}
exports.load = function(){
  if(waiting) return waiting;
  waiting = Promise.resolve().then(function(){
    return checked(require('$:/plugins/huwiki/abc/vendor/abcjs.js'));
  }).catch(function(error){waiting=null;throw error;});
  return waiting;
};
// A retry needs a fresh private sample cache after a rejected sample promise.
// The native factory reuses the same bundled source without eval or extra scripts.
exports.createAudioLibrary = function(){
  var ABC=checked(require('$:/plugins/huwiki/abc/vendor/abcjs.js'));
  if(typeof ABC.huwikiCreateAudioLibrary !== 'function')throw new Error('ABCJS lydfabrik mangler.');
  return checked(ABC.huwikiCreateAudioLibrary());
};
exports.header = function(abc,code){
  var match=String(abc||"").match(new RegExp("^"+code+":\\s*(.*)$","m"));
  return match ? match[1].trim() : "";
};
exports.putHeader = function(abc,code,value){
  abc=String(abc||"");
  value=String(value||"").replace(/[\r\n]/g," ").trim();
  var re=new RegExp("^"+code+":.*$","m");
  if(re.test(abc))return abc.replace(re,code+": "+value);
  var k=abc.search(/^K:.*$/m);
  if(k>=0)return abc.slice(0,k)+code+": "+value+"\n"+abc.slice(k);
  return abc.replace(/\s*$/,"\n")+code+": "+value+"\n";
};
exports.tempoWithBpm = function(current,bpm){
  current=String(current||"");
  if(/=\s*\d+/.test(current))return current.replace(/(=\s*)\d+/,function(_,prefix){return prefix+bpm;});
  if(/^\d+$/.test(current.trim()))return String(bpm);
  return "1/4="+bpm;
};
exports.getSource = function(wiki,title){
  var t=wiki.getTiddler(title);
  if(!t)return "";
  if(t.fields["abc-source"])return t.fields["abc-source"];
  if((t.fields.type==="text/vnd.abc" || t.fields.type==="text/plain") && /(^|\n)X:\s*\d+/m.test(t.fields.text||""))return t.fields.text;
  return "";
};
exports.fileName = function(s){
  return String(s||"musik").replace(/[^\w\u00c0-\u024f\u1e00-\u1eff-]+/g,"-").replace(/^-+|-+$/g,"").slice(0,90)||"musik";
};
exports.download = function(data,name,type){
  var blob=data instanceof Blob ? data : new Blob([data],{type:type||"application/octet-stream"});
  var url=URL.createObjectURL(blob);
  var link=document.createElement("a");link.href=url;link.download=name;
  document.body.appendChild(link);link.click();link.remove();
  setTimeout(function(){URL.revokeObjectURL(url);},30000);
};
})();
