 if(this._toggleFocusPending){this._toggleFocusPending=false;try{control.focus({preventScroll:true});}catch(ignore){control.focus();}}
};
// A small example has its own light renderer, with the same audio engine.
ABCWidget.prototype.drawMinimal=function(tiddler,source,renderToken){
 var self=this,host=this.host,view=this._scoreView,minimalABC=null;
 self._refreshMusic=function(current,plan){
  if(!minimalABC||!self._minimalPlayer)return;
  var prepared=ScoreView.prepare(minimalABC,tools.getSource(self.wiki,self.title),current.fields,view);
  var displayed=I18n.localizedSource(prepared.source,prepared.fields,I18n.language(self.wiki));
  self._minimalPlayer.update(prepared.fields,displayed,plan);
 };
 if(!tiddler||!source){host.appendChild(el('p','huwabc-error','Ingen ABC-kilde fundet.'));return;}
 var body=el('div','huwabc-minimal-content');host.appendChild(body);
 var wait=el('span','huwabc-minimal-loading','Indlæser noder …');body.appendChild(wait);
 tools.load().then(function(ABC){return (tiddler.fields['abc-font']==='petaluma'?jazzFont.ready(document):Promise.resolve()).then(function(){return ABC;});}).then(function(ABC){
  if(!host.isConnected||renderToken!==self._renderToken)return;
  var current=self.wiki.getTiddler(self.title)||tiddler;
  minimalABC=ABC;var prepared=ScoreView.prepare(ABC,tools.getSource(self.wiki,self.title),current.fields,view);
  var displayed=I18n.localizedSource(prepared.source,prepared.fields,I18n.language(self.wiki));
  body.textContent='';
  self._minimalPlayer=MinimalPlayer.mount(body,{ABC:ABC,source:displayed,fields:prepared.fields,wiki:self.wiki,audio:view.audio,showTitle:view.showTitle,
   controlsHost:self._minimalControlsHost,shortcutHost:host,paged:self._standaloneView&&!view.range,state:self._viewState,
   isCurrent:function(){return host.isConnected&&renderToken===self._renderToken;}});
  self._updateMixer=function(fields){if(self._minimalPlayer)self._minimalPlayer.updateConfig(Object.assign(accompaniment.read(fields),view.range?{repeatCounts:{}}:{}));};
  if(prepared.excerpt){host.setAttribute('data-huwabc-from',prepared.excerpt.start);host.setAttribute('data-huwabc-count',prepared.excerpt.count);}
 }).catch(function(error){if(host.isConnected&&renderToken===self._renderToken){body.textContent='';body.appendChild(el('p','huwabc-error',error.message));}});
};
ABCWidget.prototype.refresh=function(changes){
  var attrs=this.computeAttributes(),attributeChanged=Object.keys(attrs).length>0;
  if(this._viewState)this._viewState.refresh(changes);
  if(attributeChanged||changes['$:/language']){this.refreshSelf();return true;}
  var current=this.wiki.getTiddler(this.title),before=this._renderFields;
  var soundfont=!!(changes['$:/config/huwiki/abc/soundfont']||changes['$:/config/huwiki/abc/reserve-base']);
  var chordDefault=!!changes['$:/config/huwiki/abc/chords-style'];
  if(!changes[this.title]&&!soundfont&&!chordDefault)return false;
  if(!current||!before||!RefreshPolicy.source(current.fields)||!RefreshPolicy.source(before)||this._viewError){this.refreshSelf();return true;}
  // A saved view change is structural only when it changes this instance.
  var resolved;
  try{resolved=ScoreView.resolve(this._viewAttributes,current.fields);if(this._standaloneView)resolved.audio=true;}
  catch(error){this.refreshSelf();return true;}
  if(JSON.stringify(resolved)!==JSON.stringify(this._scoreView)){this.refreshSelf();return true;}
  var plan=RefreshPolicy.plan(before,current.fields);
  if(soundfont)plan.audio=true;
  if(chordDefault&&!current.fields['abc-chords-style'])plan.score=true;
  this._renderFields=current.fields;
  if(this._refreshMusic)this._refreshMusic(current,plan);
  return !!(plan.score||plan.audio||plan.live||plan.controls||plan.pages);
};
exports["huwiki-abc"]=ABCWidget;
})();
","type":"application/javascript","module-type":"widget"},"$:/plugins/huwiki/abc/import-widget.js":{"title":"$:/plugins/huwiki/abc/import-widget.js","text":"/*\
title: $:/plugins/huwiki/abc/import-widget.js
type: application/javascript
module-type: widget
\*/
(function(){
"use strict";
var I18n=require('$:/plugins/huwiki/abc/i18n.js');
var Entry=require('$:/plugins/huwiki/abc/entry-model.js');
var Widget=require("$:/core/modules/widgets/widget.js").widget;
var tools=require("$:/plugins/huwiki/abc/loader.js");
function element(name,cls,text){var e=document.createElement(name);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function btn(name,fn){var e=element("button","huwabc-btn",name);e.type="button";e.addEventListener("click",fn);return e;}
function Importer(parseTreeNode,options){this.initialise(parseTreeNode,options);}
Importer.prototype=new Widget();
Importer.prototype.execute=function(){};
Importer.prototype.onDestroy=function(){if(this._localeObserver){this._localeObserver.destroy();this._localeObserver=null;}};
Importer.prototype.render=function(parent,nextSibling){
  this.parentDomNode=parent;this.computeAttributes();this.execute();
  var box=element("section","huwabc-importer");parent.insertBefore(box,nextSibling);this.domNodes.push(box);this._localeObserver=I18n.observe(box,this.wiki);
  var self=this,parsed=[],origin="",selected={},revision=0,analysedSource=null;
  function tr(value){return I18n.translate(value,I18n.language(self.wiki));}
  box.appendChild(element("h3","","Importér ABC-melodier"));
  box.appendChild(element("p","huwabc-muted","Indsæt ABC-tekst eller vælg en .abc-fil. En samling med mange melodier deles automatisk op i enkelte musik-tiddlere."));
  var originLabel=element("label","huwabc-field");originLabel.appendChild(element("span","","Kildeadresse (valgfri)"));
  var originField=element("input","huwabc-input");originField.placeholder="https://… (til kildeangivelse, ikke automatisk download)";originLabel.appendChild(originField);box.appendChild(originLabel);
  var area=element("textarea","huwabc-code");area.rows=7;area.placeholder="X:1\nT:Min melodi\nM:4/4\nL:1/4\nK:C\nC D E F | G4 |]";box.appendChild(area);
  function invalidate(){revision++;parsed=[];selected={};analysedSource=null;result.textContent="";}
  area.addEventListener("input",function(){invalidate();msg.textContent="Teksten er ændret. Klik Analysér samling igen.";});
  var fileLine=element("div","huwabc-import-row");
  var file=element("input","huwabc-file");file.type="file";file.accept=".abc,text/plain,text/vnd.abc,.txt";
  file.addEventListener("change",function(){
    if(!file.files || !file.files[0])return;
    invalidate();var fileRevision=revision;
    var fr=new FileReader();fr.onload=function(){if(fileRevision!==revision)return;area.value=String(fr.result||"");invalidate();msg.textContent="Fil indlæst. Klik Analysér samling.";};
    fr.onerror=function(){if(fileRevision===revision)msg.textContent="Filen kunne ikke læses. Vælg den igen.";};
    fr.readAsText(file.files[0],"UTF-8");
  });fileLine.appendChild(file);
  var status=element("p","huwabc-muted");
  var result=element("div","huwabc-import-list");
  var msg=element("span","huwabc-muted","");
  fileLine.appendChild(btn("Analysér samling",function(){
    invalidate();var analysisRevision=revision,input=area.value;
    tools.load().then(function(ABC){
      if(analysisRevision!==revision||input!==area.value)return;
      var abc=input.trim();if(!abc){msg.textContent="Indsæt først ABC-tekst.";return;}
      if(!/^X:\s*\d+/m.test(abc))abc="X:1\n"+abc;
      var book=new ABC.TuneBook(abc);
      parsed=(book.tunes||[]).map(function(t,index){
        var source=t.abc||"",sourceTitle=tools.header(source,"T")||t.title;
        return {index:index,source:source,title:sourceTitle||(tr("Melodi")+" "+(index+1)),generatedTitle:!sourceTitle,key:tools.header(source,"K"),meter:tools.header(source,"M"),rhythm:tools.header(source,"R")};
      });
      if(!parsed.length){msg.textContent="Ingen melodier fundet. Prøv en ABC-fil med X:, T: og K:.";return;}
      analysedSource=input;selected={};result.innerHTML="";
      parsed.forEach(function(item){
        selected[item.index]=true;
        var row=element("label","huwabc-import-tune");var check=element("input");check.type="checkbox";check.checked=true;
        check.addEventListener("change",function(){selected[item.index]=check.checked;});row.appendChild(check);
        var info=element("span","huwabc-import-text");info.appendChild(element("strong","",item.title));
        info.appendChild(element("small","",[item.rhythm,item.key,item.meter].filter(Boolean).join(" · ")||"ABC-melodi"));row.appendChild(info);result.appendChild(row);
      });
      msg.textContent=parsed.length+" melodier fundet.";
    }).catch(function(e){if(analysisRevision===revision)msg.textContent="Kunne ikke læse ABC: "+e.message;});
  }));
  fileLine.appendChild(msg);box.appendChild(fileLine);box.appendChild(result);
  var actions=element("div","huwabc-import-row");
  actions.appendChild(btn("Importér valgte melodier",function(){
    if(analysedSource!==area.value){invalidate();msg.textContent="Analysér den aktuelle ABC-tekst før import.";return;}
    if(!parsed.length){msg.textContent="Analysér først en ABC-fil.";return;}
    origin=originField.value.trim();var created=0,duplicates=0;
    parsed.forEach(function(item){
      if(!selected[item.index])return;
      var existing=self.wiki.filterTiddlers("[has[abc-source]]").some(function(title){return tools.getSource(self.wiki,title).trim()===item.source.trim();});
      if(existing){duplicates++;return;}
      var base=item.generatedTitle?tr("Melodi")+" "+(item.index+1):(item.title||tr("ABC-melodi"));var title=base,num=2;
      while(self.wiki.tiddlerExists(title)||self.wiki.isShadowTiddler(title)){title=base+" ("+num+++")";}
      var fields={title:title,type:"text/vnd.tiddlywiki",tags:"ABC Musik","abc-source":item.source,"abc-layout":"standard","abc-rhythm":item.rhythm,"abc-key":item.key,"abc-meter":item.meter,"abc-origin-url":origin,created:new Date(),modified:new Date(),text:"!! "+tr("Mine øvenoter")+"\n\n"+tr("Skriv her, hvad du vil øve, og hvad du har lært.")+"\n"};
      self.wiki.addTiddler(new $tw.Tiddler(fields));created++;
    });
    msg.textContent=created+" melodier importeret"+(duplicates?" · "+duplicates+" identiske melodier sprunget over":"")+". De findes nu under tagget ABC.";
  }));
  var blankOptions=element('div','huwabc-blank-options');
  var blankKind=element('select','huwabc-select');blankKind.setAttribute('aria-label',tr('Stemmer'));
  [['one','En stemme'],['voices','To stemmer på samme system'],['staves','To nodesystemer']].forEach(function(pair){var o=element('option','',tr(pair[1]));o.value=pair[0];blankKind.appendChild(o);});blankOptions.appendChild(blankKind);
  var blankMeter=element('select','huwabc-select');blankMeter.setAttribute('aria-label',tr('Taktart'));['4/4','3/4','2/4','6/8','7/8','9/8','11/8','5/4'].forEach(function(v){var o=element('option','',v);o.value=v;blankMeter.appendChild(o);});blankOptions.appendChild(blankMeter);box.appendChild(blankOptions);var blankHelp=element('p','huwabc-muted',tr('Vælg stemmer og taktart før Ny tom melodi. Det nye ark har fire tomme takter.'));box.appendChild(blankHelp);
  actions.appendChild(btn("Ny tom melodi",function(){
    var base=tr("Min nye melodi"),title=base,number=2;
    while(self.wiki.tiddlerExists(title)||self.wiki.isShadowTiddler(title))title=base+" ("+number+++")";
    var abc=Entry.starter(title,blankMeter.value,blankKind.value);
    self.wiki.addTiddler(new $tw.Tiddler({title:title,type:"text/vnd.tiddlywiki",tags:"ABC Musik","abc-source":abc,"abc-layout":"standard",text:"!! "+tr("Mine øvenoter")+"\n\n",created:new Date(),modified:new Date()}));
    msg.textContent=tr("Melodien '{title}' er oprettet. Find den i listen nedenfor og tryk Redigér noder.").replace("{title}",function(){return title;});self.dispatchEvent({type:'tm-edit-tiddler',param:title,tiddlerTitle:title});
  }));
  box.appendChild(actions);box.appendChild(status);
};
Importer.prototype.refresh=function(){return false;};
exports["huwiki-abc-importer"]=Importer;
})();
","type":"application/javascript","module-type":"widget"},"$:/plugins/huwiki/abc/styles.css":{"title":"$:/plugins/huwiki/abc/styles.css","text":"/* HUWiki ABC v0.1.3 – styles confined to this plugin */
.huwabc-score,.huwabc-importer,.huwabc-hub{font:inherit;color:inherit;box-sizing:border-box}
.huwabc-score{margin:1.1rem 0 1.5rem;border:1px solid rgba(95,114,131,.18);border-radius:18px;overflow:visible;background:var(--huw-abc-bg,#fff);box-shadow:0 5px 30px rgba(22,43,59,.06)}
.huwabc-head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;padding:14px 18px;background:#f6f8f8;border-bottom:1px solid #e7ebec}
.huwabc-head-label{font-size:10px;font-weight:800;letter-spacing:.15em;color:#42736f}
.huwabc-actions{display:flex;flex-wrap:wrap;gap:6px;justify-content:flex-end}
.huwabc-btn{font:inherit;font-size:12px;font-weight:650;background:#fff;color:#243e3b;border:1px solid #dce5e2;border-radius:9px;padding:8px 11px;cursor:pointer;line-height:1.35}
.huwabc-btn:hover,.huwabc-btn:focus-visible{background:#eaf3f0;outline:2px solid #95cec2;outline-offset:1px}
.huwabc-btn.huwabc-primary{background:#276c63;color:white;border-color:#276c63}
.huwabc-btn.huwabc-primary:hover{background:#1e514b}
.huwabc-paper{background:#fff;color:#111;padding:clamp(10px,3vw,30px);overflow-x:auto;min-height:70px;border-radius:0 0 18px 18px;scroll-margin-top:130px}
.huwabc-paper svg{width:100%;max-width:100%;height:auto;color:#111;overflow:visible}
.huwabc-status{font-size:12px;padding:2px 20px 11px;color:#66807d;min-height:18px}
.huwabc-status.huwabc-error{color:#ab3333}
/* Permanent and sticky ABCJS player. Always visible while the music sheet is on screen. */
.huwabc-audio{position:sticky;top:0;z-index:20;padding:10px clamp(10px,2.5vw,18px) 12px;border-bottom:1px solid #bfd8ce;background:rgba(242,250,247,.98);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);box-shadow:0 4px 14px rgba(34,67,60,.09)}
.huwabc-audio-caption{display:flex;align-items:center;gap:12px;margin:0 0 5px;flex-wrap:wrap;color:#34544d}
.huwabc-audio-label{font-weight:800;font-size:12px;letter-spacing:.04em}
.huwabc-audio-hint{font-size:11px;color:#647f79}
.huwabc-audio-controls .abcjs-inline-audio{display:flex;gap:7px;flex-wrap:wrap;align-items:center;padding:0;background:none;color:#214d45;height:auto;min-height:42px;box-sizing:border-box}
.huwabc-audio-controls .abcjs-inline-audio.abcjs-disabled{opacity:.65}
.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn{display:inline-flex;gap:6px;align-items:center;justify-content:center;box-sizing:border-box;background:#fff!important;color:#24544c;border:1px solid #bed7cc!important;min-height:41px;height:41px;min-width:88px;border-radius:11px;padding:7px 11px;font:inherit;font-size:13px;font-weight:700;line-height:1;cursor:pointer;opacity:1}
.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn:hover{background:#e9f4ef!important}
.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn:focus-visible{outline:2px solid #2c806a;outline-offset:2px}
.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn.abcjs-pushed{background:#d5eee4!important;border-color:#528e7b!important}
/* Hide the small built-in SVGs; the custom icons give consistent visual meaning on iPad and desktop. */
.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn svg:not(.huwabc-icon){display:none!important}
.huwabc-audio-controls .huwabc-icon{display:block!important;width:20px;height:20px;flex:none}
.huwabc-audio-controls .abcjs-midi-start .huwabc-icon-pause,.huwabc-audio-controls .abcjs-midi-start .huwabc-control-label-pause{display:none!important}
.huwabc-audio-controls .abcjs-midi-start.abcjs-pushed .huwabc-icon-play,.huwabc-audio-controls .abcjs-midi-start.abcjs-pushed .huwabc-control-label{display:none!important}
.huwabc-audio-controls .abcjs-midi-start.abcjs-pushed .huwabc-icon-pause,.huwabc-audio-controls .abcjs-midi-start.abcjs-pushed .huwabc-control-label-pause{display:block!important}
.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn.abcjs-midi-start{background:#236e5e!important;color:white!important;border-color:#236e5e!important}
.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn.abcjs-midi-start:hover{background:#1a584a!important}
.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn.abcjs-midi-start.abcjs-pushed{background:#155646!important;color:white!important}
.huwabc-audio-controls .abcjs-midi-progress-background{position:relative;flex:1;min-width:84px;height:11px;border-radius:9px;border:1px solid #91b8ab;background:#d7e8e1;margin:0 5px;padding:0;box-sizing:border-box;cursor:pointer}
.huwabc-audio-controls .abcjs-midi-progress-indicator{position:absolute;left:0;top:-6px;width:18px;height:20px;margin-left:-9px;background:#257261;border:2px solid white;border-radius:9px;box-shadow:0 1px 3px #537e70;box-sizing:border-box}
.huwabc-audio-controls .abcjs-midi-clock{font:600 12px/1.25 system-ui,sans-serif;white-space:nowrap;color:#315f56;margin:0 3px}
.huwabc-audio-controls .abcjs-tempo-wrapper{display:flex;gap:4px;align-items:center;white-space:nowrap;color:#305e55;font:600 12px/1.25 system-ui,sans-serif}
.huwabc-audio-controls .abcjs-midi-tempo{font:600 13px system-ui,sans-serif;min-width:50px;max-width:58px;padding:7px 4px;border:1px solid #bed7cc;border-radius:7px;background:white;color:#24544c;text-align:center;box-sizing:border-box}
.huwabc-audio-controls .abcjs-css-warning{display:none!important}
.huwabc-player-wait{font-size:12px;color:#526d65}
.huwabc-paper .huwabc-playing-note path,.huwabc-paper .huwabc-playing-note ellipse,.huwabc-paper .huwabc-playing-note polygon{fill:#11845c!important;stroke:#11845c!important}
.huwabc-paper .huwabc-follow-line{stroke:#178665;stroke-width:2.5;stroke-linecap:round;pointer-events:none;opacity:.82}

.huwabc-editor{padding:21px;background:#f5f7f6;border-top:1px solid #e1e8e4}
.huwabc-editor h3,.huwabc-importer h3{margin:0 0 6px;font-size:20px;color:#193b35}
.huwabc-muted{color:#657a77;font-size:13px;line-height:1.55;margin:5px 0 13px}
.huwabc-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:12px;margin:15px 0}
.huwabc-field{display:flex;flex-direction:column;gap:5px;font-weight:650;font-size:12px;color:#3c5b57}
.huwabc-input,.huwabc-select,.huwabc-code{font:inherit;box-sizing:border-box;border:1px solid #cfdcd8;border-radius:10px;background:#fff;color:#1c3131;padding:9px 10px;width:100%;max-width:100%}
.huwabc-code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:13px;line-height:1.6;min-height:125px;resize:vertical}
.huwabc-code-label{margin:12px 0 8px;display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.huwabc-insert-tools{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px}
.huwabc-insert-tools .huwabc-token{min-width:33px;padding:5px 8px}
.huwabc-editor-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:12px}
.huwabc-importer{padding:20px;background:#f7faf8;border:1px solid #dfebe6;border-radius:15px;margin:15px 0 23px}
.huwabc-importer .huwabc-code{margin:10px 0 4px}
.huwabc-import-row{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:12px 0}
.huwabc-file{font:inherit;font-size:12px;max-width:100%}
.huwabc-import-list{max-height:250px;overflow:auto}
.huwabc-import-tune{display:flex;align-items:center;gap:12px;background:#fff;padding:10px 12px;margin:5px 0;border:1px solid #e1eae6;border-radius:9px}
.huwabc-import-text{display:flex;flex-direction:column;gap:3px}
.huwabc-import-text small{font-size:11px;color:#698580}
.huwabc-hub{max-width:1000px;margin:0 auto}
.huwabc-hub-head{padding:20px;border-radius:16px;background:#e8f4ee;margin-bottom:14px}
.huwabc-hub-head h2{margin:2px 0;font-size:26px;color:#1c4c43}
.huwabc-collection{padding-left:0;list-style:none}
.huwabc-collection li{border-bottom:1px solid #dde4e1;padding:9px 0}
@media(max-width:700px){.huwabc-head{align-items:stretch}.huwabc-actions{justify-content:flex-start}.huwabc-fields{grid-template-columns:1fr 1fr}.huwabc-btn{font-size:12px}.huwabc-paper{padding:8px}.huwabc-audio-hint{display:none}.huwabc-audio-controls .abcjs-inline-audio{gap:5px}.huwabc-audio-controls .abcjs-inline-audio .abcjs-btn{min-width:64px;padding:7px 9px;font-size:12px}.huwabc-audio-controls .abcjs-midi-progress-background{flex-basis:110px}.huwabc-audio{top:0;padding:8px 9px 10px}}
@media print{.huwabc-head,.huwabc-editor,.huwabc-audio,.huwabc-status,.huwabc-importer{display:none!important}.huwabc-score{box-shadow:none;border:0;margin:0}.huwabc-paper{padding:0;overflow:visible}}

/* v0.1.4: compact, anchored player BELOW the music – never a separate tab. */
.huwabc-score .huwabc-paper{border-radius:0;}
.huwabc-score .huwabc-audio{position:sticky;top:auto;bottom:0;z-index:19;padding:6px 12px 7px;background:rgba(249,252,250,.98);border-top:1px solid #d6e5df;border-bottom:0;box-shadow:0 -3px 14px rgba(28,66,52,.08)}
.huwabc-score .huwabc-audio-caption{display:none;}
.huwabc-score .huwabc-audio-controls .abcjs-inline-audio{min-height:30px;height:auto;gap:5px;flex-wrap:wrap;}
.huwabc-score .huwabc-audio-controls .abcjs-inline-audio .abcjs-btn{height:30px;min-height:30px;min-width:0;padding:4px 8px;border-radius:7px;font-size:11px;font-weight:650;gap:5px;}
.huwabc-score .huwabc-audio-controls .huwabc-icon{width:15px;height:15px;}
.huwabc-score .huwabc-audio-controls .abcjs-midi-clock,.huwabc-score .huwabc-audio-controls .abcjs-tempo-wrapper{font-size:11px;}
.huwabc-score .huwabc-audio-controls .abcjs-midi-tempo{font-size:11px;min-width:40px;max-width:45px;padding:3px 3px;}
