.huwabc-score .huwabc-settings-panel>summary::-webkit-details-marker{display:none}
.huwabc-score .huwabc-settings-panel>summary:before{content:'＋';margin-right:8px;font-size:16px;font-weight:400}
.huwabc-score .huwabc-settings-panel[open]>summary:before{content:'−'}
.huwabc-score .huwabc-settings-body{display:grid;grid-template-columns:1fr;gap:7px;margin-bottom:10px}
.huwabc-score .huwabc-learn-panels{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding:11px 16px 15px;border-top:1px solid #eaf0eb}
.huwabc-score .huwabc-learn-panel{border:1px solid #deebe3;border-radius:11px;background:#fbfdfb;padding:10px 13px;min-width:0}
.huwabc-score .huwabc-learn-panel[open]{grid-column:span 2;background:#fff}
.huwabc-score .huwabc-learn-panel>summary{list-style:none;cursor:pointer;color:#265c4d;font-size:13px;font-weight:700;position:relative;padding-right:18px}
.huwabc-score .huwabc-learn-panel>summary::-webkit-details-marker{display:none}
.huwabc-score .huwabc-learn-panel>summary:after{content:'＋';position:absolute;right:0;top:0;font-size:17px;font-weight:400}
.huwabc-score .huwabc-learn-panel[open]>summary:after{content:'−'}
.huwabc-score .huwabc-learn-hint{font-size:12px;color:#617d6c;margin:11px 0;line-height:1.55}
.huwabc-score .huwabc-abc-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:9px}
.huwabc-score .huwabc-readable-abc{background:#f5f9f6!important;color:#183e30!important;-webkit-text-fill-color:#183e30!important;border:1px solid #dceae0!important;border-radius:9px;width:100%;box-sizing:border-box;min-height:170px;max-height:330px;resize:vertical;padding:12px;font:12px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace}
.huwabc-score select,.huwabc-score select option,.huwabc-score input[type=number]{color:#183d31!important;-webkit-text-fill-color:#183d31!important;background-color:#fff!important}
.huwabc-score .huwabc-mix-channel{background:#f7faf8;border:1px solid #e1eee6;border-radius:10px;padding:10px;min-width:0}
.huwabc-score .huwabc-mix-setting{display:flex;flex-direction:column;gap:5px;margin-top:8px}
.huwabc-score .huwabc-mix-setting select{width:100%;max-width:100%;min-width:0;min-height:32px}
.huwabc-score .huwabc-paper .abcjs-chord{cursor:pointer}
.huwabc-score .huwabc-paper .abcjs-chord:hover{fill:#138b70!important}
@media(max-width:700px){.huwabc-score .huwabc-learn-panels{grid-template-columns:1fr;padding:10px}.huwabc-score .huwabc-learn-panel[open]{grid-column:span 1}.huwabc-score .huwabc-quick-settings{padding:3px 10px}.huwabc-score .huwabc-settings-panel{margin:0 10px 8px}.huwabc-score .huwabc-audio{margin:0 8px 8px!important;padding:8px!important}.huwabc-score .huwabc-head{padding:10px}}
@media print{.huwabc-quick-settings,.huwabc-settings-panel,.huwabc-learn-panels{display:none!important}}

/* v0.3.3 – a piano that follows the current staff, not the page scroll */
.huwabc-floating-keyboard{position:fixed;z-index:10020;max-width:calc(100vw - 24px);padding:10px 12px 12px;border-radius:14px;border:1px solid #bdd9cc;background:rgba(250,253,251,.97);color:#21483c;box-shadow:0 15px 48px rgba(22,55,45,.23);backdrop-filter:blur(10px)}
.huwabc-floating-keyboard[hidden]{display:none!important}
.huwabc-floating-header{display:flex;justify-content:space-between;align-items:center;gap:10px;font:12px/1.3 system-ui,sans-serif;margin-bottom:5px}
.huwabc-floating-header button{border:1px solid #cbdcd1;border-radius:8px;background:#fff;color:#275f4a;font:12px system-ui;padding:3px 9px;cursor:pointer}
.huwabc-floating-keyboard .huwabc-keys{height:86px}
.huwabc-floating-keyboard .huwabc-piano-toolbar{margin:0 0 5px;gap:4px}
.huwabc-floating-keyboard .huwabc-piano-toolbar>strong{display:none}
.huwabc-floating-keyboard .huwabc-piano-settings{gap:7px}
.huwabc-floating-keyboard .huwabc-piano-select{font-size:11px!important;min-height:27px}
@media(max-width:620px){.huwabc-floating-keyboard{padding:7px 8px 9px}.huwabc-floating-keyboard .huwabc-keys{height:65px}.huwabc-floating-keyboard .huwabc-piano-toolbar{font-size:10px}}
@media print{.huwabc-floating-keyboard{display:none!important}}

/* v0.3.5 · selected starting note/chord, no additional toolbar controls */
.huwabc-paper .huwabc-cue-selected,
.huwabc-paper .huwabc-cue-selected *{stroke:#1d84ac!important;fill:#1d84ac!important}
.huwabc-paper .huwabc-cue-selected.abcjs-chord,
.huwabc-paper .huwabc-cue-selected.abcjs-chord *{stroke:none!important;fill:#1d84ac!important}

/* v0.3.6 · gentagelse skal kunne aflæses på både Mac og iPad. */
.huwabc-score .abcjs-midi-loop.abcjs-pushed,
.huwabc-score .abcjs-midi-loop[aria-pressed="true"]{
 background:#217b62!important;border-color:#185d4a!important;color:#fff!important;
 box-shadow:0 0 0 2px rgba(27,120,88,.18)!important;opacity:1!important;
}
.huwabc-score .abcjs-midi-loop.abcjs-pushed svg,
.huwabc-score .abcjs-midi-loop[aria-pressed="true"] svg{color:#fff!important;fill:currentColor!important;}
.huwabc-score .abcjs-midi-loop:focus-visible{outline:3px solid #b5e8d4;outline-offset:2px;}

/* 0.3.21-test.2: stable transport and tempo rows.
   Layout depends on the available player width, never on the current tempo
   label, pressed/disabled state, playback time or Play/Pause label.
   The narrow layout is the safe fallback without container-query support. */
.huwabc-score .huwabc-audio-controls {
 display:grid;
 grid-template-columns:minmax(0,1fr);
 align-items:center;
 gap:8px;
 min-width:0;
 container-type:inline-size;
 container-name:huwabc-player;
}
.huwabc-score .huwabc-audio-controls .abcjs-inline-audio {
 display:grid;
 grid-template-columns:repeat(3,minmax(0,1fr)) 4.8em;
 grid-template-areas:"loop restart play stop" "progress progress progress clock";
 align-items:center;
 gap:8px 6px;
 width:100%;
 min-width:0;
 min-height:32px;
 height:auto;
 margin:0;
 padding:0;
 font-size:11px;
 box-sizing:border-box;
}
.huwabc-score .huwabc-audio-controls .abcjs-midi-loop {grid-area:loop}
.huwabc-score .huwabc-audio-controls .abcjs-midi-reset {grid-area:restart}
.huwabc-score .huwabc-audio-controls .abcjs-midi-start {grid-area:play}
.huwabc-score .huwabc-audio-controls .huwabc-stop {grid-area:stop}
.huwabc-score .huwabc-audio-controls .abcjs-inline-audio .abcjs-btn,
.huwabc-score .huwabc-audio-controls .abcjs-inline-audio .huwabc-stop {
 width:100%;
 min-width:0;
 height:32px;
 min-height:32px;
 margin:0;
 padding:4px 6px;
 box-sizing:border-box;
 white-space:nowrap;
 font-size:11px;
}
.huwabc-score .huwabc-audio-controls .abcjs-midi-progress-background {
 grid-area:progress;
 min-width:0;
 width:calc(100% - 14px);
 margin:0 7px;
}
.huwabc-score .huwabc-audio-controls .abcjs-midi-clock {
 grid-area:clock;
 display:block;
 min-width:0;
 width:100%;
 margin:0;
 text-align:center;
 white-space:nowrap;
 font-variant-numeric:tabular-nums;
}
.huwabc-score .huwabc-audio-controls .huwabc-tempo-modes {
 display:grid;
 grid-template-columns:max-content max-content 70px minmax(0,1fr);
 align-items:center;
 gap:6px 8px;
 width:100%;
 min-width:0;
 margin:0;
 font-size:12px;
}
.huwabc-score .huwabc-audio-controls .huwabc-tempo-modes > button,
.huwabc-score .huwabc-audio-controls .huwabc-tempo-modes > select {
 height:32px;
 min-height:32px;
 margin:0;
 padding:4px 10px;
 box-sizing:border-box;
 white-space:nowrap;
}
.huwabc-score .huwabc-audio-controls .huwabc-tempo-status {
 grid-column:1 / -1;
 min-width:0;
 line-height:1.5;
 min-height:1.5em;
 white-space:nowrap;
 font-variant-numeric:tabular-nums;
}
/* Text-only transport buttons on very narrow embedded/phone layouts. */
@container huwabc-player (max-width:300px) {
 .huwabc-score .huwabc-audio-controls .abcjs-inline-audio .huwabc-icon {display:none!important}
}
@container huwabc-player (min-width:400px) {
 .huwabc-score .huwabc-audio-controls .huwabc-tempo-status {grid-column:4;grid-row:1}
}
@container huwabc-player (min-width:540px) {
 .huwabc-score .huwabc-audio-controls .abcjs-inline-audio {
  grid-template-columns:7.5em 7.5em 7.5em minmax(0,1fr) 7ch 4.8em;
  grid-template-areas:"loop restart play progress clock stop";
 }
}
@media (pointer:coarse) {
 .huwabc-score .huwabc-audio-controls .abcjs-inline-audio .abcjs-btn,
 .huwabc-score .huwabc-audio-controls .abcjs-inline-audio .huwabc-stop,
 .huwabc-score .huwabc-audio-controls .huwabc-tempo-modes > button,
 .huwabc-score .huwabc-audio-controls .huwabc-tempo-modes > select {height:40px;min-height:40px}
}

