.huwabc-score .huwabc-transport-keyhint{display:block;grid-column:1 / -1;order:3;font:10px/1.4 system-ui;color:#587366;min-height:14px;white-space:nowrap;padding:0 1px}

.huwabc-voice-name-grid{display:grid;gap:10px;margin:10px 0}.huwabc-voice-name-row{display:grid;grid-template-columns:3.5em minmax(100px,1fr) minmax(90px,.7fr);gap:8px;align-items:end}.huwabc-voice-name-row>strong{font:600 12px system-ui;align-self:center;overflow-wrap:anywhere}.huwabc-voice-names .huwabc-muted{margin:8px 0}.huwabc-voice-names .huwabc-input{min-width:0}

/* 0.3.26-test.1 · Persistent source location for every floating-editor target.
   The transparent textarea remains the ONLY editable ABC field. */
