}
/* Native selection remains possible while typing; it does not replace the persistent mark. */
.huwabc-source-editor textarea.huwabc-code::selection{background:rgba(56,139,111,.20);color:transparent;}

/* Concert-pitch audio and selectable written-pitch notation (v0.3.28). */
.huwabc-instrument-bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;padding:9px 16px;background:#f4f8f6;border-bottom:1px solid #dde8e3}
