.huwabc-instrument-option{font:700 13px/1.3 system-ui,sans-serif;min-width:48px;min-height:40px;padding:8px 12px;color:#24544c;background:#fff;border:0;border-right:1px solid #bdd8ce;cursor:pointer}
.huwabc-instrument-option:last-child{border-right:0}
.huwabc-instrument-option[aria-pressed=true]{background:#256e5d;color:white}
.huwabc-instrument-option:focus-visible{outline:3px solid #47b2a5;outline-offset:-3px;position:relative;z-index:1}
.huwabc-instrument-hint{font-size:11px;color:#56746d}
.huwabc-instrument-print{margin-left:auto;min-height:40px}
