@media(max-width:600px){.huwabc-instrument-bar{padding:8px}.huwabc-instrument-group{gap:6px}.huwabc-instrument-option{min-width:42px;min-height:40px;padding:7px 10px}.huwabc-instrument-hint{flex-basis:100%}}
