function line(g,x1,y1,x2,y2,width){g.appendChild(E(g.ownerDocument,'line',{x1:x1,y1:y1,x2:x2,y2:y2,stroke:'currentColor','stroke-width':width||1.1}));}
function render(root,tune,config){if(!config.rhythm)return;var originals={};(tune.lines||[]).forEach(function(l){(l.staff||[]).filter(function(s){return s.clef.type!=='TAB';}).forEach(function(s){(s.voices||[]).forEach(function(v){v.forEach(function(e){if(e.el_type==='note')originals[e.startChar]=e;});});});});
 var rails=[];
 (tune.lines||[]).forEach(function(l){(l.staff||[]).filter(function(s){return s.clef.type==='TAB';}).forEach(function(s,tabIndex){var anchor=(s.voices||[]).flat().find(function(e){return e.notes&&!e.grace&&e.abselem;});if(!anchor)anchor=(s.voices||[]).flat().find(function(e){return e.abselem&&e.abselem.children.some(function(ch){return ch.graphelem;});});if(!anchor)return;var num=anchor.abselem.children.find(function(ch){return ch.type==='tabNumber'&&ch.graphelem;})||anchor.abselem.children.find(function(ch){return ch.graphelem;}),node=num&&num.graphelem;if(!node)return;var parent=node.closest('.huwabc-tabs-only,.abcjs-staff-wrapper');if(!parent)return;var staff;
 if(parent.classList.contains('huwabc-tabs-only'))staff=parent.querySelector('.abcjs-staff');else{var section=null;Array.from(parent.children).some(function(child){if(child.classList.contains('abcjs-staff'))section=child;if(child===node||child.contains(node)){staff=section;return true;}return false;});}
 if(!staff)return;var box=staff.getBBox(),bottom=box.y+box.height,group=E(root.ownerDocument,'g',{'class':'huwabc-tab-rhythm','aria-label':'Tabulaturens rytme','pointer-events':'none'});parent.appendChild(group);rails.push(group);
 (s.voices||[]).forEach(function(tv,voiceIndex){var y=bottom+45+voiceIndex*55,events=tv.filter(function(e){return e.notes&&!e.grace&&originals[e.startChar];}).map(function(e){return {e:originals[e.startChar],x:e.abselem.x};});
 // Rests are absent from ABCJS's tab voice: recover them from the linked source voice.
 var sourceStaff=(l.staff||[]).filter(function(st){return st.clef.type!=='TAB';})[tabIndex],originalVoice=sourceStaff&&(sourceStaff.voices||[])[voiceIndex];
 (originalVoice||[]).forEach(function(e){if(e.el_type!=='note'||!e.abselem||events.some(function(item){return item.e===e;}))return;if(e.rest&&(e.rest.type==='invisible'||e.rest.type==='spacer'))return;var head=e.abselem.heads&&e.abselem.heads[0];events.push({e:e,x:head?head.x+head.w/2:e.abselem.x+4});});events.sort(function(a,b){return a.x-b.x;});
 var beams=new Map(),ties=[],tieStart=null,tuplet=null;
 events.forEach(function(item){var e=item.e,sh=shape(e.duration),x=item.x,g=E(root.ownerDocument,'g',{'data-huwabc-rhythm-source':e.startChar,'data-duration':e.duration});group.appendChild(g);
 if(e.rest){var rn=sh.base>=1?'whole':sh.base>=.5?'half':sh.base>=.25?'quarter':Math.round(1/sh.base)+'th';glyph(g,'rests.'+rn,x-4,y-3);if(sh.base>=.5)line(g,x-6,y-3,x+6,y-3,.7);}
 else{glyph(g,'noteheads.'+(sh.base>=1?'whole':sh.base>=.5?'half':'quarter'),x-3.7,y);if(sh.base<1){line(g,x+3.5,y,x+3.5,y-25);if(sh.flags){var beam=e.abselem.beam;if(beam&&!beam.isgrace){if(!beams.has(beam))beams.set(beam,[]);beams.get(beam).push({x:x+3.5,n:sh.flags});}else glyph(g,'flags.u'+Math.round(1/sh.base)+'th',x+3.5,y-25);}}
 if(tieStart&&(e.pitches||[]).some(function(p){return p.endTie;})){ties.push([tieStart,x]);tieStart=null;}if((e.pitches||[]).some(function(p){return p.startTie;}))tieStart=x;}
 for(var d=0;d<sh.dots;d++)g.appendChild(E(root.ownerDocument,'circle',{cx:x+9+d*4,cy:y-2,r:1.2,fill:'currentColor'}));
 if(e.startTriplet)tuplet={x:x,n:e.startTriplet};if(e.endTriplet&&tuplet){line(group,tuplet.x,y-33,x,y-33,.7);var text=E(root.ownerDocument,'text',{x:(tuplet.x+x)/2,y:y-36,'text-anchor':'middle','font-size':10,'font-family':'serif',fill:'currentColor'});text.textContent=tuplet.n;group.appendChild(text);tuplet=null;}
 });
 beams.forEach(function(items){items.sort(function(a,b){return a.x-b.x;});var max=Math.max.apply(null,items.map(function(i){return i.n;}));for(var level=1;level<=max;level++){var run=[];function flush(){if(!run.length)return;var first=run[0],last=run[run.length-1],end=last.x;if(run.length===1){var idx=items.indexOf(first);end=first.x+(idx===items.length-1?-7:7);}line(group,first.x,y-25+(level-1)*4,end,y-25+(level-1)*4,2.5);run=[];}items.forEach(function(item){if(item.n>=level)run.push(item);else flush();});flush();}});
 ties.forEach(function(t){group.appendChild(E(root.ownerDocument,'path',{d:'M '+(t[0]+3)+' '+(y+7)+' Q '+((t[0]+t[1])/2)+' '+(y+16)+' '+(t[1]-3)+' '+(y+7),fill:'none',stroke:'currentColor','stroke-width':1}));});
 });
 });});
 // Compact tabs are laid out first; make room for each new rhythm row afterwards.
 root.querySelectorAll('svg').forEach(function(svg){var compact=Array.from(svg.querySelectorAll('.huwabc-tabs-only')),extra=0;compact.forEach(function(g){var rhythm=g.querySelector('.huwabc-tab-rhythm');if(extra)g.setAttribute('transform','translate(0,'+extra+') '+(g.getAttribute('transform')||''));if(rhythm){var b=rhythm.getBBox(),staff=g.querySelector('.abcjs-staff').getBBox();extra+=Math.max(0,b.y+b.height-(staff.y+staff.height))+14;}});
 var vb=svg.viewBox.baseVal;if(compact.length){svg.setAttribute('viewBox',[vb.x,vb.y,vb.width,vb.height+extra].join(' '));}else{var max=vb.y+vb.height;Array.from(svg.querySelectorAll('.huwabc-tab-rhythm')).forEach(function(g){var b=g.getBBox();max=Math.max(max,b.y+b.height+14);});svg.setAttribute('viewBox',[vb.x,vb.y,vb.width,max-vb.y].join(' '));}var v=svg.viewBox.baseVal;if(svg.parentElement&&svg.parentElement.style.paddingBottom)svg.parentElement.style.paddingBottom=(v.height/v.width*100)+'%';
 });
