(function(){
'use strict';
var meters={jig:'6/8','slip jig':'9/8','slide':'12/8',reel:'4/4',hornpipe:'4/4',polka:'2/4',waltz:'3/4',mazurka:'3/4',barndance:'4/4',strathspey:'4/4','three-two':'3/2',march:'4/4'};
function oneLine(v){return String(v||'').replace(/[\r\n\x00-\x1f]/g,' ').trim();}
function id(v){if(!/^\d+$/.test(String(v)))throw new Error('Ugyldigt melodi-ID.');return String(v);}
function source(t,s){return 'https://thesession.org/tunes/'+id(t.id)+(s?'#setting'+id(s.id):'');}
function abc(t,s){
 if(!s||typeof s.abc!=='string'||!s.abc.trim())throw new Error('Denne version har ingen ABC-noder.');
 var meter=meters[t.type];if(!meter)throw new Error('Ukendt taktart for '+oneLine(t.type)+'. Åbn kilden for at kontrollere notationen.');
 // Older Session settings use a lone ! as a line break. Keep !trill! etc.
 var body=s.abc.replace(/![^!\s]+!|!(?=\s|$)/g,function(v){return v==='!'?'\n':v;}).replace(/\n +/g,'\n');
 return 'X:'+id(s.id)+'\nT:'+oneLine(t.name)+'\nZ:'+oneLine(s.member&&s.member.name)+'\nS:'+source(t,s)+'\nR:'+oneLine(t.type)+'\nM:'+meter+'\nL:1/8\nK:'+oneLine(s.key)+'\n'+body+'\n';
}
exports.meters=meters;exports.abc=abc;exports.source=source;exports.oneLine=oneLine;
exports.fields=function(t,s){return {type:'text/vnd.tiddlywiki',tags:['ABC','Musik','The Session'],'abc-source':abc(t,s),'abc-bars-per-line':'4','abc-collection':'The Session','abc-source-url':source(t,s),'abc-session-tune-id':id(t.id),'abc-session-setting-id':id(s.id),'abc-transcriber':oneLine(s.member&&s.member.name),'abc-imported-at':new Date().toISOString(),text:'Importeret fra The Session. Kilde: '+source(t,s)};};
exports.uniqueTitle=function(wiki,title){var base=oneLine(title)||'Melodi fra The Session',v=base,n=2;while(wiki.tiddlerExists(v)||wiki.isShadowTiddler(v))v=base+' ('+(n++)+')';return v;};
exports.request=async function(path,signal){
 var r=await fetch('https://thesession.org'+path,{signal:signal,credentials:'omit',referrerPolicy:'no-referrer'});
 if(!r.ok)throw new Error(r.status===429?'The Session beder os vente. Prøv igen om lidt.':'The Session svarede med fejl '+r.status+'.');
 return r.json();
};
})();
"},"$:/plugins/huwiki/abc/search-widget.js":{"title":"$:/plugins/huwiki/abc/search-widget.js","type":"application/javascript","module-type":"widget","text":"(function(){
