title: $:/plugins/huwiki/abc/jazz-catalog.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
var base='https://api.github.com/repos/ian-hayden/abc-music-files/contents/';
var indexUrl=base+'Jazz%20songs';
var cached=null;
async function readJson(url,signal){
 var res=await fetch(url,{method:'GET',headers:{'Accept':'application/vnd.github+json'},signal:signal});
 if(res.status===403)throw Error('GitHubs offentlige grænse for forespørgsler er nået. Prøv senere.');
 if(!res.ok)throw Error('GitHub svarede '+res.status+'. Prøv igen.');
 return res.json();
}
function isValid(item){return item&&item.type==='file'&&!/^\./.test(item.name)&&/\.(?:abc|txt)$/i.test(item.name)||item&&item.type==='file'&&!/\./.test(item.name);}
async function list(signal){
 if(cached)return cached;
 var items=await readJson(indexUrl,signal);
 if(!Array.isArray(items))throw Error('GitHubs katalog kunne ikke læses.');
 cached=items.filter(isValid).map(function(item){return {name:item.name,title:item.name.replace(/\.(?:abc|txt)$/i,''),url:item.url,html_url:item.html_url,size:item.size};});
 return cached;
}
function decodeBase64(contents){
 var binary=atob(contents.replace(/[\r\n\s]/g,'')),bytes=new Uint8Array(binary.length);
 for(var i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
 return new TextDecoder('utf-8').decode(bytes);
}
async function fetchTune(item,signal){
 if(!item||typeof item.url!=='string'||!item.url.startsWith(base))throw Error('Ugyldig GitHub-kilde.');
 var response=await readJson(item.url,signal);
 if(response.encoding!=='base64'||!response.content)throw Error('GitHub leverede ikke ABC-teksten i et læsbart format.');
 var abc=decodeBase64(response.content);
 if(!/(^|\n)K:\s*\S/m.test(abc))throw Error('Filen indeholder ikke genkendelig ABC-notation.');
 return abc;
}
function filter(items,query){var q=String(query||'').trim().toLocaleLowerCase('da');return items.filter(function(t){return t.title.toLocaleLowerCase('da').includes(q);});}
exports.list=list;exports.fetchTune=fetchTune;exports.filter=filter;
})();
"},"$:/plugins/huwiki/abc/jazz-engine.js":{"title":"$:/plugins/huwiki/abc/jazz-engine.js","text":"/*\
title: $:/plugins/huwiki/abc/jazz-engine.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
/* HUWiki jazz arranging engine. Only playback events are changed, never the user's ABC.
 * Rhythm/arrangement choices are seeded and thus repeatable (also when looping a tune).
 * The source/part metadata is advisory; section choice is always overrideable. */
function pc(n){return ((Math.round(Number(n))%12)+12)%12;}
function clamp(n,lo,hi){return Math.max(lo,Math.min(hi,n));}
function hash(s){var h=2166136261;for(var i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function rng(seed){var x=seed>>>0;return function(){x+=0x6D2B79F5;var t=x;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;};}
function noteInRegister(pitch,prev,min,max){
 var choices=[];for(var n=min;n<=max;n++)if(pc(n)===pc(pitch))choices.push(n);
 if(!choices.length)return Math.round(pitch);
 return choices.sort(function(a,b){var da=Math.abs(a-(prev==null?43:prev));var db=Math.abs(b-(prev==null?43:prev));return da-db||a-b;})[0];
}
function inferStyle(source,fields){
 fields=fields||{};
 var r=(String(source||'').match(/^R:\s*(.*)$/mi)||[])[1]||fields['abc-rhythm']||'';
 var notes=[r,fields['abc-style']||'',fields['abc-genre']||''].join(' ').toLowerCase();
 var fromJazz=/jazz|ian.hayden/i.test(String(fields['abc-origin-library']||'')+' '+String(fields['abc-origin-url']||''));
 var meter=(String(source||'').match(/^M:\s*([^\s]+)$/mi)||[])[1]||fields['abc-meter']||'';
 if(/samba/.test(notes))return 'samba';
 if(/bossa|bossanova|bossa nova/.test(notes))return 'bossa';
 if(/ballad|slow jazz|jazz slow/.test(notes))return 'jazzballad';
 if(/jazz waltz|jazz vals/.test(notes))return 'jazzwaltz';
 if(/swing|bebop|jazz|blues|shuffle/.test(notes)||fromJazz)return meter==='3/4'?'jazzwaltz':'swing';
 if(/waltz|vals|valse/.test(notes)||meter==='3/4')return 'waltz';
 return 'pop';
}
function organise(events){return (events||[]).filter(function(e){return e&&e.cmd==='note'&&Number.isFinite(e.start)&&Number.isFinite(e.pitch);}).slice().sort(function(a,b){return a.start-b.start||a.pitch-b.pitch;});}
function meterLength(meter){return meter&&meter.den?meter.num/meter.den:1;}
function calcBars(events,meter){var sorted=organise(events),last=0;sorted.forEach(function(e){last=Math.max(last,e.start+Math.max(0,e.duration||0));});return Math.max(1,Math.ceil((last-0.0001)/meterLength(meter)));}
function normalForm(s){return String(s||'').replace(/[^A-Za-z]/g,'').toUpperCase();}
function form(source,barCount,meter,override){
 source=String(source||'');barCount=barCount||1;
 var head=source.split(/^K:\s*.*$/m)[0],p=(head.match(/^P:\s*(.*)$/m)||[])[1]||'';
 var detected='';var reason='';var confidence='forslag';
 var requested=String(override||'auto').toUpperCase();
 if(requested!=='AUTO'&&requested!=='NONE')detected=requested;
 if(!detected){
  var named=normalForm(p);
  if(/^(?:AABA|ABAC|ABAB|ABA|AAB|AB|ABC)$/.test(named)){detected=named;reason='ABC-feltet P:';confidence='høj';}
 }
 // Inline P:A / P:B sections: when no repeats, respect the explicit boundaries.
 var lines=source.split(/\r?\n/),body=false,marks=[],bar=0,inside=false;
 lines.forEach(function(line){
  if(/^K:/.test(line)){body=true;return;}if(!body)return;
  var part=line.match(/^P:\s*([A-Za-z])\s*$/);
  if(part){marks.push({at:bar,id:part[1].toUpperCase()});return;}
  if(/^[A-Za-z%]:/.test(line)||/^%%/.test(line))return;
  line=line.replace(/"(?:[^"\\]|\\.)*"/g,'').replace(/%.*$/,'');
  var separators=line.match(/\|:?|:\||\[\||\|\]|\|\|/g)||[];
  // Never use this approximate written count for unfolded repeats.
  bar+=separators.length;
 });
 var repeats=/\|:|:\|/.test(source.replace(/^\s*%.*$/gm,''));
 if(!detected&&marks.length>1&&!repeats){detected='INLINE';reason='P: markører i nodeteksten';confidence='høj';}
 if(!detected){
  if(barCount===32)detected=repeats&&/\[1/.test(source)&&/\[2/.test(source)?'AAB':'AABA';
  else if(barCount===12)detected='BLUES';
  else if(barCount===24)detected='AAB';
  else if(barCount===16)detected='AB';
  else detected='FREE';
  reason='taktantal'+(repeats?' og gentagelsestegn':'');
  confidence=detected==='FREE'?'ukendt':'forslag';
 }
 if(requested==='NONE'){detected='FREE';reason='valgt uden form';confidence='manuelt';}
 if(requested!=='AUTO'){confidence='manuelt';reason='valgt i afspilleren';}
 var sections=[];
 if(detected==='INLINE'){
  var used=marks.slice().sort(function(a,b){return a.at-b.at;});
  if(used[0].at>0)used.unshift({at:0,id:'A'});
  used.forEach(function(m,i){sections.push({start:clamp(m.at,0,barCount),end:clamp(i+1<used.length?used[i+1].at:barCount,0,barCount),id:m.id,index:i});});
 }else{
  var labels=detected==='BLUES'?['A','A','B']:detected==='FREE'?['A']:detected.split('');
  if(detected==='AAB'&&barCount===32)labels=['A','A','B'];
  for(var i=0;i<labels.length;i++)sections.push({start:Math.round(i*barCount/labels.length),end:Math.round((i+1)*barCount/labels.length),id:labels[i],index:i});
 }
 if(!sections.length)sections=[{start:0,end:barCount,id:'A',index:0}];
 sections=sections.filter(function(s){return s.end>s.start;});
 return {type:detected,sections:sections,bars:barCount,reason:reason,confidence:confidence,repeats:repeats};
}
function sectionAt(formResult,bar){var ss=formResult&&formResult.sections||[];for(var i=ss.length-1;i>=0;i--)if(bar>=ss[i].start)return ss[i];return ss[0]||{id:'A',index:0};}
// AABA defaults to a spacious bass-in-two in A and walking four in B.
function feelAt(formResult,bar,c){var mode=c&&c.feel||'form';if(mode==='two'||mode==='four')return mode;var sec=sectionAt(formResult,bar);return sec.id==='B'||sec.id==='C'?'four':'two';}
function walk(events,meter,formResult,c){
 var organised=organise(events),beats=[],seen={},barLength=meterLength(meter),quarters=Math.round(barLength*4);
 organised.forEach(function(e){var index=Math.round(e.start*4),key=String(index);if(Math.abs(e.start*4-index)>.001||seen[key])return;seen[key]=true;beats.push({idx:index,root:pc(e.pitch),source:e});});
 beats.sort(function(a,b){return a.idx-b.idx;});var previous=null,output=[];
 beats.forEach(function(beat,i){
  var next=beats[i+1],root=beat.root,position=((beat.idx%quarters)+quarters)%quarters,bar=Math.floor((beat.idx/4+.00001)/barLength),feel=feelAt(formResult,bar,c||{});
  if(feel==='two'&&position%2!==0)return;
  var prevRoot=i?beats[i-1].root:null,change=prevRoot!=null&&prevRoot!==root;
  var targetPc=root;
  if(feel==='two'){
   if(position!==0)targetPc=next&&next.root!==root?pc(next.root+11):pc(root+7);
  }else if(position===0||change){targetPc=root;}
  else if(next&&(position===quarters-1||next.root!==root)){
   var nextPitch=noteInRegister(next.root,previous,36,55),up=pc(nextPitch-1),down=pc(nextPitch+1);
   targetPc=previous==null?up:(Math.abs(noteInRegister(up,previous,36,55)-previous)<=Math.abs(noteInRegister(down,previous,36,55)-previous)?up:down);
  }else if(position===1){targetPc=pc(root+7);}
  else if(position===2){targetPc=pc(root+4);}
  else{targetPc=pc(root+5);}
  var midi=noteInRegister(targetPc,previous,36,55);
  if(previous!=null&&Math.abs(midi-previous)>8&&targetPc!==root){var alternate=noteInRegister(pc(root+7),previous,36,55);if(Math.abs(alternate-previous)<Math.abs(midi-previous))midi=alternate;}
  previous=midi;
  output.push(Object.assign({},beat.source,{pitch:midi,duration:feel==='two'?.435:.215,volume:clamp(Math.round((beat.source.volume||70)*(position===0?1:.83)),1,127)}));
 });
 return output;
}
// These non-Brazilian pattern slots are eighth-note subdivisions.
// Musical examples: Charleston, reverse Charleston, 2&4, upbeat anticipation, brush ballad, jazz waltz.
var COMP={
 swing:[[0,3],[1,4],[2,6],[3,7],[2,5,7]],
 jazzballad:[[0,4],[0,5],[2,6],[0,3,7],[1,6]],
 jazzwaltz:[[0,3],[2,4],[1,5],[0,4],[2,5]]
};
function describe(style){return style==='bossa'?BRAZIL_COMP.bossa.cycle.length:(COMP[style]||COMP.swing).length;}
function comp(events,meter,formResult,c,style,source){
 if(style==='bossa')return brazilComp(events,meter,formResult,c,'bossa',source);
 var sorted=organise(events),groups=[],barLength=meterLength(meter),total=formResult.bars,variation=clamp(Number(c.variation||0),0,100),choices=COMP[style]||COMP.swing;
 sorted.forEach(function(e){var g=groups[groups.length-1];if(!g||Math.abs(g.start-e.start)>.0001){g={start:e.start,notes:[]};groups.push(g);}g.notes.push(e);});
 if(!groups.length)return [];
 var random=rng(hash(String(source||'')+'|'+String(c.seed||0)+'|'+style)),current=-1,prevSec=-1,output=[];
 for(var bar=0;bar<total;bar++){
  var sec=sectionAt(formResult,bar),newSection=sec.index!==prevSec,cell=bar-sec.start,feel=feelAt(formResult,bar,c);
  if(newSection){current=sec.id==='B'?2:0;prevSec=sec.index;}
  // Chance of a pattern change; prefer 2/4-bar phrase boundaries at low randomness.
  if(variation>0&&bar>0&&(newSection||variation>=65||cell%2===0||cell%4===0)&&random()*100<variation){
   var old=current;current=Math.floor(random()*choices.length);if(current===old)current=(current+1)%choices.length;
  }
  var pulses=choices[current]||choices[0],slots=Math.round(barLength*8),start=bar*barLength;
  pulses.forEach(function(slot){
   if(slot>=slots)return;
   var at=start+slot/8;
   // Before a fresh chord on the next downbeat, an upbeat can anticipate it.
   var lookup=at;if(slot===slots-1&&variation>35)lookup+=.126;
   var lo=0,hi=groups.length-1,idx=0;
   while(lo<=hi){var mid=Math.floor((lo+hi)/2);if(groups[mid].start<=lookup+.00001){idx=mid;lo=mid+1;}else hi=mid-1;}
   var group=groups[idx],velocity=variation?(.88+random()*.23):1;
   group.notes.forEach(function(note){var jitter=variation?(random()-.5)*.0014*variation/100:0;
    output.push(Object.assign({},note,{start:Math.max(0,at+jitter),duration:style==='jazzballad'?.33:style==='bossa'?.18:.13,volume:clamp(Math.round((note.volume||60)*velocity*(feel==='two'?.75:.9)),1,127)}));
   });
  });
 }
