(function(){
'use strict';
// Interprets the most common ABC lead-sheet chord symbols. Pitch-class display
// is deliberately distinct from the arranger's actual rootless voicings.
var ROOTS={C:0,D:2,E:4,F:5,G:7,A:9,B:11,H:11};
function unique(a){return a.filter(function(x,i){return a.indexOf(x)===i;});}
function parse(label){
 var raw=String(label||'').trim().replace(/♭/g,'b').replace(/♯/g,'#').replace(/Δ|△/g,'maj').replace(/ø/g,'m7b5').replace(/°/g,'dim');
 var match=raw.match(/^([A-Ha-h])([#b]?)(.*)$/);if(!match)return null;
 var root=ROOTS[match[1].toUpperCase()];if(root===undefined)return null;
 if(match[2]==='#')root++;if(match[2]==='b')root--;root=(root+12)%12;
 var quality=match[3].split('/')[0],suffix=quality.toLowerCase();
 var intervals=[0,4,7];
 if(/^(?:m(?!aj)|min|-)/i.test(quality))intervals=[0,3,7];
 if(/^(?:dim|o|m7b5)/i.test(quality))intervals=[0,3,6];
 if(/^(?:aug|\+)/i.test(quality))intervals=[0,4,8];
 if(/sus2/i.test(quality))intervals=[0,2,7];
 else if(/sus(?:4)?/i.test(quality))intervals=[0,5,7];
 var maj7=/maj(?:7|9|11|13)|M(?:7|9|11|13)/.test(quality),seven=/(?:7|9|11|13)/.test(quality),six=/(?:^|[^1])6(?!\d)/.test(quality);
 if(seven)intervals.push(maj7?11:(/dim7/i.test(quality)?9:10));else if(six)intervals.push(9);
 if(/(?:add9|maj9|M9|(?:^|[^a-z#b0-9])9|^9)/.test(quality))intervals.push(14);
 if(/(?:11|add11)/i.test(quality))intervals.push(17);
 if(/(?:13|add13)/i.test(quality))intervals.push(21);
 if(/b5/i.test(quality))intervals=intervals.map(function(n){return n===7?6:n;});
 if(/#5/i.test(quality))intervals=intervals.map(function(n){return n===7?8:n;});
 if(/b9/i.test(quality))intervals.push(13);
 if(/#9/i.test(quality))intervals.push(15);
 if(/#11/i.test(quality))intervals.push(18);
 if(/b13/i.test(quality))intervals.push(20);
 // One-octave plus extensions in a readable piano range. Do not conflate
 // the root-position chord tones with the actual (possibly rootless) comp voicing.
 var pcs=unique(intervals.map(function(n){return (root+n)%12;}));
 var base=48+root; // From C3 up: C3 to B3 as bass root.
 var pitches=pcs.map(function(pc){return base+((pc-root+12)%12);});
 // A slash bass is a separate bass note, shown an octave below where practical.
 var slash=raw.match(/\/([A-Ha-h])([#b]?)/),bass=null;
 if(slash){bass=ROOTS[slash[1].toUpperCase()];if(bass!==undefined){bass=(bass+(slash[2]==='#'?1:slash[2]==='b'?-1:0)+12)%12;pitches.unshift(36+bass);}}
 return {name:String(label).trim(),root:root,pitchClasses:pcs,pitches:unique(pitches).sort(function(a,b){return a-b;})};
}
exports.parse=parse;
})();
