(function(){
'use strict';
// Correct an unclosed second-ending bracket only for rendering/printing.
// Its intended length is inferred from the matching first ending, not guessed
// as a fixed number of measures. The original ABC is never edited.
function separators(text,start,end){
 var found=[],inQuote=false,inComment=false;
 for(var i=start;i<end;i++){
  var c=text[i];
  if(c==='\n'||c==='\r'){inComment=false;continue;}
  if(inComment)continue;
  if(c==='"'&&(i===0||text[i-1]!=='\\')){inQuote=!inQuote;continue;}
  if(c==='%'&&!inQuote){inComment=true;continue;}
  if(inQuote)continue;
  if(c==='|' || (c===':'&&text[i+1]==='|')){
   var token=c===':'?':|':text.slice(i,i+2)==='||'?'||':text.slice(i,i+2)==='|]'?'|]':text.slice(i,i+2)==='|:'?'|:':'|';
   if(token==='|:')continue; // starts a repeat, does not end a measure
   found.push({at:i,token:token});
   if(token.length>1)i++;
  }
 }
 return found;
}
function presentation(source){
 source=String(source||'');
 // Only operate on a clear paired [1 ... :| [2 structure.
 var first=/\[1(?:[,0-9-]*)/.exec(source);if(!first)return source;
 var repeat=source.indexOf(':|',first.index+first[0].length);if(repeat<0)return source;
 var second=/\[2(?:[,0-9-]*)/.exec(source.slice(repeat+2));if(!second)return source;
 var pos=repeat+2+second.index+second[0].length;
 var count=separators(source,first.index+first[0].length,repeat).length+1; // :| closes the last measure
 if(count<1||count>12)return source;
 var following=separators(source,pos,source.length);
 if(following.length<count)return source;
 var end=following[count-1];
 if(end.token==='||'||end.token==='|]'||end.token===':|')return source;
 if(end.token!=='|')return source;
 return source.slice(0,end.at)+'||'+source.slice(end.at+1);
}
exports.presentation=presentation;
exports.separators=separators;
})();
