(function(){
'use strict';
function create(details,host){
 var parent=host.parentNode,next=host.nextSibling,box=document.createElement('div');
 box.className='huwabc-floating-keyboard';box.hidden=true;box.setAttribute('role','region');box.setAttribute('aria-label','Klaviatur følger noderne');
 var header=document.createElement('div');header.className='huwabc-floating-header';
 var heading=document.createElement('strong');heading.textContent='Klaviatur · følg noderne';header.appendChild(heading);
 var close=document.createElement('button');close.type='button';close.textContent='Skjul';close.setAttribute('aria-label','Skjul klaviatur');header.appendChild(close);box.appendChild(header);
 document.body.appendChild(box);
 // Moving the existing interactive keyboard out of the tiddler used to collapse
 // its details panel. Browser scroll anchoring then made the *whole tiddler*
 // jump up and down at the beginning of playback. Keep the original height.
 var placeholder=document.createElement('div');placeholder.className='huwabc-floating-placeholder';placeholder.hidden=true;
 var lastTarget=null,disposed=false;
 function restore(){
  if(parent&&host.parentNode!==parent){if(next&&next.parentNode===parent)parent.insertBefore(host,next);else parent.appendChild(host);}
  if(placeholder.parentNode)placeholder.parentNode.removeChild(placeholder);
  placeholder.hidden=true;
 }
 function hide(){lastTarget=null;box.hidden=true;restore();}
 function position(){
  if(box.hidden||!lastTarget||!lastTarget.isConnected)return;
  var staff=lastTarget.closest('.abcjs-staff-wrapper,.abcjs-staff,.huwabc-tabs-only')||lastTarget;
  var rect=staff.getBoundingClientRect(),paper=lastTarget.closest('.huwabc-paper,#paper'),paperRect=paper?paper.getBoundingClientRect():rect,width=Math.min(630,window.innerWidth-24);
  box.style.width=width+'px';
  var own=box.getBoundingClientRect(),height=Math.max(120,own.height);
  var center=Math.min(window.innerWidth-width/2-12,Math.max(width/2+12,(paperRect.left+paperRect.right)/2));
  box.style.left=Math.round(center-width/2)+'px';
  var below=rect.bottom+8,above=rect.top-height-9;
  var top=below+height<=window.innerHeight-10?below:above>=12?above:window.innerHeight-height-10;
  box.style.top=Math.round(Math.max(9,top))+'px';
 }
 function show(node){
  if(disposed||!details.open||!node){hide();return;}
  lastTarget=node;
  if(host.parentNode!==box){
   var r=host.getBoundingClientRect(),cs=window.getComputedStyle(host);
   placeholder.style.height=Math.max(0,r.height)+'px';
   placeholder.style.marginTop=cs.marginTop;placeholder.style.marginBottom=cs.marginBottom;
   placeholder.style.boxSizing='border-box';
   placeholder.hidden=false;
   parent.insertBefore(placeholder,host);
   box.appendChild(host);
  }
  box.hidden=false;
