 }
 function onToggle(){if(!details.open)hide();}
 details.addEventListener('toggle',onToggle);
 close.addEventListener('click',function(){details.open=false;hide();});
 window.addEventListener('resize',position);window.addEventListener('scroll',position,{passive:true});
 return {show:show,hide:hide,update:position,destroy:function(){if(disposed)return;disposed=true;hide();details.removeEventListener('toggle',onToggle);window.removeEventListener('resize',position);window.removeEventListener('scroll',position);box.remove();}};
}
// Follow only when playback moves to another *staff line*. Avoid
// element.scrollIntoView(), which scrolls every ancestor and can cause
// TiddlyWiki's story river to bounce when the audio widget is focused.
function createScroller(){
