 function follow(note){
  if(!note||!note.isConnected)return;
  var staff=note.closest('.abcjs-staff-wrapper,.abcjs-staff,.huwabc-tabs-only')||note;
  if(staff===lastStaff)return;
  lastStaff=staff;
  var root=null,parent=staff.parentElement;
  while(parent&&parent!==document.body&&parent!==document.documentElement){
   var style=window.getComputedStyle(parent);
   if(/auto|scroll/.test(style.overflowY)&&parent.scrollHeight>parent.clientHeight+8){root=parent;break;}
   parent=parent.parentElement;
  }
  var rect=staff.getBoundingClientRect(),boundary=root?root.getBoundingClientRect():null;
  var top=boundary?boundary.top+32:86;
  var bottom=boundary?boundary.bottom-90:window.innerHeight-115;
