  if(rect.top>=top&&rect.bottom<=bottom)return;
  var delta=rect.top-top-16;
  if(Math.abs(delta)<25)return;
  if(root)root.scrollTop+=delta;
  else window.scrollTo(window.scrollX,window.scrollY+delta);
 }
