(function(){
'use strict';
// One listener per document. Only the active score owns musical shortcuts.
// Shift+Space is a deliberate transport command, even on a focused button;
// ordinary Space retains native button/checkbox behaviour. Neither consumes
// typing, composition, selection-menu input, or a different modal dialog.
var entries=[],current=null,attached=false,heldSpace=false;
function visible(entry){
 if(!entry||!entry.host||!entry.host.isConnected)return false;
 var r=entry.host.getBoundingClientRect();if(r.width>0&&r.height>0)return true;
 // A minimal standalone player can have zero flow height when all its
 // visible children live in the fixed-position Music stand.
 var desk=entry.host.querySelector('.huwabc-page-is-desk');if(!desk)return false;
 r=desk.getBoundingClientRect();return r.width>0&&r.height>0;
}
function inputOwnsKey(target){
 return !!(target&&target.closest&&target.closest('input,textarea,select,button,summary,a[href],[contenteditable],[role="textbox"],[role="button"],[role="combobox"],[role="menuitem"],dialog[open]'));
}
function editingText(target){
 return !!(target&&target.closest&&target.closest('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"],[role="combobox"],[role="menuitem"]'));
}
function area(e){var r=e.host.getBoundingClientRect();return Math.max(0,Math.min(innerWidth,r.right)-Math.max(0,r.left))*Math.max(0,Math.min(innerHeight,r.bottom)-Math.max(0,r.top));}
function selected(target){
 var candidates=entries.filter(visible);if(!candidates.length)return null;
 var modal=document.querySelector('dialog[open],.huwabc-page-is-desk,.huwabc-editor-expanded');
 if(modal){candidates=candidates.filter(function(e){return modal.contains(e.host)||e.host.contains(modal);});if(!candidates.length)return null;}
 var focused=target||document.activeElement;
 if(focused){
  var enclosing=candidates.filter(function(e){return e.host.contains(focused);});
  // Nested examples/editors take precedence over their enclosing score.
  if(enclosing.length)return enclosing.reduce(function(a,b){return a.host.contains(b.host)?b:a;});
  if(inputOwnsKey(focused))return null;
 }
 if(candidates.indexOf(current)>=0)return current;
 return candidates.sort(function(a,b){return area(b)-area(a);})[0];
}
function keyName(event){
 if(event.code==='Space'||event.key===' '||event.key==='Spacebar')return 'Space';
 if(['PageDown','PageUp','Home','Escape'].indexOf(event.key)>=0)return event.key;
 if(/^[a-z]$/i.test(event.key))return event.key.toUpperCase();return null;
}
function consume(event){event.preventDefault();event.stopPropagation();}
function handle(event){
 if(event.defaultPrevented||event.isComposing||event.altKey||event.ctrlKey||event.metaKey)return;
 var key=keyName(event),shiftPlay=key==='Space'&&event.shiftKey,shiftStand=key==='N'&&event.shiftKey;
 if(shiftStand)key='Stand';
 if(key==='Space'&&heldSpace&&event.repeat){consume(event);return;}
 if(event.repeat&&key==='Space')return;
 if(event.shiftKey&&!shiftPlay&&!shiftStand)return;
 if((shiftPlay||shiftStand)?editingText(event.target):inputOwnsKey(event.target))return;
 var entry=selected(event.target);if(!key||!entry||!entry.actions[key])return;
 if(shiftStand&&event.repeat){consume(event);return;}
 if(entry.actions[key](event)===false)return;
 if(key==='Space')heldSpace=true;consume(event);
}
function keyup(event){
 // Prevent a native button click on keyup after consuming Shift+Space on
 // keydown. Holding a key must not alternate Play/Pause repeatedly.
 if(heldSpace&&keyName(event)==='Space'){heldSpace=false;consume(event);}
}
function blur(){heldSpace=false;}
function register(host,actions){
 var entry={host:host,actions:actions},disposed=false,addedTabindex=false;
 entries.push(entry);
 if(actions.Space&&!host.hasAttribute('tabindex')){host.setAttribute('tabindex','-1');addedTabindex=true;}
 var activate=function(event){
  current=entry;
  // Clicks on paper should not leave focus on another score's toolbar.
  // Do not steal focus from controls, text entry or the graphical editor.
  if(event.type==='pointerdown'&&actions.Space&&event.target&&event.target.closest&&
     event.target.closest('.huwabc-paper,#paper')&&!event.target.closest('input,textarea,select,button,summary,a[href],[contenteditable]')){
   try{host.focus({preventScroll:true});}catch(ignore){}
  }
 };
 host.addEventListener('pointerdown',activate,true);host.addEventListener('focusin',activate,true);
 if(!attached){document.addEventListener('keydown',handle,true);document.addEventListener('keyup',keyup,true);window.addEventListener('blur',blur);attached=true;}
 return function(){
  if(disposed)return;disposed=true;
  host.removeEventListener('pointerdown',activate,true);host.removeEventListener('focusin',activate,true);
  if(addedTabindex)host.removeAttribute('tabindex');
  entries=entries.filter(function(e){return e!==entry;});if(current===entry)current=null;
  if(!entries.length&&attached){document.removeEventListener('keydown',handle,true);document.removeEventListener('keyup',keyup,true);window.removeEventListener('blur',blur);attached=false;heldSpace=false;}
 };
}
exports.register=register;exports.inputOwnsKey=inputOwnsKey;exports.editingText=editingText;
})();
"},"$:/plugins/huwiki/abc/start-position.js":{"title":"$:/plugins/huwiki/abc/start-position.js","type":"application/javascript","module-type":"library","text":"/*\
