(function(){
'use strict';
// Match the clicked ABC source element with an ABCJS timing event.
// The timing data is the same data used by the playback cursor, so pickup
// measures, rests, repeats, and unequal durations are respected.
function validTiming(ev){return ev&&typeof ev.milliseconds==='number'&&isFinite(ev.milliseconds)&&ev.milliseconds>=0;}
function timings(tune){
 if(!tune)return [];
 try{if(!tune.noteTimings&&typeof tune.setTiming==='function')tune.setTiming();}catch(_ignored){}
 return (tune.noteTimings||[]).filter(validTiming);
}
function charStart(ev){
 var chars=ev.startCharArray;
 if(Array.isArray(chars))return chars.filter(function(x){return typeof x==='number'&&isFinite(x);});
 return typeof ev.startChar==='number'?[ev.startChar]:[];
}
function fromSource(tune,start){
 if(typeof start!=='number')return null;
 var list=timings(tune);
 var exact=list.find(function(ev){return charStart(ev).indexOf(start)>=0;});
 if(exact)return exact;
 // A few ABCJS parsing/rendering modes move the character position to the
 // beginning of the token. Allow a tiny tolerance, but never jump a bar.
 var near=null,distance=4;
 list.forEach(function(ev){charStart(ev).forEach(function(n){var d=Math.abs(n-start);if(d<distance){near=ev;distance=d;}});});
 return near;
}
function flattenElements(ev){var out=[];function add(e){if(Array.isArray(e))e.forEach(add);else if(e&&typeof e.getBoundingClientRect==='function')out.push(e);}
 add(ev.elements||[]);return out;}
function fromLocation(tune,clickedElement){
 if(!clickedElement||typeof clickedElement.getBoundingClientRect!=='function')return null;
 var r=clickedElement.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,best=null,bestDistance=Infinity;
 timings(tune).forEach(function(ev){flattenElements(ev).forEach(function(node){var n=node.getBoundingClientRect();if(!n.width||!n.height)return;
   var dx=n.left+n.width/2-cx,dy=n.top+n.height/2-cy;
   // Prefer the following note in the same system when clicking a chord symbol.
   var penalty=Math.abs(dx)+Math.abs(dy)*1.7+(dx< -24?100:0);
   if(Math.abs(dy)<115&&Math.abs(dx)<220&&penalty<bestDistance){best=ev;bestDistance=penalty;}
 });});return best;
}
function find(tune,sourceChar,svgTarget,milliseconds){
 var ev=fromSource(tune,sourceChar)||fromLocation(tune,svgTarget);
 if(ev)return {milliseconds:ev.milliseconds,event:ev};
 if(typeof milliseconds==='number'&&isFinite(milliseconds)&&milliseconds>=0)return {milliseconds:milliseconds,event:null};
 return null;
}
// Public ABCJS SynthController.seek accepts a fractional progress and a units
// argument. Prefer seconds; use fractional progress if a custom controller only
// supports percent. No change is made to notes or timing events.
function exactProgress(controller,ms){
 var end=controller.timer&&Number(controller.timer.lastMoment);
 if(!Number.isFinite(end)||end<=0)return;
 var percent=Math.max(0,Math.min(1,ms/end));
 // ABCJS seek emits a beat callback which rounds controller.percent to a
 // subdivision. AudioController subsequently calls timer.start(percent).
 // Restore the exact clicked position after seek so that a tuplet or other
 // off-grid onset starts the cursor at the same instant as the sound.
 try{
  if(typeof controller.setProgress==='function')controller.setProgress(percent,end);
  else controller.percent=percent;
 }catch(_ignored){
  // A custom controller can expose a read-only UI; successful seeking must
  // remain successful even if its progress display cannot be updated.
  try{controller.percent=percent;}catch(_readOnly){}
 }
}
function seek(controller,tune,ms){
 if(!controller||typeof controller.seek!=='function')return false;
 if(!isFinite(ms)||ms<0)return false;
 try{controller.seek(ms/1000,'seconds');exactProgress(controller,ms);return true;}catch(e){
  var list=timings(tune),last=list.length?list[list.length-1].milliseconds:0;
  if(!last)return false;
  try{controller.seek(Math.max(0,Math.min(1,ms/last)));exactProgress(controller,ms);return true;}catch(_ignored){return false;}
 }
}
exports.timings=timings;
exports.fromSource=fromSource;
exports.fromLocation=fromLocation;
exports.find=find;
exports.seek=seek;
})();
"},"$:/plugins/huwiki/abc/repeat-button.js":{"title":"$:/plugins/huwiki/abc/repeat-button.js","type":"application/javascript","module-type":"library","text":"/*\
