(function(){
'use strict';
/* Keep the repeat button's visible and accessible state in sync with abcjs. */
function mount(root){
 if(!root)return;
 var button=root.querySelector('.abcjs-midi-loop');if(!button)return;
 if(button._huwRepeatObserver)return;
 function update(){
  var on=button.classList.contains('abcjs-pushed');
  button.setAttribute('aria-pressed',on?'true':'false');
  button.setAttribute('aria-label',on?'Gentagelse slået til':'Gentagelse slået fra');
  button.setAttribute('title',on?'Gentagelse slået til – klik for at slå fra':'Gentagelse slået fra – klik for at slå til');
 }
 button._huwRepeatObserver=new MutationObserver(update);
 button._huwRepeatObserver.observe(button,{attributes:true,attributeFilter:['class']});
