(function(){
'use strict';
var INDEX='https://raw.githubusercontent.com/stewing-co/jambuddy-abc/main/index/search/balkan.json';
var BASE='https://raw.githubusercontent.com/stewing-co/jambuddy-abc/main/sources/';
var CACHE=null;
function normalize(text){return String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
