  return parsed.tunes.filter(function(t){return t&&safeURL(t.url)&&Array.isArray(t.titles)&&t.titles.length;});
 }).catch(function(err){CACHE=null;throw err;});
 return CACHE;
}
function filter(all,q){var term=normalize(q);if(!term)return all;return all.filter(function(t){return [t.titles.join(' '),t.category||'',t.key||'',t.meter||''].some(function(s){return normalize(s).includes(term);});});}
