 var lines=[],re=/^X:\s*([^\r\n]*)/gm,match;
 while((match=re.exec(raw))!==null)lines.push({index:match.index,x:match[1].trim()});
 if(!lines.length)throw Error('Kildefilen indeholder ingen ABC-melodier med X:.');
 function chunk(i){return raw.slice(lines[i].index,i+1<lines.length?lines[i+1].index:raw.length).trim();}
 var ordinal=Number(item.ordinal),matches=[];
 for(var i=0;i<lines.length;i++)if(lines[i].x===String(item.x))matches.push(i);
