  var title=normalize(item.titles[0]);
  matches.sort(function(a,b){return Number(!chunk(a).split('\n').some(function(line){return /^T:/.test(line)&&normalize(line.slice(2))===title;}))-Number(!chunk(b).split('\n').some(function(line){return /^T:/.test(line)&&normalize(line.slice(2))===title;}));});
 }
 var selected=matches.length?matches[0]:(Number.isInteger(ordinal)&&ordinal>=0&&ordinal<lines.length?ordinal:-1);
