(function(){'use strict';
/* Original HUWiki 7/8 arranging studies. The patterns are teaching-oriented,
 * regionally inspired models, not claimed transcriptions of specific folk drummers.
 * A tick is exactly one notated eighth note: no 4/4 padding or timing drift. */
var STYLE={
 'mk-lesnoto':{label:'Makedonien · Lesnoto (3+2+2)',group:[3,2,2],family:'tapan',bassInstrument:32,chordInstrument:24},
 'mk-cigancica':{label:'Makedonien · Čigančica (2+2+3)',group:[2,2,3],family:'tapan',bassInstrument:32,chordInstrument:21},
 'gr-kalamatianos':{label:'Grækenland · Kalamatianós (3+2+2)',group:[3,2,2],family:'daouli',bassInstrument:32,chordInstrument:24},
 'tr-devrihindi':{label:'Tyrkiet · Devr-i Hindî (3+2+2)',group:[3,2,2],family:'darbuka',bassInstrument:32,chordInstrument:24},
 'tr-devrituran':{label:'Tyrkiet · Devr-i Tûrân (2+2+3)',group:[2,2,3],family:'darbuka',bassInstrument:32,chordInstrument:24},
 'free-232':{label:'Rytmeværksted · 2+3+2 (fri 7/8)',group:[2,3,2],family:'tapan',bassInstrument:32,chordInstrument:24},
 'in-misrachapu':{label:'Indien · Miśra Cāpu (7/8 studie · 3+2+2)',group:[3,2,2],family:'mridangam',bassInstrument:32,chordInstrument:24}
};
var COMPOSITE={
 'mk-form':{label:'Makedonien · A Lesnoto / B Čigančica',a:'mk-lesnoto',b:'mk-cigancica',group:null,bassInstrument:32,chordInstrument:24},
 'tr-form':{label:'Tyrkiet · A Hindî / B Tûrân',a:'tr-devrihindi',b:'tr-devrituran',group:null,bassInstrument:32,chordInstrument:24},
 'balkan-form':{label:'Balkan · A Lesnoto / B Kalamatianós',a:'mk-lesnoto',b:'gr-kalamatianos',group:[3,2,2],bassInstrument:32,chordInstrument:24}
};
var ALL=Object.assign({},STYLE,COMPOSITE);
function readMeter(source){
 var header=(String(source||'').match(/^M:\s*([^\r\n%]+)/m)||[])[1]||'';
 var match=header.match(/^\s*\(?\s*([0-9+\s]+)\s*\)?\s*\/\s*(\d+)/);
 if(!match)return null;
 var numbers=match[1].split('+').map(function(x){return Number(x.trim());});
 if(!numbers.length||numbers.some(function(n){return !(n>0)}))return null;
 return {num:numbers.reduce(function(a,b){return a+b;},0),den:Number(match[2]),groups:numbers.length>1?numbers:null};
}
function same(a,b){return !a||!b||a.join('+')===b.join('+');}
function compatible(source){
 var meter=readMeter(source);if(!meter||meter.num!==7||meter.den!==8)return [];
 // An explicitly grouped meter must be respected through every form section.
 // E.g. a 3+2+2 score must not silently play the 2+2+3 B style.
 return Object.keys(ALL).filter(function(k){
  if(!meter.groups)return true;
  if(STYLE[k])return same(meter.groups,STYLE[k].group);
  var composite=COMPOSITE[k];
  return composite&&same(meter.groups,STYLE[composite.a].group)&&same(meter.groups,STYLE[composite.b].group);
 });
}
function autoStyle(source,fields){
 var meter=readMeter(source);var group=meter&&meter.groups||null;
 var info=String(source||'').match(/^R:\s*(.*)$/mi)||[];
 var words=[info[1],fields&&fields['abc-style'],fields&&fields['abc-rhythm'],fields&&fields['abc-genre']].join(' ').toLowerCase();
 var candidates=[];
 if(/misra\s*chapu|miśra|misra\s*c[āa]pu|konnakol|solkattu/.test(words))candidates.push('in-misrachapu');
 if(/cigan|ciganch|čigan|r[ăa]čenica|ruchenitsa/.test(words))candidates.push('mk-cigancica');
 if(/lesno|lesnoto|makedon|macedon/.test(words))candidates.push('mk-lesnoto');
 if(/kalamat|greek|gr[æe]sk|ellin/.test(words))candidates.push('gr-kalamatianos');
 if(/turan|tûrân|mandira/.test(words))candidates.push('tr-devrituran');
 if(/hindi|hindî|t[üu]rk|tyrk/.test(words))candidates.push('tr-devrihindi');
 if(group&&group.join('+')==='2+3+2')candidates.push('free-232');
 if(group&&group.join('+')==='2+2+3')candidates.push('mk-cigancica');
 candidates.push('mk-lesnoto');
 return candidates.find(function(k){return same(group,STYLE[k].group);})||'mk-lesnoto';
}
function choice(style,section){
 var c=COMPOSITE[style];return c?(section==='B'?c.b:c.a):(STYLE[style]?style:'mk-lesnoto');
}
function starts(groups){var p=0;return groups.map(function(n){var old=p;p+=n;return old;});}
function hash(s){var h=2166136261;for(var i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function rng(seed){var n=seed>>>0;return function(){n+=0x6D2B79F5;var t=n;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;};}
function clamp(n,a,b){return Math.min(b,Math.max(a,n));}
function register(n,lo,hi){var p=Math.round(n);while(p<lo)p+=12;while(p>hi)p-=12;return p;}
function sorted(events){return (events||[]).filter(function(e){return e&&e.cmd==='note'&&Number.isFinite(e.start)&&Number.isFinite(e.pitch);}).slice().sort(function(a,b){return a.start-b.start||a.pitch-b.pitch;});}
function noteAt(events,when){var ans=null;for(var i=0;i<events.length;i++){if(events[i].start>when+.00001)break;ans=events[i];}return ans;}
function groupAt(events,when){var t=noteAt(events,when);if(!t)return [];return events.filter(function(e){return Math.abs(e.start-t.start)<.0001;});}
// Each style supplies four distinct, two-bar arrangements. Per-bar slots are 0..6.
var PATTERNS={
 'mk-lesnoto':[
  {bass:[[0,3],[0,5]],comp:[[3,5],[3]],orn:[[6],[]]},
  {bass:[[0,5],[0,3]],comp:[[3],[3,5]],orn:[[],[6]]},
  {bass:[[0,3,5],[0,5]],comp:[[0,5],[3,6]],orn:[[2],[]]},
  {bass:[[0,5],[0,3,5]],comp:[[5,6],[3]],orn:[[],[4,6]]}
 ],
 'mk-cigancica':[
  {bass:[[0,4],[0,2,4]],comp:[[2,4],[2,5]],orn:[[],[6]]},
  {bass:[[0,2],[0,4]],comp:[[2,5],[4,6]],orn:[[6],[]]},
  {bass:[[0,2,4],[0,4]],comp:[[0,4],[2,4,6]],orn:[[],[5]]},
  {bass:[[0,4],[0,2,4]],comp:[[2,6],[0,4]],orn:[[3],[6]]}
 ],
 'gr-kalamatianos':[
  {bass:[[0,3],[0,5]],comp:[[0,3,5],[3,5]],orn:[[],[6]]},
  {bass:[[0,5],[0,3]],comp:[[3,5],[0,3,6]],orn:[[2],[]]},
  {bass:[[0,3,5],[0,5]],comp:[[3,6],[3,5]],orn:[[6],[2]]},
  {bass:[[0,3],[0,3,5]],comp:[[0,5],[3,5,6]],orn:[[],[4]]}
 ],
 'tr-devrihindi':[
  {bass:[[0,3],[0,3]],comp:[[3,5],[3,6]],orn:[[1,2],[1,5]]},
  {bass:[[0,3,5],[0,3]],comp:[[3],[3,5]],orn:[[1,2],[2]]},
  {bass:[[0,3],[0,5]],comp:[[0,3,5],[3]],orn:[[1,2],[4,6]]},
  {bass:[[0,3],[0,3,5]],comp:[[3,6],[0,5]],orn:[[2],[1,2,6]]}
 ],
 'tr-devrituran':[
  {bass:[[0,4],[0,2,4]],comp:[[2,4],[2,5]],orn:[[3],[6]]},
  {bass:[[0,2,4],[0,4]],comp:[[2,5],[0,4]],orn:[[3],[5]]},
  {bass:[[0,4],[0,4]],comp:[[0,2,5],[2,4,6]],orn:[[1,3],[6]]},
  {bass:[[0,2],[0,4]],comp:[[4,6],[2,5]],orn:[[3],[3,6]]}
 ],
 'free-232':[
  {bass:[[0,2],[0,5]],comp:[[2,5],[2,6]],orn:[[],[6]]},
  {bass:[[0,5],[0,2]],comp:[[2,5],[0,5]],orn:[[4],[]]},
  {bass:[[0,2,5],[0,5]],comp:[[0,2,5],[2,6]],orn:[[4],[6]]},
  {bass:[[0,2],[0,2,5]],comp:[[5,6],[2,5]],orn:[[],[4]]}
 ],
 'in-misrachapu':[
  {bass:[[0,3],[0,5]],comp:[[3,5],[3]],orn:[[2],[6]]},
  {bass:[[0,5],[0,3]],comp:[[3],[3,5]],orn:[[2,6],[]]},
  {bass:[[0,3,5],[0,5]],comp:[[0,5],[3,6]],orn:[[1],[4]]},
  {bass:[[0,3],[0,3,5]],comp:[[3,6],[0,3]],orn:[[2],[6]]}
 ]
};
function generate(style,form,config,source,bassSeeds,chordSeeds){
 var out={bass:[],chords:[],drums:[],bars:[],style:style};
 var meter=readMeter(source);if(!meter||meter.num!==7||meter.den!==8)return out;
 var length=7/8,bars=Math.max(1,form&&form.bars||1),variation=clamp(Number(config.variation||0),0,100);
 var random=rng(hash(source+'|'+(config.seed||1)+'|'+style));bassSeeds=sorted(bassSeeds);chordSeeds=sorted(chordSeeds);
 var current=0,prevSection=-1,lastStyle='';
 for(var bar=0;bar<bars;bar++){
  var section=form&&form.sections&&form.sections.find(function(s){return bar>=s.start&&bar<s.end;})||{id:'A',index:0,start:0};
  var specific=choice(style,section.id),def=STYLE[specific],variants=PATTERNS[specific],phase=bar%2;
  if(section.index!==prevSection||specific!==lastStyle){current=section.id==='B'?2:0;prevSection=section.index;lastStyle=specific;}
  else if(phase===0&&variation>0&&random()*100<variation){var previous=current;current=Math.floor(random()*4);if(previous===current)current=(current+1)%4;}
  var fig=variants[current],groups=def.group,accents=starts(groups),tickStart=bar*length;
  out.bars.push({bar:bar,style:specific,group:groups.slice(),variant:current,section:section.id});
  function pushBase(tick,i){var at=tickStart+tick/8,seed=noteAt(bassSeeds,at);if(!seed)return;
   var pitch=register(seed.pitch,36,56),other=fig.bass[phase];
   if(i>0){pitch=register(pitch+(i===other.length-1?7:0),36,56);}
   out.bass.push(Object.assign({},seed,{start:at,pitch:pitch,duration:Math.min(.11,length-tick/8-.006),volume:clamp(Math.round((seed.volume||75)*(i===0?.96:.78)),1,127)}));}
  fig.bass[phase].forEach(pushBase);
  fig.comp[phase].forEach(function(tick){var at=tickStart+tick/8,notes=groupAt(chordSeeds,at);notes.forEach(function(n){out.chords.push(Object.assign({},n,{start:at,duration:Math.min(.15,length-tick/8-.006),volume:clamp(Math.round((n.volume||65)*(tick===0?.83:.72)),1,127)}));});});
  function drum(tick,pitch,v){if(tick<0||tick>=7)return;out.drums.push({cmd:'note',start:tickStart+tick/8,duration:.052,pitch:pitch,volume:clamp(Math.round(v),1,127),instrument:128});}
  // Tapan/daouli use low drum plus stick/rim; Turkish usuls use dum/tek
  // approximated with low conga and higher conga/bongo in General MIDI.
  if(def.family==='mridangam'){
   // GM conga/tabla-like surrogate; not a sampled mridangam or a canonical theka.
   drum(0,64,94);drum(accents[1],63,67);drum(accents[2],64,73);
   fig.orn[phase].forEach(function(t){drum(t,62,28+variation*.25);});
  } else if(def.family==='darbuka'){
   drum(0,64,89);drum(accents[1],64,72);
   [1,2,5].forEach(function(t){if(specific==='tr-devrihindi'||t!==2)drum(t,63,t===5?65:45);});
   if(specific==='tr-devrituran'){drum(2,63,66);drum(4,64,72);}
   fig.orn[phase].forEach(function(t){drum(t,62,25+variation*.22);});
  }else{
   drum(0,36,def.family==='daouli'?82:95);
   drum(accents[1],def.family==='daouli'?38:37,def.family==='daouli'?60:76);
   drum(accents[2],36,def.family==='daouli'?65:83);
   if(def.family==='daouli')drum(5,54,40); // hand/tambourine flourish
   fig.orn[phase].forEach(function(t){drum(t,def.family==='daouli'?54:37,24+variation*.24);});
  }
  // Light subdivision only on high variation – never blur the uneven downbeats.
  if(variation>=50&&random()*100<variation/2){[1,2,4,6].forEach(function(t){if(!accents.includes(t))drum(t,70,17);});}
 }
 return out;
}
exports.patterns=PATTERNS;exports.styles=ALL;exports.readMeter=readMeter;exports.compatible=compatible;exports.autoStyle=autoStyle;exports.generate=generate;exports.groupFor=function(style,source){var m=readMeter(source);if(m&&m.groups)return m.groups;return (STYLE[choice(style,'A')]||STYLE['mk-lesnoto']).group.slice();};
})();
