 var copy=document.createElement('button');copy.textContent=english?'Copy HTML':'Kopiér HTML';copy.onclick=async function(){try{await navigator.clipboard.writeText(html);onStatus(english?'HTML copied. Save it as '+name+'.':'HTML-koden er kopieret. Gem den som '+name+'.');overlay.remove();}catch(err){input.focus();input.select();onStatus(english?'Select the HTML code and copy it manually.':'Markér HTML-koden og kopiér manuelt.');}};
 var close=document.createElement('button');close.textContent=english?'Close':'Luk';close.onclick=function(){overlay.remove();};row.appendChild(copy);row.appendChild(close);panel.appendChild(row);overlay.appendChild(panel);document.body.appendChild(overlay);
 onStatus(english?'This iPad browser cannot share files. Copy the HTML code or open the wiki in Safari.':'Denne iPad-browser understøtter ikke fildeling; du kan kopiere HTML-koden eller åbne wikien i Safari.');
