 var panel=document.createElement('section');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',english?'Local Site player preview':'Lokal forhåndsvisning af Site-afspiller');panel.style.cssText='display:flex;flex-direction:column;width:min(1150px,98vw);height:94vh;background:#fff;color:#19362e;border-radius:14px;overflow:hidden;box-shadow:0 25px 60px #0003';
