 var hint=document.createElement('span');hint.style.cssText='flex:1 1 200px;font:13px/1.5 system-ui';hint.textContent=english?'Local site preview · the downloaded HTML works without HUWiki.':'Lokal sitevisning · den gemte HTML-fil virker uden HUWiki.';bar.appendChild(hint);
