 var titleLabel=document.createElement('label');titleLabel.textContent=english?'Site heading':'Siteoverskrift';titleLabel.style.cssText='font-size:12px;display:flex;align-items:center;gap:8px;flex:1 1 260px';
 var headingInput=document.createElement('input');headingInput.id='huwabc-site-heading-field';headingInput.type='text';headingInput.maxLength=180;headingInput.value=options&&typeof options.siteHeading==='string'?options.siteHeading:'TiddlyWiki Musik Edition';headingInput.style.cssText='padding:8px;border:1px solid #bbd3c8;border-radius:8px;min-width:140px;flex:1';titleLabel.appendChild(headingInput);
 var displayLabel=document.createElement('label');displayLabel.style.cssText='display:flex;align-items:center;gap:5px;white-space:nowrap;font-size:12px';var displayCheck=document.createElement('input');displayCheck.type='checkbox';displayCheck.id='huwabc-site-heading-visible';displayCheck.checked=!options||options.showSiteHeading!==false;displayLabel.appendChild(displayCheck);displayLabel.appendChild(document.createTextNode(english?'Show heading':'Vis overskrift'));
 settings.appendChild(titleLabel);settings.appendChild(displayLabel);
 function headingChoices(){return {siteHeading:headingInput.value.trim(),showSiteHeading:displayCheck.checked};}
