title: $:/plugins/huwiki/abc/audio-controller.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
// Keep ABCJS's controls and timing callbacks. Guard asynchronous preparation and
// resume so Stop, closing a tiddler, and changing tempo cannot restart old sound.
var Reserve=require('$:/plugins/huwiki/abc/reserve-mixer.js');
function cancelled(){var e=new Error('Afspilningen er annulleret.');e.name='AbortError';return e;}
exports.install=function(controller,ABC,options){
 options=options||{};
 var revision=0,pending=null,playPending=null,forced=false;
 var nativeSetTune=controller.setTune;
 function alive(stamp){return stamp===revision&&!controller._disposed&&(!options.isCurrent||options.isCurrent());}
 function check(stamp){if(!alive(stamp))throw cancelled();}
 function stopped(paused){if(options.onStop)options.onStop(!!paused);}
 function context(){
  var ctx=ABC.synth.activeAudioContext();
  if(!ctx){var AudioCtor=window.AudioContext||window.webkitAudioContext;if(!AudioCtor)throw new Error('Web Audio understøttes ikke i denne browser.');ctx=new AudioCtor();ABC.synth.registerAudioContext(ctx);}
  return ctx;
 }
 function stopTimer(reset){if(controller.timer){try{if(reset)controller.timer.reset();controller.timer.stop();}catch(_ignore){}}}
 function discard(){
  revision++;pending=null;playPending=null;controller.isLoading=false;controller.isLoaded=false;
  stopTimer(true);controller.timer=null;
  var buffer=controller.midiBuffer;controller.midiBuffer=null;
  if(buffer){if(buffer.cancel)buffer.cancel();try{buffer.stop();}catch(_ignore){}if(buffer.release)buffer.release();else if(buffer.disposeMixer)buffer.disposeMixer();}
  if(Reserve.stopAuditions)Reserve.stopAuditions();
  controller.isStarted=false;stopped(false);
 }
 function failure(error){if(error&&error.name!=='AbortError'&&options.onError)options.onError(error);}
 function syncWarp(){
  var control=controller.control;if(!control)return;
  // ABCJS's setWarp assumes its optional tempo input exists. HUWiki uses
  // its own tempo controls, so only update ABCJS's tempo label in that case.
  if(control.parent&&control.parent.querySelector('.abcjs-midi-tempo'))control.setWarp(controller.currentTempo,controller.warp);
  else control.setTempo(controller.currentTempo);
 }
 controller.go=function(){
  if(pending)return pending;
  if(!controller.visualObj)return Promise.reject(new Error('Der er ingen melodi at afspille.'));
  var stamp=revision,ctx,buffer;
  try{
   check(stamp);ctx=context();
   buffer=controller.midiBuffer;
   if(!buffer){
    buffer=Reserve.createMixer(ABC,options.getConfig,{wiki:options.wiki,
     forceReserve:function(){return forced;},isCancelled:function(){return controller._disposed||controller.midiBuffer!==buffer||(options.isCurrent&&!options.isCurrent());},
     onStatus:function(state){if(controller.midiBuffer===buffer&&(!options.isCurrent||options.isCurrent())&&options.onStatus)options.onStatus(state);},runtime:options.runtime});
    controller.midiBuffer=buffer;
   }
   controller.isLoading=true;controller.isLoaded=false;
   var ms=controller.visualObj.millisecondsPerMeasure()*100/controller.warp;
   controller.currentTempo=Math.round(controller.visualObj.getBeatsPerMeasure()/ms*60000);
   if(controller.control)controller.control.setTempo(controller.currentTempo);
   controller.percent=0;
  }catch(error){failure(error);return Promise.reject(error);}
  var response;
  var task=Promise.resolve(ctx.resume()).then(function(){
   check(stamp);
   return buffer.init({audioContext:ctx,visualObj:controller.visualObj,options:controller.options||{},millisecondsPerMeasure:ms});
  }).then(function(result){check(stamp);response=result;return buffer.prime();}).then(function(){
   check(stamp);
   var cursor=controller.cursorControl,subdivisions=16;
   if(cursor&&Number(cursor.beatSubdivisions)>=1&&Number(cursor.beatSubdivisions)<=64)subdivisions=parseInt(cursor.beatSubdivisions,10);
   controller.timer=new ABC.TimingCallbacks(controller.visualObj,{beatCallback:controller.beatCallback,eventCallback:controller.eventCallback,
    lineEndCallback:controller.lineEndCallback,qpm:controller.currentTempo,
    extraMeasuresAtBeginning:cursor?cursor.extraMeasuresAtBeginning:undefined,
    lineEndAnticipation:cursor?cursor.lineEndAnticipation:0,beatSubdivisions:subdivisions});
   if(cursor&&typeof cursor.onReady==='function')cursor.onReady(controller);
   controller.isLoaded=true;controller.isLoading=false;
   return {status:'created',notesStatus:response};
  }).catch(function(error){
   if(alive(stamp)){controller.isLoading=false;controller.isLoaded=false;failure(error);}
   throw error;
  }).finally(function(){if(pending===task)pending=null;});
  pending=task;return task;
 };
 controller.runWhenReady=function(fn,arg){
  if(!controller.visualObj)return Promise.resolve({status:'loading'});
  var stamp=revision;
  return Promise.resolve(controller.isLoaded?null:controller.go()).then(function(){check(stamp);return fn(arg);}).catch(function(error){
   if(error&&error.name==='AbortError')return {status:'cancelled'};
   throw error;
  });
 };
 controller._play=function(){
  var stamp=revision;
  return Promise.resolve(context().resume()).then(function(){
   check(stamp);
   if(controller.isStarted){controller.pause();return {status:'paused'};}
   if(!controller.isLoaded||!controller.timer||!controller.midiBuffer)throw cancelled();
   if(options.beforePlay)options.beforePlay();
   check(stamp);
   controller.isStarted=true;
   if(controller.cursorControl&&controller.cursorControl.onStart)controller.cursorControl.onStart();
   check(stamp);controller.midiBuffer.start();controller.timer.start(controller.percent);
   if(options.onStatus&&controller.midiBuffer.getState)options.onStatus(controller.midiBuffer.getState());
   if(controller.control)controller.control.pushPlay(true);
   return {status:'ok'};
  });
 };
 controller.play=function(){
  if(playPending)return playPending;
  var task=controller.runWhenReady(controller._play).catch(function(error){failure(error);throw error;}).finally(function(){if(playPending===task)playPending=null;});
  playPending=task;return task;
 };
 controller.pause=function(){
  // Pausing a preparation cancels it. Pausing prepared audio retains its cursor.
  if(controller.isLoading){discard();return;}
  revision++;pending=null;playPending=null;
  if(Reserve.stopAuditions)Reserve.stopAuditions();
  if(controller.timer)controller.timer.pause();
  if(controller.midiBuffer)try{controller.midiBuffer.pause();}catch(_ignore){}
  controller.isStarted=false;if(controller.control)controller.control.pushPlay(false);stopped(true);
 };
 controller.huwikiStop=function(){
  discard();controller._huwabcStopGeneration=(controller._huwabcStopGeneration||0)+1;
  controller.isLooping=false;controller.setProgress(0,1);
  if(controller.control){controller.control.pushPlay(false);controller.control.pushLoop(false);}
  if(controller.cursorControl&&controller.cursorControl.onFinished)controller.cursorControl.onFinished();
 };
 controller.destroy=function(){
  discard();controller.setProgress(0,1);
  if(controller.control)controller.control.resetAll();
 };
 controller.setTune=function(tune,userAction,params){
  discard();return nativeSetTune.call(controller,tune,userAction,params);
 };
 controller.setWarp=function(value){
  var warp=parseInt(value,10);if(!(warp>0))return Promise.resolve();
  var wasPlaying=controller.isStarted,position=Number(controller.percent)||0,loop=controller.isLooping;
  var prepared=controller.isLoaded||controller.isLoading;
  controller.warp=warp;
  // Changing an unplayed tune's tempo must not download sounds without a gesture.
  if(!prepared){
   if(controller.visualObj)controller.currentTempo=Math.round(controller.visualObj.getBeatsPerMeasure()/controller.visualObj.millisecondsPerMeasure()*60000*warp/100);
   syncWarp();
   return Promise.resolve({status:'deferred'});
  }
  discard();controller.isLooping=loop;var stamp=revision;
  return controller.go().then(function(){
   check(stamp);controller.setProgress(position,controller.midiBuffer.duration*1000);
   syncWarp();if(controller.control)controller.control.pushLoop(loop);
   controller.seek(position);
   if(wasPlaying)return controller._play();
   return {status:'ready'};
  }).catch(function(error){if(error&&error.name==='AbortError')return {status:'cancelled'};failure(error);throw error;});
 };
 controller.setReserveMode=function(force){
  forced=!!force;controller.huwikiStop();
  if(options.onStatus)options.onStatus({engine:forced?'fluid':'original',phase:'selected',reason:forced?'manual':'retry',local:false});
  return forced;
 };
 controller.reserveMode=function(){return forced;};
 controller.getAudioState=function(){return controller.midiBuffer&&controller.midiBuffer.getState?controller.midiBuffer.getState():{engine:forced?'fluid':'original',phase:'idle'};};
 controller.audition=function(notes,tune){
  var stamp=revision;
  try{check(stamp);context();}catch(error){return Promise.reject(error);}
  var buffer=controller.midiBuffer;
  if(buffer&&buffer.audition)return buffer.audition(notes,tune);
  return Reserve.audition(ABC,notes,tune,{wiki:options.wiki,getConfig:options.getConfig,runtime:options.runtime,
   soundFontUrl:controller.options&&controller.options.soundFontUrl,forceReserve:forced,onStatus:options.onStatus,
   isCancelled:function(){return !alive(stamp);}});
 };
 return controller;
};
})();
"},"$:/plugins/huwiki/abc/audio-sequence.js":{"title":"$:/plugins/huwiki/abc/audio-sequence.js","type":"application/javascript","module-type":"library","text":"/* HUWiki Lydforsøg 01. New, isolated test code; does not patch TiddlyWiki. */
(function (root, factory) {
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  else root.HULabCore = api;
})(typeof window !== 'undefined' ? window : this, function () {
  'use strict';
  const PARTS = ['melodyVolume', 'bassVolume', 'chordVolume', 'drumVolume', 'metronomeVolume'];

  // Match ABCJS 6.7.2 create-note-map's duration/gap rounding. The candidate
  // gets identical musical on/off times; its own sample envelopes are retained.
  function notesFromSequence(sequence, secondsPerWhole) {
    const result = [];
    let currentInstrument = 0;
    sequence.tracks.forEach((track, trackIndex) => {
      track.forEach(event => {
        if (event.cmd === 'program') currentInstrument = event.instrument;
        if (event.cmd !== 'note' || !(event.duration > 0) || !(event.volume > 0)) return;
        const gap = Math.min(event.gap || 0, event.duration * 2 / 3);
        const startWhole = Math.round(event.start * 1e6) / 1e6;
        const endWhole = Math.round((event.start + event.duration - gap) * 1e6) / 1e6;
        const program = Number(event.instrument === undefined ? currentInstrument : event.instrument);
        result.push({
          start: startWhole * secondsPerWhole,
          end: endWhole * secondsPerWhole,
          pitch: Number(event.pitch), velocity: Math.max(1, Math.min(127, Math.round(event.volume))),
          program, percussion: program === 128, cents: Number(event.cents || 0),
          part: track.huwabcPart || 'melodyVolume', trackIndex,
          startChar: event.startChar, endChar: event.endChar
        });
      });
    });
    return result.sort((a, b) => a.start - b.start || a.trackIndex - b.trackIndex || a.pitch - b.pitch);
  }

  function clipSequence(sequence, endWhole) {
    const out = Object.assign({}, sequence, { totalDuration: Math.min(sequence.totalDuration, endWhole) });
    out.tracks = sequence.tracks.map(track => {
      const clipped = track.filter(event => event.cmd !== 'note' || event.start < endWhole).map(event => {
        if (event.cmd !== 'note') return Object.assign({}, event);
        return Object.assign({}, event, { duration: Math.max(0, Math.min(event.duration, endWhole - event.start)) });
      });
      if (track.huwabcPart) clipped.huwabcPart = track.huwabcPart;
      return clipped;
    });
    return out;
  }

  function allocateChannels(notes) {
    const assignments = new Map();
    let next = 0;
    for (const n of notes) {
      if (!Number.isInteger(n.pitch) || n.pitch < 0 || n.pitch > 127) throw new Error('Ugyldig MIDI-tone: ' + n.pitch);
      if (!Number.isInteger(n.program) || n.program < 0 || n.program > 128) throw new Error('Ugyldigt program: ' + n.program);
      const key = n.percussion ? 'drums' : n.program + ':' + n.cents;
      if (assignments.has(key)) continue;
      if (n.percussion) assignments.set(key, 9);
      else {
        if (next === 9) next++;
        if (next > 15) throw new Error('Forsøget kræver mere end 15 melodiske MIDI-kanaler.');
        assignments.set(key, next++);
      }
    }
    return assignments;
  }

  function createEvents(notes, sampleRate) {
    const channels = allocateChannels(notes);
    const events = [];
    notes.forEach((note, id) => {
      const channel = channels.get(note.percussion ? 'drums' : note.program + ':' + note.cents);
      const startFrame = Math.max(0, Math.round(note.start * sampleRate));
      events.push({ frame: startFrame, on: true, channel, note, id });
      events.push({ frame: Math.max(startFrame + 1, Math.round(note.end * sampleRate)), on: false, channel, note, id });
    });
    // At an exact boundary release the old note before the new attack.
    events.sort((a, b) => a.frame - b.frame || Number(a.on) - Number(b.on) || a.id - b.id);
    return { channels, events };
  }

  function meterGroups(source, meter) {
    const text = (String(source).match(/^M:\s*([^\r\n%]+)/m) || [])[1] || '';
    const explicit = text.match(/\(?\s*(\d+(?:\s*\+\s*\d+)+)\s*\)?\s*\/\s*(\d+)/);
    if (explicit) return explicit[1].split('+').map(Number);
    const num = Number(meter.num), den = Number(meter.den);
    if (den === 8 && num === 7) return [3, 2, 2];
    if (den === 8 && num === 9) return [3, 3, 3];
    if (den === 8 && num === 6) return [3, 3];
    return Array.from({ length: Math.max(1, num) }, () => 1);
  }

  function countInPlan(source, meter, secondsPerWhole, bars, pickupWhole) {
    const groups = meterGroups(source, meter);
    const units = Number(meter.num), unitSeconds = secondsPerWhole / Number(meter.den);
    const barSeconds = units * unitSeconds;
    const pickup = Math.max(0, Number(pickupWhole) || 0) * secondsPerWhole;
    // One complete bar, then enough of the next bar for the pickup to land
    // before beat one. No change is made to the source or its event times.
    const delay = bars > 0 ? bars * barSeconds + (pickup > 0 ? Math.max(0, barSeconds - pickup) : 0) : 0;
    const accents = new Set([0]);
    let sum = 0; groups.forEach(n => { accents.add(sum); sum += n; });
    const beats = [];
    for (let k = 0; k * unitSeconds < delay - 1e-6; k++) {
      const inBar = k % units;
      beats.push({ at: k * unitSeconds, accent: inBar === 0 ? 2 : accents.has(inBar) ? 1 : 0, unit: inBar + 1 });
    }
    return { delay, beats, barSeconds, groups, pickupSeconds: pickup };
  }

  function bufferStats(buffers, gains, commonFrames) {
    const keys = Object.keys(buffers);
    if (!keys.length) return { rms: 0, peak: 0, frames: 0, pcmBytes: 0 };
    const frames = Math.max(Number(commonFrames)||0, ...keys.map(k => buffers[k].length));
    let sum = 0, peak = 0;
    const channels = keys.map(k => [buffers[k].getChannelData(0), buffers[k].getChannelData(Math.min(1, buffers[k].numberOfChannels - 1))]);
    for (let i = 0; i < frames; i++) {
      let l = 0, r = 0;
      for (let j = 0; j < keys.length; j++) {
        const g = gains[keys[j]] === undefined ? 1 : gains[keys[j]];
        if (i < channels[j][0].length) { l += channels[j][0][i] * g; r += channels[j][1][i] * g; }
      }
      sum += l * l + r * r; peak = Math.max(peak, Math.abs(l), Math.abs(r));
    }
    return { rms: Math.sqrt(sum / Math.max(1, frames * 2)), peak, frames,
      pcmBytes: keys.reduce((n, k) => n + buffers[k].length * buffers[k].numberOfChannels * 4, 0) };
  }

  function matchLevels(a, b) {
    if (!(a.rms > 0) || !(b.rms > 0)) throw new Error('En lydvej er tavs; sammenligningen kan ikke niveaujusteres.');
    // Approximate RMS matching, explicitly not an equal-loudness/LUFS claim.
    const target = Math.min(a.rms, b.rms);
    const trims = { A: target / a.rms, B: target / b.rms };
    const peak = Math.max(a.peak * trims.A, b.peak * trims.B);
    const headroom = peak > 0.85 ? 0.85 / peak : 1;
    return { A: trims.A * headroom, B: trims.B * headroom, targetRms: target * headroom };
  }

  return { PARTS, notesFromSequence, clipSequence, allocateChannels, createEvents, meterGroups, countInPlan, bufferStats, matchLevels };
});
"},"$:/plugins/huwiki/abc/fluid-renderer.js":{"title":"$:/plugins/huwiki/abc/fluid-renderer.js","type":"application/javascript","module-type":"library","text":"/* HUWiki Lydforsøg 01 — separate experimental renderer.
 * Uses one pinned FluidSynth/js-synthesizer instance. No wiki/plugin mutations.
 * Original HUWiki code is not changed by this module.
 */
(function (root, factory) {
  'use strict';
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  else root.HUFluidRenderer = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  const CHANNEL_COUNT = 64;
  const SLICE_MS = 14;
  const FRAME_CHUNK = 2048;
  const now = () => typeof performance !== 'undefined' ? performance.now() : Date.now();
  const yieldUI = () => new Promise(resolve => setTimeout(resolve, 0));

  function abortError() {
    const error = new Error('Lydforberedelsen blev afbrudt.');
    error.name = 'AbortError';
    return error;
  }
  function hasCancelled(value) {
    if (typeof value === 'function') return !!value();
    if (value && typeof value === 'object') return !!(value.aborted || value.cancelled);
    return value === true;
  }
  function heapSize() {
    // Exact runtime heap when exported. This is not total browser/device RAM.
    try {
      if (typeof Module !== 'undefined' && Module.HEAPU8) return Module.HEAPU8.byteLength;
      if (typeof globalThis !== 'undefined' && globalThis.Module && globalThis.Module.HEAPU8) return globalThis.Module.HEAPU8.byteLength;
    } catch (_) { /* Optional metric. */ }
    return null;
  }

