(function () {
  'use strict';

  // ABCJS writes every played occurrence (including repeats/voltas) back onto
  // the parsed note/rest as currentTrackWholeNotes. Source measures supply the
  // meter; these playback positions supply the clock. In particular, a repeat
  // may return to a different meter without another explicit M: event.
  var EPSILON = 0.00002;

  function copyMeter(meter) {
    return { num: meter.num, den: meter.den, groups: meter.groups ? meter.groups.slice() : null };
  }

  function meterKey(meter) {
    return meter.num + '/' + meter.den + ':' + (meter.groups || []).join('+');
  }

  function normalizeMeter(value) {
    if (!value) return null;
    if (value.type === 'common_time') return { num: 4, den: 4, groups: null };
    if (value.type === 'cut_time') return { num: 2, den: 2, groups: null };
    if (value.num !== undefined && value.den !== undefined) {
      value = { type: 'specified', value: [{ num: String(value.num), den: String(value.den) }] };
    }
    if (value.type !== 'specified' || !value.value || value.value.length !== 1) return null;
    var fraction = value.value[0], denominator = Number(fraction.den);
    var pieces = String(fraction.num || '').replace(/[()\s]/g, '').split('+');
    if (!pieces.length || pieces.some(function (piece) { return !/^\d+$/.test(piece); })) return null;
    var groups = pieces.map(Number), numerator = groups.reduce(function (a, b) { return a + b; }, 0);
    if (!Number.isInteger(denominator) || denominator < 1 || denominator > 128 ||
        !Number.isInteger(numerator) || numerator < 1 || numerator > 128 ||
        groups.some(function (n) { return n < 1; })) return null;
    return { num: numerator, den: denominator, groups: groups.length > 1 ? groups : null };
  }

  function occurrences(note) {
    var value = note.currentTrackWholeNotes;
    return (Array.isArray(value) ? value : [value]).filter(function (n) {
      return typeof n === 'number' && Number.isFinite(n) && n >= -EPSILON;
    });
