        (parsedTune.lines || []).forEach(function (line) {
          var staff = (line.staff || [])[other.staff];
          var voice = staff && (staff.voices || [])[other.voice];
          (voice || []).forEach(function (event) {
            if (event.el_type !== 'note') return;
