(function () {
  'use strict';

  function indexKey(value) {
    var text = String(value);
    return /^(?:0|[1-9]\d*)$/.test(text) && Number.isSafeInteger(Number(text)) ? text : null;
  }

  function level(value, fallback) {
    if (value === undefined || value === null || value === '' || typeof value === 'boolean') return fallback;
    var number = Number(value);
    return Number.isFinite(number) ? Math.max(0, Math.min(100, Math.round(number))) : fallback;
  }

  function instrument(value, fallback) {
    if (value === 'source' || value === 'inherit') return value;
    if (value === undefined || value === null || value === '' || typeof value === 'boolean') return fallback;
    var number = Number(value);
    return Number.isInteger(number) && number >= 0 && number <= 127 ? number : fallback;
  }

  // Normalize only the voiceSettings dictionary; callers normalize bassSource
  // separately. Omitted voices use inherit / 100% / audible without adding keys.
  function clean(settings) {
    var result = {};
    if (!settings || typeof settings !== 'object' || Array.isArray(settings)) return result;
    Object.keys(settings).forEach(function (key) {
      var valid = indexKey(key), item = settings[key];
      if (valid === null || !item || typeof item !== 'object' || Array.isArray(item)) return;
      result[valid] = {
        instrument: instrument(item.instrument, 'inherit'),
        volume: level(item.volume, 100),
        muted: item.muted === true
      };
    });
    return result;
  }

  function bassSource(value) {
    if (value === 'none' || value === 'style') return value;
    var match = typeof value === 'string' && value.match(/^voice:(0|[1-9]\d*)$/);
    return match && indexKey(match[1]) !== null ? 'voice:' + match[1] : 'style';
  }

  function selectedBass(config, trackCount) {
    var value = bassSource(config && config.bassSource), match = value.match(/^voice:(\d+)$/);
    var index = match ? Number(match[1]) : -1;
    return Number.isInteger(trackCount) && index >= 0 && index < trackCount ? index : -1;
  }

  function percussion(track) {
    return (track || []).some(function (event) {
      return event && ((event.cmd === 'program' && Number(event.channel) === 9) ||
        ((event.cmd === 'program' || event.cmd === 'note') && Number(event.instrument) === 128));
    });
  }

  function sourceVoiceNames(source) {
    var names = Object.create(null), selectors = [], match;
    var pattern = /(?:^|\n)[ \t]*V:\s*([^\s\]]+)([^\r\n]*)|\[V:\s*([^\s\]]+)([^\]]*)\]/g;
    while ((match = pattern.exec(String(source || ''))) !== null) {
      var id = match[1] || match[3], tail = match[2] || match[4] || '';
      var name = tail.match(/\b(?:name|nm)\s*=\s*(?:"((?:\\.|[^"\\])*)"|'([^']*)'|([^\s]+))/);
      if (name) names[id] = (name[1] !== undefined ? name[1] : name[2] !== undefined ? name[2] : name[3]).replace(/\\(["\\])/g, '$1');
      selectors.push({ at: match.index, id: id });
    }
    return {
      nameAt: function (position) {
        var id = null;
        if (Number.isFinite(position)) {
          for (var i = 0; i < selectors.length && selectors[i].at <= position; i++) id = selectors[i].id;
        }
        return id ? (names[id] || 'V:' + id) : '';
      }
    };
  }

  function parsedVoices(tune) {
    var byKey = Object.create(null), list = [];
    (tune.lines || []).forEach(function (line) {
      (line.staff || []).forEach(function (staff, staffIndex) {
        (staff.voices || []).forEach(function (voice, voiceIndex) {
          var key = staffIndex + ':' + voiceIndex;
          if (!byKey[key]) {
            byKey[key] = { name: '', sourceStart: Infinity };
            list.push(byKey[key]);
          }
          var item = byKey[key];
          if (!item.name && staff.title && staff.title[voiceIndex]) item.name = String(staff.title[voiceIndex]).trim();
          voice.forEach(function (event) {
            if (event.el_type === 'note' && Number.isFinite(event.startChar) && event.startChar >= 0) item.sourceStart = Math.min(item.sourceStart, event.startChar);
          });
        });
      });
    });
    return list;
  }

  function describe(ABC, source) {
    if (!ABC || typeof ABC.parseOnly !== 'function') return [];
    var tune = ABC.parseOnly(String(source || ''))[0];
    if (!tune || typeof tune.setUpAudio !== 'function') return [];
    // Work on this newly parsed tune only. Automatic MIDI accompaniments are not
    // notated voices and must never appear in the routing menu.
    var managed = /^(?:gchord.*|bassprog|bassvol|chordprog|chordvol|drum|drumon|drumoff|drumbars)$/;
    if (tune.formatting && tune.formatting.midi) Object.keys(tune.formatting.midi).forEach(function (key) {
      if (managed.test(key)) delete tune.formatting.midi[key];
    });
    (tune.lines || []).forEach(function (line) {
      (line.staff || []).forEach(function (staff) {
        (staff.voices || []).forEach(function (voice) {
          for (var i = voice.length - 1; i >= 0; i--) if (voice[i].el_type === 'midi' && managed.test(voice[i].cmd)) voice.splice(i, 1);
        });
      });
    });
    var voices = parsedVoices(tune), names = sourceVoiceNames(source);
    var sequence = tune.setUpAudio({ chordsOff: true, drum: '', drumIntro: 0 });
    return Array.from(sequence.tracks || [], function (track, index) {
      var voice = voices[index] || {}, text = track.find(function (event) { return event.cmd === 'text' && event.type === 'name'; });
      var program = track.find(function (event) { return event.cmd === 'program' && Number.isFinite(Number(event.instrument)); });
      if (!program) program = track.find(function (event) { return event.cmd === 'note' && Number.isFinite(Number(event.instrument)); });
      return {
        index: index,
        name: names.nameAt(voice.sourceStart) || voice.name || (text && String(text.text || '').trim()) || 'V:' + (index + 1),
        program: program ? Number(program.instrument) : 0,
        isPercussion: percussion(track)
      };
    });
  }

  function apply(baseSequence, config, live) {
    config = config || {};
    var tracks = baseSequence && Array.isArray(baseSequence.tracks) ? baseSequence.tracks : [];
    var selected = selectedBass(config, tracks.length), settings = clean(config.voiceSettings);
    var used = new Set();
    tracks.forEach(function (track) {
      track.forEach(function (event) {
        if (event.cmd === 'program' && Number.isInteger(event.channel) && event.channel >= 0 && event.channel <= 15) used.add(event.channel);
      });
    });
    function pitchedChannel(track) {
      var existing = track.find(function (event) {
        return event.cmd === 'program' && Number.isInteger(event.channel) && event.channel >= 0 && event.channel <= 15 && event.channel !== 9;
      });
      if (existing) return existing.channel;
      for (var channel = 0; channel < 16; channel++) {
        if (channel !== 9 && !used.has(channel)) { used.add(channel); return channel; }
      }
      throw new Error('Der er ikke en ledig melodisk MIDI-kanal til det valgte instrument.');
    }
    var routed = tracks.map(function (track, index) {
      var setting = settings[String(index)] || { instrument: 'inherit', volume: 100, muted: false };
      var isBass = index === selected, isDrum = percussion(track);
      var chosen = setting.instrument === 'inherit' ?
        instrument(isBass ? config.bassInstrument : config.melodyInstrument, 'source') : setting.instrument;
      var explicit = typeof setting.instrument === 'number';
      // A global melodic instrument selector must not turn notated percussion
      // into pitched notes. Per-voice GM selection is the explicit exception.
      if (isDrum && !explicit) chosen = 'source';
      var changeInstrument = typeof chosen === 'number';
      var newChannel = isDrum && explicit ? pitchedChannel(track) : null;
      var master = live ? 100 : level(isBass ? config.bassVolume : config.melodyVolume, 100);
      var factor = setting.muted ? 0 : setting.volume / 100 * master / 100;
      var copy = track.map(function (event) {
        var out = Object.assign({}, event);
        if (changeInstrument && (event.cmd === 'program' || event.cmd === 'note')) out.instrument = chosen;
        if (newChannel !== null && (event.cmd === 'program' || event.cmd === 'note') && Number(event.channel) === 9) out.channel = newChannel;
        if (event.cmd === 'note' && factor !== 1) {
          if (factor === 0) out.volume = 0;
          else if (Number.isFinite(Number(event.volume))) out.volume = Math.max(0, Math.min(127, Math.round(Number(event.volume) * factor)));
        }
        return out;
      });
      // Array metadata is used by both sound engines and is not copied by map.
      Object.keys(track).forEach(function (key) { if (!/^(?:0|[1-9]\d*)$/.test(key)) copy[key] = track[key]; });
      copy.huwabcVoice = String(index);
      delete copy.huwabcPart;
      if (isBass) copy.huwabcPart = 'bassVolume';
      return copy;
    });
    return Object.assign({}, baseSequence || {}, { tracks: routed });
  }

  exports.clean = clean;
  exports.bassSource = bassSource;
  exports.describe = describe;
  exports.selectedBass = selectedBass;
  exports.apply = apply;
})();
