title: $:/plugins/huwiki/abc/voice-controls.js
type: application/javascript
module-type: library
\*/
(function () {
  'use strict';

  var Routing = require('$:/plugins/huwiki/abc/voice-routing.js');
  var nextId = 0;
  // General MIDI programs are zero-based in ABCJS and in saved settings.
  var gmNames = [
    'Acoustic Grand Piano', 'Bright Acoustic Piano', 'Electric Grand Piano', 'Honky-tonk Piano',
    'Electric Piano 1', 'Electric Piano 2', 'Harpsichord', 'Clavinet',
    'Celesta', 'Glockenspiel', 'Music Box', 'Vibraphone', 'Marimba', 'Xylophone', 'Tubular Bells', 'Dulcimer',
    'Drawbar Organ', 'Percussive Organ', 'Rock Organ', 'Church Organ', 'Reed Organ', 'Accordion', 'Harmonica', 'Tango Accordion',
    'Acoustic Guitar (nylon)', 'Acoustic Guitar (steel)', 'Electric Guitar (jazz)', 'Electric Guitar (clean)',
    'Electric Guitar (muted)', 'Overdriven Guitar', 'Distortion Guitar', 'Guitar Harmonics',
    'Acoustic Bass', 'Electric Bass (finger)', 'Electric Bass (pick)', 'Fretless Bass', 'Slap Bass 1', 'Slap Bass 2', 'Synth Bass 1', 'Synth Bass 2',
    'Violin', 'Viola', 'Cello', 'Contrabass', 'Tremolo Strings', 'Pizzicato Strings', 'Orchestral Harp', 'Timpani',
    'String Ensemble 1', 'String Ensemble 2', 'Synth Strings 1', 'Synth Strings 2', 'Choir Aahs', 'Voice Oohs', 'Synth Voice', 'Orchestra Hit',
    'Trumpet', 'Trombone', 'Tuba', 'Muted Trumpet', 'French Horn', 'Brass Section', 'Synth Brass 1', 'Synth Brass 2',
    'Soprano Sax', 'Alto Sax', 'Tenor Sax', 'Baritone Sax', 'Oboe', 'English Horn', 'Bassoon', 'Clarinet',
    'Piccolo', 'Flute', 'Recorder', 'Pan Flute', 'Blown Bottle', 'Shakuhachi', 'Whistle', 'Ocarina',
    'Lead 1 (square)', 'Lead 2 (sawtooth)', 'Lead 3 (calliope)', 'Lead 4 (chiff)', 'Lead 5 (charang)', 'Lead 6 (voice)', 'Lead 7 (fifths)', 'Lead 8 (bass + lead)',
    'Pad 1 (new age)', 'Pad 2 (warm)', 'Pad 3 (polysynth)', 'Pad 4 (choir)', 'Pad 5 (bowed)', 'Pad 6 (metallic)', 'Pad 7 (halo)', 'Pad 8 (sweep)',
    'FX 1 (rain)', 'FX 2 (soundtrack)', 'FX 3 (crystal)', 'FX 4 (atmosphere)', 'FX 5 (brightness)', 'FX 6 (goblins)', 'FX 7 (echoes)', 'FX 8 (sci-fi)',
    'Sitar', 'Banjo', 'Shamisen', 'Koto', 'Kalimba', 'Bag Pipe', 'Fiddle', 'Shanai',
    'Tinkle Bell', 'Agogo', 'Steel Drums', 'Woodblock', 'Taiko Drum', 'Melodic Tom', 'Synth Drum', 'Reverse Cymbal',
    'Guitar Fret Noise', 'Breath Noise', 'Seashore', 'Bird Tweet', 'Telephone Ring', 'Helicopter', 'Applause', 'Gunshot'
  ];

  function copyConfig(config) {
    var next = Object.assign({}, config && typeof config === 'object' ? config : {});
    next.voiceSettings = Routing.clean(next.voiceSettings);
    return next;
  }

  function programName(ABC, index) {
    var names = ABC && ABC.synth && ABC.synth.instrumentIndexToName, found;
    try { found = typeof names === 'function' ? names(index) : names && names[index]; }
    catch (_) { found = null; }
    if (typeof found !== 'string' || !found.trim()) return gmNames[index];
    found = found.replace(/_/g, ' ').trim();
    return found.charAt(0).toUpperCase() + found.slice(1);
  }

  function mount(parent, ABC, source, getConfig, onChange) {
    var doc = parent && parent.ownerDocument || (typeof document !== 'undefined' ? document : null);
    if (!doc || !parent || typeof parent.appendChild !== 'function') {
      return { element: null, update: function () {} };
    }
    var prefix = 'huwabc-voice-' + (++nextId) + '-', voices = [], parseFailed = false;
    var current = {}, rows = [], unavailableOption = null;

    function E(tag, className, text) {
      var node = doc.createElement(tag);
      if (className) node.className = className;
      if (text !== undefined) node.textContent = text;
      return node;
    }
    function option(select, value, text) {
      var item = E('option', '', text);
      item.value = String(value);
      select.appendChild(item);
      return item;
    }
    function label(control, text, container) {
      var node = E('label', 'huwabc-voice-label', text);
      node.setAttribute('for', control.id);
      container.appendChild(node);
      return node;
    }
    function read() {
      var value;
      try { value = typeof getConfig === 'function' ? getConfig() : getConfig; }
      catch (_) { value = null; }
      return copyConfig(value && typeof value === 'object' ? value : current);
    }
    function voiceSetting(config, index) {
      return Routing.clean(config.voiceSettings)[String(index)] || { instrument: 'inherit', volume: 100, muted: false };
    }
    function commit(change) {
      var next = read();
      change(next);
      current = next;
      update(next);
      if (typeof onChange === 'function') onChange(next);
    }
    function changeVoice(index, key, value) {
      commit(function (next) {
        var setting = Object.assign({}, voiceSetting(next, index));
        setting[key] = value;
        next.voiceSettings[String(index)] = setting;
      });
    }
    function voiceLabel(voice) {
      return 'Stemme ' + (voice.index + 1) + (voice.name ? ' · ' + voice.name : '');
    }

    var details = E('details', 'huwabc-voice-controls');
    details.appendChild(E('summary', 'huwabc-voice-summary', 'Noterede stemmer · instrumenter og lydstyrke'));
    var body = E('div', 'huwabc-voice-body');
    details.appendChild(body);

    try {
      var described = Routing.describe(ABC, String(source || ''));
      if (Array.isArray(described)) voices = described.filter(function (voice) {
        return voice && Number.isInteger(voice.index) && voice.index >= 0;
      });
    } catch (_) { parseFailed = true; }

    var bassField = E('div', 'huwabc-voice-field huwabc-voice-bass-field');
    var bassSelect = E('select', 'huwabc-voice-bass-select');
    bassSelect.id = prefix + 'bass-source';
    label(bassSelect, 'Bas fra', bassField);
    option(bassSelect, 'style', 'Becifringer og stilart');
    option(bassSelect, 'none', 'Ingen genereret bas');
    voices.forEach(function (voice) { option(bassSelect, 'voice:' + voice.index, voiceLabel(voice)); });
    bassSelect.addEventListener('change', function () {
      var selected = Routing.bassSource(bassSelect.value);
      commit(function (next) { next.bassSource = selected; });
    });
    bassField.appendChild(bassSelect);
    var bassHint = E('p', 'huwabc-voice-hint');
    bassHint.id = prefix + 'bass-hint';
    bassSelect.setAttribute('aria-describedby', bassHint.id);
    bassField.appendChild(bassHint);
    body.appendChild(bassField);

    if (!voices.length) {
      body.appendChild(E('p', 'huwabc-voice-empty huwabc-muted', parseFailed ?
        'Stemmerne kunne ikke læses. Kontrollér ABC-koden.' : 'Ingen noterede stemmer fundet i ABC-koden.'));
    } else {
      body.appendChild(E('p', 'huwabc-voice-hint', 'Ændringer af stemmerne gælder fra næste afspilning.'));
    }
    var list = E('div', 'huwabc-voice-list');
    body.appendChild(list);
    voices.forEach(function (voice) {
      var key = String(voice.index), row = E('fieldset', 'huwabc-voice-row');
      row.setAttribute('data-voice-index', key);
      var legend = E('legend', 'huwabc-voice-name');
      legend.appendChild(E('span', '', 'Stemme'));
      legend.appendChild(doc.createTextNode(' ' + (voice.index + 1) + (voice.name ? ' · ' : '')));
      if (voice.name) legend.appendChild(E('span', 'huwabc-voice-source-name', voice.name));
      row.appendChild(legend);
      var role = E('p', 'huwabc-voice-role');
      row.appendChild(role);
      var fields = E('div', 'huwabc-voice-fields');
      row.appendChild(fields);

      var instrumentField = E('div', 'huwabc-voice-field huwabc-voice-instrument-field');
      var instrument = E('select', 'huwabc-voice-instrument');
      instrument.id = prefix + key + '-instrument';
      label(instrument, 'Instrument', instrumentField);
      option(instrument, 'inherit', 'Følg mixerens instrument');
      option(instrument, 'source', 'Som noteret i ABC');
      for (var program = 0; program < 128; program++) option(instrument, program, programName(ABC, program));
      instrument.addEventListener('change', function () {
        var value = instrument.value;
        changeVoice(voice.index, 'instrument', value === 'source' || value === 'inherit' ? value : Number(value));
      });
      instrumentField.appendChild(instrument);
      fields.appendChild(instrumentField);

      var volumeField = E('div', 'huwabc-voice-field huwabc-voice-volume-field');
      var slider = E('input', 'huwabc-voice-volume');
      slider.type = 'range'; slider.min = '0'; slider.max = '100'; slider.step = '1';
      slider.id = prefix + key + '-volume';
      label(slider, 'Lydstyrke', volumeField);
      var volumeControls = E('div', 'huwabc-voice-volume-controls');
      var value = E('output', 'huwabc-voice-volume-value');
      value.setAttribute('for', slider.id);
      slider.addEventListener('input', function () { value.textContent = slider.value + '%'; });
      slider.addEventListener('change', function () { changeVoice(voice.index, 'volume', Number(slider.value)); });
      volumeControls.appendChild(slider); volumeControls.appendChild(value);
      volumeField.appendChild(volumeControls);
      fields.appendChild(volumeField);

      var muteLabel = E('label', 'huwabc-voice-audible');
      var audible = E('input', 'huwabc-voice-audible-input');
      audible.type = 'checkbox'; audible.id = prefix + key + '-audible';
      muteLabel.setAttribute('for', audible.id);
      muteLabel.appendChild(audible);
      muteLabel.appendChild(E('span', '', 'Lyd til'));
      audible.addEventListener('change', function () { changeVoice(voice.index, 'muted', !audible.checked); });
      fields.appendChild(muteLabel);
      list.appendChild(row);
      rows.push({ index: voice.index, row: row, role: role, instrument: instrument, slider: slider, value: value, audible: audible });
    });

    function update(config) {
      current = config && typeof config === 'object' ? copyConfig(config) : read();
      var bass = Routing.bassSource(current.bassSource);
      var available = bass === 'style' || bass === 'none' || voices.some(function (voice) { return bass === 'voice:' + voice.index; });
      if (unavailableOption) { bassSelect.removeChild(unavailableOption); unavailableOption = null; }
      if (!available) {
        unavailableOption = option(bassSelect, bass, 'Den valgte basstemme findes ikke i nodearket');
        unavailableOption.disabled = true;
      }
      bassSelect.value = bass;
      bassHint.textContent = bass === 'style' ? 'Bassen følger becifringerne og stilens basmønster.' :
        bass === 'none' ? 'Stilens bas er slået fra. Noterede stemmer spiller stadig.' :
        available ? 'Den valgte stemme erstatter stilens bas og følger basmixeren. Du kan vælge dens eget instrument nedenfor.' :
        'Den valgte basstemme findes ikke i nodearket';
      rows.forEach(function (row) {
        var setting = voiceSetting(current, row.index), isBass = bass === 'voice:' + row.index;
        row.instrument.value = String(setting.instrument);
        row.slider.value = String(setting.volume);
        row.value.textContent = setting.volume + '%';
        row.audible.checked = !setting.muted;
        row.role.textContent = isBass ? 'Basstemme · følger basmixeren' : 'Følger melodimixeren';
        row.row.className = 'huwabc-voice-row' + (isBass ? ' huwabc-voice-is-bass' : '') + (setting.muted ? ' huwabc-voice-is-muted' : '');
      });
    }

    parent.appendChild(details);
    update();
    return { element: details, update: update };
  }

  exports.mount = mount;
})();
"},"$:/plugins/huwiki/abc/voice-controls.css":{"title":"$:/plugins/huwiki/abc/voice-controls.css","type":"text/css","tags":"$:/tags/Stylesheet","text":"/* Per-voice playback controls; shared by the wiki and exported Site players. */
.huwabc-voice-controls {
  margin: .75rem 0;
  border: 1px solid #a6b2bd;
  border-radius: .5rem;
  max-width: 100%;
  color: inherit;
}
.huwabc-voice-summary {
  cursor: pointer;
  padding: .6rem .75rem;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.huwabc-voice-body { padding: 0 .75rem .75rem; }
.huwabc-voice-list { display: grid; gap: .7rem; margin-top: .75rem; }
.huwabc-voice-row {
  border: 1px solid #bbc4cc;
  border-radius: .4rem;
  margin: 0;
  padding: .55rem .7rem .7rem;
  min-width: 0;
}
.huwabc-voice-row.huwabc-voice-is-bass { border-color: #617f97; border-inline-start-width: 3px; }
.huwabc-voice-name { font-weight: 600; padding: 0 .25rem; max-width: 100%; overflow-wrap: anywhere; }
.huwabc-voice-role, .huwabc-voice-hint, .huwabc-voice-empty {
  font-size: .88em;
  line-height: 1.4;
  margin: .25rem 0 .5rem;
  opacity: .8;
}
.huwabc-voice-fields { display: flex; flex-wrap: wrap; gap: .65rem 1rem; align-items: end; }
.huwabc-voice-field { min-width: 0; }
.huwabc-voice-label { display: block; font-size: .9em; margin: 0 0 .2rem; }
.huwabc-voice-instrument-field { flex: 2 1 14rem; }
.huwabc-voice-volume-field { flex: 1 1 11rem; }
.huwabc-voice-controls select {
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-height: 2.25rem;
  margin: 0;
  font: inherit;
}
.huwabc-voice-bass-field > select { max-width: 34rem; }
.huwabc-voice-volume-controls { display: flex; gap: .5rem; align-items: center; min-height: 2.25rem; }
.huwabc-voice-volume-controls input[type="range"] { flex: 1; min-width: 3rem; width: 100%; margin: 0; }
.huwabc-voice-volume-value { flex: 0 0 3.3em; text-align: end; font-variant-numeric: tabular-nums; }
.huwabc-voice-audible { display: inline-flex; align-items: center; gap: .45rem; min-height: 2.25rem; margin: 0; white-space: nowrap; }
.huwabc-voice-audible input { margin: 0; }
.huwabc-voice-is-muted .huwabc-voice-role { opacity: .6; }
.huwabc-voice-controls :focus-visible { outline: 2px solid #4b84b0; outline-offset: 2px; }
@media (max-width: 480px) {
  .huwabc-voice-body { padding-inline: .5rem; }
  .huwabc-voice-row { padding-inline: .5rem; }
  .huwabc-voice-instrument-field { flex-basis: 100%; }
}
"},"$:/plugins/huwiki/abc/repeat-plan.js":{"title":"$:/plugins/huwiki/abc/repeat-plan.js","type":"application/javascript","module-type":"library","text":"/*\
title: $:/plugins/huwiki/abc/repeat-plan.js
type: application/javascript
module-type: library
\*/
(function () {
'use strict';
var EPS = 0.00002, MAX_COUNT = 16, MAX_BARS = 20000;

var RENDER_FIELDS={abselem:true,abcelem:true,graphelem:true,elemset:true,parent:true,staffGroup:true,engraver:true};
function clone(value,ancestors) {
 if (typeof value === 'function') return undefined;
 if (!value || typeof value !== 'object') return value;
 // ABCJS's real draw pass adds event.abselem.abcelem === event, including
 // staff clefs, keys and meters. Headers need music data, never that graph.
 if (typeof value.nodeType === 'number') return undefined;
 ancestors=ancestors||new Set();if(ancestors.has(value))return undefined;
 ancestors.add(value);
 var out;
 if(Array.isArray(value))out=value.map(function(item){return clone(item,ancestors);});
 else {
  out={};Object.keys(value).forEach(function(k){
   if(Object.prototype.hasOwnProperty.call(RENDER_FIELDS,k))return;
   var copied=clone(value[k],ancestors);if(copied!==undefined)out[k]=copied;
  });
 }
 ancestors.delete(value);return out;
}
function clean(value) {
 var out={}; if(!value||typeof value!=='object'||Array.isArray(value))return out;
 Object.keys(value).slice(0,512).sort().forEach(function(id){
  var n=Number(value[id]);if(/^r[\w-]+$/.test(id)&&Number.isInteger(n)&&n>=1&&n<=MAX_COUNT)out[id]=n;
 });return out;
}
function header(staff,previous) {
 var out=Object.assign({},previous||{});
 ['clef','key','meter','title','stafflines','staffscale','scale','brace','bracket','connectBarLines','vocalfont'].forEach(function(k){
  if(staff[k]!==undefined)out[k]=clone(staff[k]);
 });return out;
}
// Written measures are collected independently of ABCJS's playback traversal.
// Keep original event references so the playback adapter can transfer timing
// occurrences back to the displayed score without editing the source.
function collect(tune) {
 var byKey=Object.create(null),voices=[];
 function voiceFor(si,vi){var key=si+':'+vi;if(!byKey[key]){
  byKey[key]={staffIndex:si,voiceIndex:vi,header:{},measures:[],boundaries:[],annotations:[],pending:[],active:null,clock:0,triplet:1,sounding:0};voices.push(byKey[key]);
 }return byKey[key];}
 function boundary(v){var n=v.measures.length;return v.boundaries[n]||(v.boundaries[n]={index:n,events:[],startEnding:null,endEnding:false});}
 function annotations(v,e,isBar){(e.chord||[]).forEach(function(c){
  if(c.position&&c.position!=='default'&&typeof c.name==='string')v.annotations.push({name:c.name,bar:v.measures.length,isBar:isBar,event:e,offset:v.active?v.active.duration:0});
 });}
 function flush(v){if(!v.active||v.active.duration<=EPS)return;
  v.active.index=v.measures.length;v.active.start=v.clock;v.clock+=v.active.duration;v.measures.push(v.active);v.active=null;
 }
 (tune.lines||[]).forEach(function(line){(line.staff||[]).forEach(function(staff,si){if(staff.isTabStaff)return;(staff.voices||[]).forEach(function(events,vi){
  var v=voiceFor(si,vi);v.header=header(staff,v.header);
  events.forEach(function(e){
   if(e.el_type==='bar'){
    if(v.active&&v.active.duration>EPS){v.active.events.push(e);flush(v);}else v.pending.push(e);
    var b=boundary(v);b.events.push(e);if(e.startEnding)b.startEnding=String(e.startEnding);if(e.endEnding)b.endEnding=true;
    annotations(v,e,true);return;
   }
