      var groups = renderedMeasures(entries, state.model.voices[voiceIndex], voiceIndex), tempos = [], currentTempo = tune.getBpm(tune.metaText && tune.metaText.tempo);
      groups.forEach(function (group, index) {
        group.forEach(function (entry) {
          if (entry.elem.type === 'tempo') { currentTempo = tune.getBpm(entry.elem.abcelem); hasTempo = true; }
        });
        tempos[index] = currentTempo;
      });
      var played = [];
      state.plan.order.forEach(function (writtenIndex, index) {
        tempoLocations[index] = tempos[writtenIndex];
        groups[writtenIndex].forEach(function (entry) {
          var absolute = Object.assign({}, entry.elem);
          absolute.abcelem = Object.assign({}, entry.elem.abcelem);
          if (absolute.type === 'bar') {
            absolute.abcelem.type = 'bar_thin';
            delete absolute.abcelem.startEnding;
            delete absolute.abcelem.endEnding;
          }
          // elemset and all coordinates still refer to the existing score DOM.
          played.push(Object.assign({}, entry, { measureNumber: index, elem: absolute }));
        });
      });
      return played;
    });
    tune.tempoLocations = hasTempo ? tempoLocations : {};
    return result;
  }

  function install(tune, plan) {
    if (!tune) return tune;
    var state = tune._huwabcRepeatPlayback;
    if (!plan || !plan.active) {
      if (state) { state.plan = null; delete tune.noteTimings; }
      return tune;
    }
    if (state) {
      validate(state.model, plan);
      state.plan = plan;
      delete tune.noteTimings;
      return tune;
    }
    var model = Planner.collect(tune);
    validate(model, plan);
    state = { model: model, plan: plan, audio: tune.setUpAudio, voices: tune.makeVoicesArray };
    if (typeof state.audio !== 'function') throw new Error('Gentagelser: ABC-afspilleren mangler.');
    Object.defineProperty(tune, '_huwabcRepeatPlayback', { value: state, configurable: true });
    tune.setUpAudio = function (options) {
      if (!state.plan) return state.audio.call(this, options);
      var linear = linearTune(this, state, options || {});
      var sequence = state.audio.call(linear.tune, options);
      transferTimings(state.model, linear.noteCopies);
      return sequence;
    };
    if (typeof state.voices === 'function') tune.makeVoicesArray = function () {
      var voices = state.voices.call(this);
      return state.plan ? playbackVoices(this, state, voices) : voices;
    };
    delete tune.noteTimings;
    return tune;
  }

  exports.install = install;
})();
