title: $:/plugins/huwiki/abc/repeat-controls.js
type: application/javascript
module-type: library
\*/
(function () {
  'use strict';

  var RepeatPlan = require('$:/plugins/huwiki/abc/repeat-plan.js');
  var nextId = 0;

  function cleanCounts(value) {
    var result = Object.create(null);
    if (!value || typeof value !== 'object' || Array.isArray(value)) return result;
    Object.keys(value).forEach(function (id) {
      var count = Number(value[id]);
      if (Number.isInteger(count) && count >= 1 && count <= 16) result[id] = count;
    });
    return result;
  }

  function copyConfig(config) {
    var next = Object.assign({}, config && typeof config === 'object' ? config : {});
    next.repeatCounts = cleanCounts(next.repeatCounts);
    return next;
  }

  function countText(count) { return count + (count === 1 ? ' gang' : ' gange'); }

  function mount(parent, ABC, source, getConfig, onChange) {
    var doc = parent && parent.ownerDocument || (typeof document !== 'undefined' ? document : null);
    if (!doc || !parent || typeof parent.appendChild !== 'function') {
      return { element: null, update: function () {} };
    }
    var prefix = 'huwabc-repeat-' + (++nextId) + '-', current = {}, rows = [];

    function E(tag, className, text) {
      var node = doc.createElement(tag);
      if (className) node.className = className;
      if (text !== undefined) node.textContent = text;
      return node;
    }
    function option(select, value, text) {
      var item = E('option', '', text);
      item.value = String(value);
      select.appendChild(item);
      return item;
    }
    function read() {
      var value;
      try { value = typeof getConfig === 'function' ? getConfig() : getConfig; }
      catch (_) { value = null; }
      return copyConfig(value && typeof value === 'object' ? value : current);
    }
    function commit(id, value) {
      var next = read();
      if (value === '') delete next.repeatCounts[id];
      else {
        var count = Number(value);
        if (!Number.isInteger(count) || count < 1 || count > 16) { update(); return; }
        next.repeatCounts[id] = count;
      }
      current = next;
      update(next);
      // A native host can rebuild its player after a change and restore this
      // state on the newly mounted details element. Shared Site hosts can use
      // update() without rebuilding, which also preserves the open state.
      if (typeof onChange === 'function') onChange(next, { open: !!details.open });
    }

    var details = E('details', 'huwabc-repeat-controls');
    details.appendChild(E('summary', 'huwabc-repeat-summary', 'Gentagelser · antal gennemspilninger'));
    var body = E('div', 'huwabc-repeat-body');
    details.appendChild(body);
    current = read();

    var sections = [], parseFailed = false;
    try {
      var plan = RepeatPlan.build(ABC, String(source || ''), current.repeatCounts);
      var described = Array.isArray(plan) ? plan : plan && plan.sections;
      if (!Array.isArray(described)) throw new Error('Missing repeat sections');
      sections = described.filter(function (section) {
        return section && typeof section.id === 'string' && section.id.length > 0 &&
          Number.isInteger(section.startBar) && section.startBar >= 0 &&
          Number.isInteger(section.endBar) && section.endBar >= section.startBar;
      });
    } catch (_) { parseFailed = true; }

    if (!sections.length) {
      var empty = E('p', 'huwabc-repeat-empty huwabc-muted', parseFailed ?
        'Gentagelserne kunne ikke læses. Kontrollér ABC-koden.' : 'Ingen gentagelsesafsnit fundet.');
      empty.setAttribute('role', 'status');
      body.appendChild(empty);
    } else {
      var help = E('p', 'huwabc-repeat-hint', '3 gange betyder tre gennemspilninger i alt.');
      help.id = prefix + 'help';
      body.appendChild(help);
      body.appendChild(E('p', 'huwabc-repeat-hint', 'Gx3, ×3 og 4 gange over noderne læses automatisk.'));
      body.appendChild(E('p', 'huwabc-repeat-hint', 'Ændringer gælder fra næste afspilning.'));
      var list = E('div', 'huwabc-repeat-list');
      body.appendChild(list);

      sections.forEach(function (section, index) {
        var row = E('div', 'huwabc-repeat-row');
        row.setAttribute('data-repeat-section', section.id);
        var select = E('select', 'huwabc-repeat-count');
        select.id = prefix + index + '-count';
        select.setAttribute('aria-describedby', help.id);

        var label = E('label', 'huwabc-repeat-label');
        label.setAttribute('for', select.id);
        var name = E('span', 'huwabc-repeat-name');
        var sourceLabel = typeof section.label === 'string' ? section.label.trim() : '';
        var automatic = sourceLabel.match(/^Afsnit\s+(\d+)$/);
        if (!sourceLabel || automatic) {
          name.appendChild(E('span', '', 'Afsnit'));
          name.appendChild(doc.createTextNode(' ' + (automatic ? automatic[1] : index + 1)));
        } else name.textContent = sourceLabel;
        label.appendChild(name);
        var bars = E('span', 'huwabc-repeat-bars');
        bars.appendChild(E('span', '', 'takt'));
        bars.appendChild(doc.createTextNode(' ' + (section.startBar + 1) +
          (section.endBar === section.startBar ? '' : '–' + (section.endBar + 1))));
        label.appendChild(bars);
        row.appendChild(label);

        var notated = Number(section.notatedCount);
        if (!Number.isInteger(notated) || notated < 1) notated = 2;
        option(select, '', 'Som noteret (' + countText(notated) + ')');
        for (var count = 1; count <= 16; count++) option(select, count, countText(count));
        select.addEventListener('change', function () { commit(section.id, select.value); });
        row.appendChild(select);
        list.appendChild(row);
        rows.push({ id: section.id, notated: notated, row: row, select: select });
      });
    }

    function update(config) {
      current = config && typeof config === 'object' ? copyConfig(config) : read();
      rows.forEach(function (row) {
        var count = current.repeatCounts[row.id], overridden = count !== undefined;
        row.select.value = overridden ? String(count) : '';
        row.row.className = 'huwabc-repeat-row' + (overridden ? ' huwabc-repeat-is-custom' : '');
        row.row.setAttribute('data-repeat-count', String(overridden ? count : row.notated));
      });
    }

    parent.appendChild(details);
    update(current);
    return { element: details, update: update };
  }

  exports.mount = mount;
})();
"},"$:/plugins/huwiki/abc/repeat-controls.css":{"title":"$:/plugins/huwiki/abc/repeat-controls.css","type":"text/css","tags":"$:/tags/Stylesheet","text":"/* Repeat counts shared by the wiki and exported Site players. */
.huwabc-repeat-controls {
  margin: .75rem 0;
  border: 1px solid #a6b2bd;
  border-radius: .5rem;
  max-width: 100%;
  color: inherit;
}
.huwabc-repeat-summary {
  cursor: pointer;
  padding: .6rem .75rem;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.huwabc-repeat-body { padding: 0 .75rem .75rem; }
.huwabc-repeat-hint, .huwabc-repeat-empty {
  font-size: .88em;
  line-height: 1.4;
  margin: .25rem 0 .5rem;
  opacity: .8;
}
.huwabc-repeat-list { display: grid; gap: .5rem; margin-top: .75rem; }
.huwabc-repeat-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(10rem, 14rem);
  align-items: center;
  gap: .5rem 1rem;
  border: 1px solid #bbc4cc;
  border-radius: .4rem;
  padding: .55rem .7rem;
  min-width: 0;
}
.huwabc-repeat-row.huwabc-repeat-is-custom { border-color: #617f97; }
.huwabc-repeat-label { margin: 0; min-width: 0; overflow-wrap: anywhere; }
.huwabc-repeat-name { display: block; font-weight: 600; }
.huwabc-repeat-bars { display: block; font-size: .88em; opacity: .8; margin-top: .1rem; }
.huwabc-repeat-count {
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 2.25rem;
  margin: 0;
  font: inherit;
}
.huwabc-repeat-controls :focus-visible { outline: 2px solid #4b84b0; outline-offset: 2px; }
@media (max-width: 480px) {
  .huwabc-repeat-body { padding-inline: .5rem; }
  .huwabc-repeat-row { grid-template-columns: minmax(0, 1fr); padding-inline: .5rem; }
}
"},"HUWiki ABC – Gentagelser":{"title":"HUWiki ABC – Gentagelser","type":"text/vnd.tiddlywiki","tags":"ABC Hjælp","huwiki-title-da":"ABC – Gentagelser","huwiki-title-en":"ABC – Repeats","huwiki-text-da":"! Gentagelser · antal gennemspilninger

Fra v0.3.17-test.3 bruger lyd og nodecursor samme rækkefølge af takter. Melodi, øvrige noterede stemmer, genereret bas, akkorder, slagtøj og metronom følger det samme gentagelsesantal.

!! Gx3 betyder tre gange i alt

Et almindeligt afsnit mellem <code>|:</code> og <code>:|</code> spiller to gange. En tekst som <code>Gx3</code>, <code>G × 3</code>, <code>×3</code>, <code>3x</code> eller <code>4 gange</code> over noderne bestemmer i stedet det samlede antal gennemspilninger af det tilhørende gentagelsesafsnit.

I ABC skal det være en tekstangivelse, fx <code>"^Gx3"</code>. Tegnet <code>^</code> placerer teksten over noderne. En almindelig becifring som <code>"G"</code> behandles fortsat som en akkord.

<pre>|: "^Gx3" C2 D2 E3 :| F7 |]</pre>

Eksemplet er tænkt som 7/8 med <code>L:1/8</code>. Den første takt spilles tre gange; den afsluttende takt spilles én gang. Det er tre gennemspilninger i alt, ikke den normale dobbelte gentagelse ganget med tre.

Teksten kan stå ved afsnittets begyndelse eller på den afsluttende gentagelsestaktstreg. Den skal høre til et afsnit med gentagelsestegn. Den må gerne kun stå i melodistemmen; antallet gælder alle stemmer.

!! Vælg antallet i afspilleren

Åbn ''Gentagelser · antal gennemspilninger''. Hvert afsnit vises med navn eller nummer og dets noterede takter.

* ''Som noteret'' følger gentagelsestegnene og en eventuel tekst som Gx3.
* Et valgt antal, fx ''3 gange'' eller ''4 gange'', erstatter afsnittets noterede antal ved afspilning. Der kan vælges 1–16 gennemspilninger.
* Vælg ''Som noteret'' igen for at nulstille det pågældende afsnit.

Valgene gemmes med nodearket og følger med i Site-afspilleren. De gælder fra næste afspilning. Ændringer her ændrer ikke den gemte ABC eller teksten i nodebilledet. Ved transponering bevares gentagelsesangivelser og valgte antal.

Afspillerens eksisterende ''Gentag''-knap gentager hele nummeret. Afsnittenes antal styres i dette panel.

!! Volter og taktartsskift

Nummererede slutninger indgår i den samme afspilningsplan. Eksempelvis vælger <code>[1,2</code> en fælles slutning de første to gange og <code>[3</code> slutningen tredje gang. Intervaller som <code>[1-3</code> og en slutning mærket <code>[4</code> kan bruges til fire gennemspilninger. Separate tredje slutninger og lister som <code>[1,3</code> / <code>[2,4</code> understøttes også.

Hvis et almindeligt par med første og anden slutning får et større antal i panelet, bruges første slutning på de indledende gennemspilninger og anden slutning på den sidste.

ABC's ekstra gentagelsesprikker, fx <code>|:: … ::|</code>, læses som tre gennemspilninger. Almindelige dobbelte gentagelsestegn mellem to afsnit er fortsat afslutningen på det ene og begyndelsen på det næste.

Taktartsskift inden i afsnittet gentages sammen med musikken. Et afsnit med 9/8 efterfulgt af 7/8 beholder de to forskellige taktlængder ved hver gennemspilning.

!! Afgrænsning

Denne funktion styrer afsnit med gentagelsestegn og nummererede slutninger. En fri tekst uden et tilhørende gentagelsesafsnit definerer ikke i sig selv en ny form. Fritekst som D.C., D.S. og Fine samt en samlet spillerækkefølge i headerens P:-felt har deres egne formregler og bliver ikke tilføjet af denne opdatering.

Noterede stemmer skal have tilsvarende takter med samme varighed; fejl i deres taktstreger eller nodeværdier giver en forklaring i stedet for usynlig forskydning. Temposkift inde i ABC-kilden er fortsat ikke understøttet af det automatiske akkompagnement.

[[ABC-standarden: gentagelsestegn og alternative slutninger|https://abcnotation.com/wiki/abc:standard:v2.1]] beskriver notationen. HUWiki sørger for, at den anvendte afspiller og nodecursor følger samme plan.
","huwiki-text-en":"! Repeats · total number of plays

From v0.3.17-test.3, sound and the notation cursor share one played-measure order. Melody, other notated voices, generated bass, chords, percussion and metronome all follow the same repeat count.

!! Gx3 means three plays in total

A normal section between <code>|:</code> and <code>:|</code> plays twice. An annotation such as <code>Gx3</code>, <code>G × 3</code>, <code>×3</code>, <code>3x</code> or <code>4 times</code> above the notes specifies the total number of plays of the corresponding repeat section.

Use an ABC text annotation, for example <code>"^Gx3"</code>. The <code>^</code> positions the text above the notes. An ordinary chord symbol such as <code>"G"</code> remains a chord.

<pre>|: "^Gx3" C2 D2 E3 :| F7 |]</pre>

This example assumes 7/8 and <code>L:1/8</code>. The first measure plays three times and the final measure once. Three means three plays in total, not the normal two-pass repeat multiplied by three.

An annotation may appear at the beginning of its repeat section or on its closing repeat bar. It must belong to a section with repeat signs. It can be written in just the melody voice; its count applies to every voice.

!! Choose a count in the player

Open ''Repeats · total number of plays''. Each section is shown with its name or number and its written measures.

* ''As notated'' follows the repeat signs and any annotation such as Gx3.
* Choosing a count, such as ''3 times'' or ''4 times'', overrides the section's notated count during playback. Counts from 1 to 16 are available.
* Choose ''As notated'' again to reset that section.

Settings are saved with the score and included in the Site player. They apply from the next playback. The controls do not rewrite the stored ABC or the text in the printed score. Transposition preserves repeat annotations and chosen counts.

The existing ''Repeat'' button loops the complete tune. Section counts are controlled in this panel.

!! Endings and meter changes

Numbered endings use the same playback plan. For example, <code>[1,2</code> selects a shared ending on the first two passes and <code>[3</code> selects the third ending. A range such as <code>[1-3</code> followed by <code>[4</code> supports four plays. Separate third endings and lists such as <code>[1,3</code> / <code>[2,4</code> are supported as well.

When a conventional first/second ending pair is given a larger count in the panel, the first ending is used on the earlier passes and the second ending on the final pass.

ABC's additional repeat dots, such as <code>|:: … ::|</code>, specify three plays. An ordinary double repeat between two sections still closes one section and opens the next.

Meter changes inside a section repeat with the music. A section containing 9/8 followed by 7/8 retains those distinct measure lengths on every pass.

!! Scope

This feature handles sections with repeat signs and numbered endings. Free text outside a repeat section does not by itself define a new form. Free-text D.C., D.S. and Fine instructions and a complete part order in the header's P: field have separate form rules; this update does not add those rules.

Notated voices need corresponding measures of equal duration. Inconsistent barlines or note values produce an explanation rather than silently shifting the voices. Inline tempo changes remain unsupported by the automatic accompaniment.

The [[ABC standard: repeat bars and alternate endings|https://abcnotation.com/wiki/abc:standard:v2.1]] describes the notation. HUWiki ensures that the audio player and notation cursor follow the same plan.
