 function height(){queued=false;if(!alive()||window.parent===window)return;const n=Math.max(40,Math.ceil(Math.max(host.scrollHeight,host.getBoundingClientRect().height)));if(n===lastHeight)return;lastHeight=n;window.parent.postMessage({type:'huwiki-abc-frame-height',version:1,height:n},'*');}
 function schedule(){if(!queued){queued=true;window.requestAnimationFrame(height);}}
 function stop(){if(player&&player.controller&&player.controller.huwikiStop)player.controller.huwikiStop();}
