title: $:/plugins/huwiki/abc/auto-transclusion.js
type: application/javascript
module-type: startup
\*/
(function(){
"use strict";
var Transclude=require("$:/core/modules/widgets/transclude.js").transclude;
var PARAMS=["from","count","bars","audio","show-title"];
function hasOwn(o,k){return Object.prototype.hasOwnProperty.call(o||{},k);}
function isExternal(widget){
  var title=widget.transcludeTitle,current=widget.getVariable("currentTiddler");
  // Explicit <$transclude $tiddler="Score"/> in another tiddler.
  if(title!==current)return true;
  // {{Score}} generates a tiddler widget around its transclude widget. Its
  // currentTiddler is already Score, so inspect the context outside that wrapper.
  // Do not treat the ordinary <$transclude/> in a score's ViewTemplate as an
  // embedded score: that transclusion must continue to show the lesson notes.
  var parent=widget.parentWidget,node=parent&&parent.parseTreeNode;
  return !!(parent&&node&&node.type==="tiddler"&&/^(?:transcludeinline|transcludeblock)$/.test(node.rule||"")&&
    parent.tiddlerTitle===title&&parent.getVariable("currentTiddler")!==title);
}
function enabled(widget){
  if(widget.transcludeVariable||widget.transcludeField!==undefined||
    widget.transcludeIndex!==undefined||widget.transcludeSubTiddler!==undefined||
    (widget.transcludeOutput&&widget.transcludeOutput!=="text/html"))return false;
  if(!widget.transcludeTitle||!isExternal(widget))return false;
  var t=widget.wiki.getTiddler(widget.transcludeTitle);
  if(!t||t.fields["draft.of"])return false;
  // Match loader.getSource, including raw ABC imports without a tag. Keep this
  // predicate independent of parsing so ordinary text keeps its normal reader.
  var fields=t.fields;
  return !!(fields["abc-source"]||
    ((fields.type==="text/vnd.abc"||fields.type==="text/plain")&&
      /(^|\n)X:\s*\d+/m.test(fields.text||"")));
}
function scoreNode(widget){
  var attrs={
    tiddler:{type:"string",value:widget.transcludeTitle},
    view:{type:"string",value:"minimal"},
    embedded:{type:"string",value:"yes"}
  },params=widget.stringParametersByName||{};
  PARAMS.forEach(function(name){if(hasOwn(params,name))attrs[name]={type:"string",value:String(params[name])};});
  // An explicit view parameter is useful with the long <$transclude> form.
  // Parameters for ordinary transclusions remain entirely with the core.
  if(params.view==="full"||params.view==="minimal"||params.view==="auto")attrs.view={type:"string",value:params.view};
  return {type:"huwiki-abc",attributes:attrs,isBlock:true};
}
function install(){
  var proto=Transclude.prototype;
  if(proto._huwikiAbcTransclusionInstalled)return;
  var originalParse=proto.parseTransclusionTarget,originalRefresh=proto.parserNeedsRefresh;
  proto.parseTransclusionTarget=function(parseAsInline){
    var target=originalParse.call(this,parseAsInline),active=enabled(this);
    this._huwikiAbcAutoTarget=active;
    if(!active)return target;
    // Never mutate a cached parser or the source tiddler. Only this particular
    // rendered transclusion receives the minimal score node.
    var result={};Object.keys(target).forEach(function(k){result[k]=target[k];});
    result.parseTreeNodes=[scoreNode(this)];
    return result;
  };
  proto.parserNeedsRefresh=function(){
    // Adding/removing abc-source does not change text. The core's text-only
    // parser comparison therefore needs this one additional mode comparison.
    var active=enabled(this);
    if(!!this._huwikiAbcAutoTarget!==active)return true;
    // While the target is an ABC example our parse tree is a score widget, not
    // its prose. The score widget handles source/field changes selectively.
    if(active)return false;
    return originalRefresh.call(this);
  };
  proto._huwikiAbcTransclusionInstalled=true;
}
exports.name="huwiki-abc-auto-transclusion";
exports.after=["load-modules"];
exports.before=["startup"];
exports.synchronous=true;
exports.startup=function(){if(!$tw.safeMode)install();};
exports.install=install;
exports.enabled=enabled;
})();
