.huwabc-minimal-player{display:block;position:static;margin:.6em 0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;color:inherit;max-width:100%;}
.huwabc-minimal-player .huwabc-minimal-paper{margin:0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;width:100%;max-width:100%;overflow-x:auto;}
.huwabc-minimal-player .huwabc-minimal-paper svg{display:block;max-width:100%;height:auto;}
.huwabc-minimal-controls{position:static;display:flex;align-items:center;margin:0 0 7px;padding:0;border:0;background:transparent;}
.huwabc-minimal-controls .abcjs-inline-audio{display:flex;align-items:center;gap:0;width:auto;min-width:0;min-height:0;height:auto;padding:0;background:transparent;color:inherit;}
.huwabc-minimal-controls .abcjs-inline-audio .abcjs-midi-start{display:inline-flex;align-items:center;justify-content:center;gap:5px;width:auto;height:auto;min-height:28px;margin:0;padding:4px 9px;border:1px solid #7fae9e;border-radius:5px;background:#236e5e;color:#fff;font:600 12px/1.3 system-ui,sans-serif;cursor:pointer;opacity:1;box-sizing:border-box;}
.huwabc-minimal-controls .abcjs-midi-start:hover{background:#1a584a;}
.huwabc-minimal-controls .abcjs-midi-start:focus-visible{outline:2px solid #2a8670;outline-offset:3px;}
.huwabc-minimal-controls .abcjs-inline-audio.abcjs-disabled .abcjs-midi-start{opacity:.55;cursor:wait;}
.huwabc-minimal-controls .huwabc-minimal-icon{display:block;width:14px;height:14px;flex:none;}
.huwabc-minimal-controls .abcjs-midi-start .huwabc-minimal-pause,.huwabc-minimal-controls .abcjs-midi-start .huwabc-minimal-label-pause{display:none;}
.huwabc-minimal-controls .abcjs-midi-start.abcjs-pushed .huwabc-minimal-play,.huwabc-minimal-controls .abcjs-midi-start.abcjs-pushed .huwabc-minimal-label-play{display:none;}
.huwabc-minimal-controls .abcjs-midi-start.abcjs-pushed .huwabc-minimal-pause{display:block;}
.huwabc-minimal-controls .abcjs-midi-start.abcjs-pushed .huwabc-minimal-label-pause{display:inline;}
.huwabc-minimal-player .huwabc-minimal-status{margin:4px 0 0;padding:0;color:#456b60;font:12px/1.4 system-ui,sans-serif;}
.huwabc-minimal-player .huwabc-minimal-status.huwabc-error{color:#a32d2d;}
.huwabc-minimal-player [hidden]{display:none!important;}
.huwabc-minimal-player .huwabc-playing-note,.huwabc-minimal-player .huwabc-playing-note *{fill:#ce4e38!important;stroke:#ce4e38!important;}
.huwabc-minimal-player .huwabc-minimal-cursor{stroke:#15989b;stroke-width:2;pointer-events:none;}
.huwabc-minimal-player .huwabc-cue-selected,.huwabc-minimal-player .huwabc-cue-selected *{stroke:#1d84ac!important;fill:#1d84ac!important;}
.huwabc-minimal-player .huwabc-cue-selected.abcjs-chord,.huwabc-minimal-player .huwabc-cue-selected.abcjs-chord *{stroke:none!important;fill:#1d84ac!important;}
.huwabc-minimal-player:focus-visible{outline:2px solid #9fc3b5;outline-offset:3px;}
@media print{.huwabc-minimal-controls,.huwabc-minimal-player .huwabc-minimal-status{display:none!important;}}

/* Embedded examples flow with the prose; standalone scores keep their frame. */
.huwabc-score.huwabc-minimal:not(.huwabc-standalone){margin:.6em 0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;}
.huwabc-score.huwabc-minimal .huwabc-minimal-player{margin:0;}
.huwabc-score.huwabc-minimal .huwabc-minimal-paper{padding:0;min-height:0;border:0;border-radius:0;background:transparent;}
.huwabc-score.huwabc-standalone.huwabc-minimal>.huwabc-minimal-content{padding:clamp(10px,3vw,30px);}
.huw-music-view:has(>.huw-music-media-abc>.huwabc-standalone.huwabc-minimal)>.huw-music-practice,
.huw-music-view:has(>.huw-music-media-abc>.huwabc-standalone.huwabc-minimal)>.huw-music-bottomnav{display:none;}
.huwabc-minimal-loading{font-size:12px;color:#456b60;}
.huwabc-title-help{margin:.6em 0;}
/* The same small action stays above the tools in both standalone views. */
.huwabc-standalone>.huwabc-view-toggle-row{display:flex;justify-content:flex-end;align-items:center;gap:8px;flex-wrap:wrap;min-height:29px;padding:6px 18px 0;margin:0;background:#f6f8f8;border-radius:17px 17px 0 0;}
.huwabc-minimal-toolbar{display:flex;align-items:center;}
.huwabc-minimal-toolbar .huwabc-minimal-controls{margin:0;}
.huwabc-minimal-toolbar .abcjs-inline-audio .abcjs-midi-start{min-height:25px;padding:3px 9px;border-radius:999px;font-size:11px;}
.huwabc-standalone>.huwabc-view-toggle-row+.huwabc-head{padding-top:6px;}
.huwabc-standalone .huwabc-view-toggle{display:inline-flex;align-items:center;justify-content:center;min-height:25px;padding:3px 9px;border:1px solid #c7dbd3;border-radius:999px;background:transparent;color:#426b60;font:500 11px/1.35 system-ui,sans-serif;box-shadow:none;}
.huwabc-standalone .huwabc-view-toggle:hover{background:#e9f3ee;color:#245b4c;border-color:#9fc3b5;outline:none;}
.huwabc-standalone .huwabc-view-toggle:focus-visible{outline:2px solid #2a8670;outline-offset:2px;}
@media(max-width:700px){.huwabc-standalone>.huwabc-view-toggle-row{padding-right:10px;}.huwabc-standalone .huwabc-view-toggle,.huwabc-minimal-toolbar .abcjs-inline-audio .abcjs-midi-start{min-height:28px;font-size:12px;}}
@media print{.huwabc-standalone>.huwabc-view-toggle-row{display:none!important;}}
