(function(){
'use strict';
var Accompaniment=require('$:/plugins/huwiki/abc/accompaniment.js');
// Compare dependencies, not the tiddler as a whole. Timestamps, practice notes
// and unrelated custom fields must not invalidate the score or its audio.
var visualFields=['abc-parts-new-line','abc-layout','abc-font','abc-tabs','abc-tabs-config','abc-show-notes',
 'abc-bars-per-line','abc-chords-style','huwiki-score-title-source','huwiki-score-title-da','huwiki-score-title-en'];
var soundFields=['abc-rhythm','abc-style','abc-genre','abc-meter','abc-origin-library','abc-origin-url'];
function source(fields){
 fields=fields||{};
 if(fields['abc-source'])return String(fields['abc-source']);
 if((fields.type==='text/vnd.abc'||fields.type==='text/plain')&&/(^|\n)X:\s*\d+/m.test(fields.text||''))return String(fields.text);
 return '';
}
function different(a,b,keys){return keys.some(function(key){return (a[key]||'')!==(b[key]||'');});}
function plan(before,after){
 before=before||{};after=after||{};
 var sourceChanged=source(before)!==source(after);
 var score=sourceChanged||different(before,after,visualFields);
 var configChanged=JSON.stringify(Accompaniment.read(before))!==JSON.stringify(Accompaniment.read(after));
 var audio=sourceChanged||different(before,after,soundFields)||
  (configChanged&&!Accompaniment.liveConfigChange(Accompaniment.read(before),Accompaniment.read(after)));
 return {score:score,audio:audio,live:configChanged&&!audio,source:sourceChanged,
  pages:different(before,after,['abc-lines-per-page','abc-paper-size','abc-page-margin']),
  controls:different(before,after,visualFields.concat(['abc-lines-per-page','abc-before-transpose','abc-paper-size','abc-page-margin']))};
}
exports.plan=plan;exports.source=source;
})();
