(function(){
'use strict';
// Session-only UI state. No page turn, panel opening or focus change writes to
// the music tiddler. Qualifier plus widget-tree path also separates duplicate
// transclusions of the same score. No playback clock is stored in the wiki.
function keyFor(widget){
 var path=[],node=widget;
 while(node&&node.parentWidget){
  var parent=node.parentWidget,index=(parent.children||[]).indexOf(node);
  path.push(index);node=parent;
 }
 return '$:/temp/huwiki/abc/view/'+encodeURIComponent(widget.title||'')+'/'+
  widget.getStateQualifier()+'/'+path.reverse().join('.');
}
exports.mount=function(widget,host){
 var wiki=widget.wiki,key=keyFor(widget),closed=false,bound=false,state=read();
 function read(){try{var x=JSON.parse(wiki.getTiddlerText(key,'{}'));return x&&typeof x==='object'&&!Array.isArray(x)?x:{};}catch(ignore){return {};}}
 function set(name,value){
  if(closed)return;var next=read();if(next[name]===value)return;
  next[name]=value;state=next;wiki.setText(key,'text',null,JSON.stringify(next));
 }
 function apply(){
  state=read();
  host.querySelectorAll('details[data-huwabc-panel]').forEach(function(node){
   var value=state[node.getAttribute('data-huwabc-panel')];
   if(typeof value==='boolean'&&node.open!==value)node.open=value;
  });
  var mixer=host.querySelector('.huwabc-mixer'),button=host.querySelector('.huwabc-mixer-toggle');
  if(mixer&&typeof state.mixer==='boolean'){
   mixer.hidden=!state.mixer;
   if(button){button.setAttribute('aria-expanded',String(state.mixer));button.textContent=state.mixer?'Skjul mixer og instrumenter':'Vis mixer og instrumenter';}
  }
 }
 function toggle(event){var node=event.target;if(!node||!node.getAttribute||!host.contains(node))return;var name=node.getAttribute('data-huwabc-panel');if(name)set(name,!!node.open);}
 function click(event){var target=event.target&&event.target.closest&&event.target.closest('.huwabc-mixer-toggle');if(target&&host.contains(target)){var m=host.querySelector('.huwabc-mixer');if(m)set('mixer',!m.hidden);}}
 return {key:key,get:function(name,fallback){return state[name]===undefined?fallback:state[name];},set:set,
  bind:function(){apply();if(!bound){host.addEventListener('toggle',toggle,true);host.addEventListener('click',click);bound=true;}},
  refresh:function(changes){if(changes[key])apply();},
  destroy:function(){closed=true;if(bound){host.removeEventListener('toggle',toggle,true);host.removeEventListener('click',click);}}
 };
};
})();
"},"$:/plugins/huwiki/abc/viewport-anchor.js":{"title":"$:/plugins/huwiki/abc/viewport-anchor.js","type":"application/javascript","module-type":"library","text":"/*\
