title: $:/plugins/huwiki/abc/engraving-rules.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
var VoiceNames=require('$:/plugins/huwiki/abc/voice-names.js');
var EPS=1e-7;
function note(e){return e&&e.el_type==='note';}
function opening(e){return e&&e.el_type==='bar'&&(e.type==='bar_left_repeat'||e.type==='bar_dbl_repeat');}
function part(e){return e&&(e.el_type==='part'||(e.chord||[]).some(function(c){return c.position==='above'&&/^[A-Z](?:[0-9]|['′])?(?:\s*[x×]\s*\d+)?$/.test(String(c.name||'').trim());}));}
function times(voice){var time=0,multiplier=1,events=[];voice.forEach(function(e,index){var at=time;if(note(e)){if(e.startTriplet)multiplier=Number(e.tripletMultiplier)||1;time+=(Number(e.duration)||0)*multiplier;if(e.endTriplet)multiplier=1;}events.push({e:e,index:index,time:at,end:time});});return {events:events,total:time};}
function hasMusic(voice){return voice.some(note);}
function closeBar(e){var copy=Object.assign({},e,{type:'bar_right_repeat'});if(copy.chord)copy.chord=copy.chord.filter(function(c){return c.position!=='above';});delete copy.startEnding;return copy;}
function openBar(e){var copy=Object.assign({},e,{type:'bar_left_repeat'});delete copy.endEnding;return copy;}
function cloneHeader(staff,left,following){
 var next=Object.assign({},staff);delete next.meter;delete next.barNumber;
 if(Array.isArray(staff.abbrevTitle))next.title=staff.abbrevTitle.slice();
 else if(following&&Array.isArray(following.title))next.title=following.title.slice();
 (left[0]||[]).forEach(function(e){if(e.el_type==='clef'||e.el_type==='key'){next[e.el_type]=Object.assign({},e);delete next[e.el_type].el_type;delete next[e.el_type].startChar;delete next[e.el_type].endChar;}});
 return next;
}
// A complete system is cut at a common musical boundary. Never split an
// event (including ties, tuplets or a multimeasure rest) merely to fit a page.
function cutVoice(voice,at){
 if(!hasMusic(voice))return {left:voice.slice(),right:[]};
 var scan=times(voice);if(scan.total<=at+EPS)return null;
 if(scan.events.some(function(r){return note(r.e)&&r.time<at-EPS&&r.end>at+EPS;}))return null;
 var first=scan.events.findIndex(function(r){return r.time>=at-EPS;});if(first<0)return null;
 var boundary=scan.events.slice(first).filter(function(r){return Math.abs(r.time-at)<EPS;});
 if(!boundary.some(function(r){return r.e.el_type==='bar';})&&first>0&&voice[first-1].el_type!=='bar')return null;
 var pivot=first,closing=[];
 // The closing half belongs to the old line. The opening half and its part
// label belong with the first note of the new line.
 while(pivot<voice.length&&Math.abs(scan.events[pivot].time-at)<EPS){
  var e=voice[pivot];
  if(e.el_type==='bar'&&e.type==='bar_dbl_repeat'){
   closing.push(closeBar(e));return {left:voice.slice(0,first).concat(closing),right:[openBar(e)].concat(voice.slice(pivot+1))};
  }
  if(e.el_type==='bar'&&!opening(e)&&!part(e)){closing.push(e);pivot++;continue;}
  break;
 }
 return {left:voice.slice(0,first).concat(closing),right:voice.slice(pivot)};
}
function splitSystem(line,at,nextOriginal){
 var cuts=[];for(var si=0;si<line.staff.length;si++){var staff=line.staff[si],voices=[];for(var vi=0;vi<staff.voices.length;vi++){var cut=cutVoice(staff.voices[vi],at);if(!cut)return null;voices.push(cut);}cuts.push(voices);}
 if(!cuts.some(function(s){return s.some(function(v){return hasMusic(v.left)&&hasMusic(v.right);});}))return null;
 var left=Object.assign({},line),right=Object.assign({},line);delete right.vskip;delete right.newpage;
 left.staff=line.staff.map(function(s,si){return Object.assign({},s,{voices:cuts[si].map(function(c){return c.left;})});});
 right.staff=line.staff.map(function(s,si){var next=cloneHeader(s,cuts[si].map(function(c){return c.left;}),nextOriginal&&nextOriginal.staff&&nextOriginal.staff[si]);next.voices=cuts[si].map(function(c){return c.right;});return next;});
 return [left,right];
}
function moveTrailing(line,next){
 if(!line.staff||!next||!next.staff||line.staff.length!==next.staff.length)return;
 line.staff.forEach(function(staff,si){staff.voices.forEach(function(voice,vi){var target=next.staff[si].voices[vi];if(!target||!hasMusic(target))return;var last=-1;voice.forEach(function(e,i){if(note(e))last=i;});if(last<0)return;
  var start=-1;for(var i=last+1;i<voice.length;i++){if(opening(voice[i])||voice[i].el_type==='part'){start=i;break;}}
  if(start<0)return;
  var moved=voice.splice(start);if(moved[0].el_type==='bar'&&moved[0].type==='bar_dbl_repeat'){voice.push(closeBar(moved[0]));moved[0]=openBar(moved[0]);}
  // A lone opening repeat doubles as the source's boundary. Retain a closing
  // thin bar on the old system; it has no duration and creates no measure.
  if(voice.length&&note(voice[voice.length-1]))voice.push({el_type:'bar',type:'bar_thin',startChar:-1,endChar:-1});
  Array.prototype.unshift.apply(target,moved);
 });});
}
function combineBars(voice){
 for(var i=1;i<voice.length;i++){var a=voice[i-1],b=voice[i];if(a.el_type!=='bar'||b.el_type!=='bar'||b.type!=='bar_left_repeat')continue;
  // Endings and decorations can carry different meanings; retain unusual
  // combinations rather than guessing their intended scope.
  if(a.startEnding||b.endEnding||(a.decoration&&a.decoration.length)||(b.decoration&&b.decoration.length))continue;
  if(a.type!=='bar_right_repeat'&&a.type!=='bar_thin')continue;
  var merged=Object.assign({},a,b,{type:a.type==='bar_right_repeat'?'bar_dbl_repeat':'bar_left_repeat',startChar:Math.min(a.startChar,b.startChar),endChar:Math.max(a.endChar,b.endChar)});
  if(a.endEnding)merged.endEnding=a.endEnding;
  if(a.chord||b.chord)merged.chord=(a.chord||[]).concat(b.chord||[]);
  voice.splice(i-1,2,merged);i--;
 }
}
function prepare(tune,fields,source){
 if(!tune||!Array.isArray(tune.lines))return tune;
 var lines=tune.lines,force=!fields||fields['abc-parts-new-line']!=='no';
 // A single source line may have no subsequent staff from which ABCJS can
 // recover its snm attribute. Use explicit, unambiguous source labels only.
 var names=source?VoiceNames.scan(source):[];
 lines.forEach(function(l){(l.staff||[]).forEach(function(s){if(Array.isArray(s.abbrevTitle)||!Array.isArray(s.title))return;
  var matched=false,short=s.title.map(function(full){var candidates=names.filter(function(v){return v.name===full&&v.hasShort;});if(candidates.length===1){matched=true;return candidates[0].short;}return full;});
  if(matched)s.abbrevTitle=short;
 });});
 for(var i=0;i<lines.length-1;i++)if(lines[i].staff&&lines[i+1].staff)moveTrailing(lines[i],lines[i+1]);
 if(force){
  var result=[];for(var j=0;j<lines.length;j++){var original=lines[j];if(!original.staff){result.push(original);continue;}var pending=original,guard=0;
   while(guard++<256){var candidates=[];pending.staff.forEach(function(s){s.voices.forEach(function(v){var scan=times(v);scan.events.forEach(function(r){if(part(r.e)&&r.time>EPS&&r.time<scan.total-EPS&&!candidates.some(function(t){return Math.abs(t-r.time)<EPS;}))candidates.push(r.time);});});});
    candidates.sort(function(a,b){return a-b;});var cut=null;for(var ci=0;ci<candidates.length;ci++){cut=splitSystem(pending,candidates[ci],lines[j+1]);if(cut)break;}
    if(!cut)break;result.push(cut[0]);pending=cut[1];
   }result.push(pending);
  }tune.lines=result;
 }
 var firstSystem=true;
 (tune.lines||[]).forEach(function(l){if(!l.staff)return;l.staff.forEach(function(s){
  // ABCJS wrapping retains both title and abbrevTitle but repeats title on
  // every wrapped system. Respect the source's short label after system one.
  if(!firstSystem&&Array.isArray(s.abbrevTitle))s.title=s.abbrevTitle.slice();
  s.voices.forEach(combineBars);
 });firstSystem=false;});return tune;
}
exports.prepare=prepare;exports.part=part;exports.times=times;exports.combineBars=combineBars;exports.splitSystem=splitSystem;
})();
"},"$:/plugins/huwiki/abc/voice-names.js":{"title":"$:/plugins/huwiki/abc/voice-names.js","type":"application/javascript","module-type":"library","text":"/*\
title: $:/plugins/huwiki/abc/voice-names.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
var I18n=require('$:/plugins/huwiki/abc/i18n.js');
// Edit only voice-label attributes. Voice IDs, notes, clefs and MIDI routing
// are not regenerated. Source offsets remain explicit for editor selection.
var FULL=['name','nm'],SHORT=['subname','sname','snm'];
function contentEnd(s){var quote=false;for(var i=0;i<s.length;i++){if(s[i]==='\\'){i++;continue;}if(s[i]==='"')quote=!quote;if(s[i]==='%'&&!quote)return i;}return s.length;}
function attrs(text,start){var list=[],re=/(?:^|\s)(name|nm|subname|sname|snm)\s*=\s*("(?:\\.|[^"\\])*"|[^\s%\]]+)/g,m;while((m=re.exec(text))){var leading=/^\s/.test(m[0])?1:0,v=m[2];list.push({key:m[1],value:v[0]==='"'?v.slice(1,-1).replace(/\\"/g,'"'):v,start:start+m.index+leading,end:start+re.lastIndex});}return list;}
function scan(source){
 source=String(source||'');var records=[],offset=0,block=null;
 function add(body,start,end){var m=/^\s*([^\s\]]+)/.exec(body);if(!m)return;var id=m[1],items=attrs(body.slice(m[0].length),start+m[0].length);records.push({id:id,start:start,end:end,attrs:items});}
 (source.match(/[^\r\n]*(?:\r\n|\r|\n|$)/g)||[]).forEach(function(raw){var line=raw.replace(/[\r\n]+$/,''),begin=/^\s*%%begin([a-z]+)/i.exec(line);
  if(block){if(new RegExp('^\\s*%%end'+block+'\\b','i').test(line))block=null;offset+=raw.length;return;}
  if(begin){block=begin[1];offset+=raw.length;return;}
  var end=contentEnd(line),m=/^\s*V:\s*/.exec(line);
  if(m)add(line.slice(m[0].length,end),offset+m[0].length,offset+end);
  else if(!/^\s*(?:%|[A-Za-z+]:)/.test(line)){
   for(var i=0,quote=false;i<end;i++){if(line[i]==='\\'){i++;continue;}if(line[i]==='"'){quote=!quote;continue;}if(quote||line.slice(i,i+3)!=='[V:')continue;
    var j=i+3,q=false;for(;j<end;j++){if(line[j]==='\\'){j++;continue;}if(line[j]==='"')q=!q;if(line[j]===']'&&!q)break;}if(j<end){add(line.slice(i+3,j),offset+i+3,offset+j);i=j;}
   }
  }
  offset+=raw.length;
 });
 var ids=[];records.forEach(function(r){if(ids.indexOf(r.id)<0)ids.push(r.id);});
 return ids.map(function(id){var all=records.filter(function(r){return r.id===id;}),main=all.find(function(r){return r.attrs.some(function(a){return FULL.indexOf(a.key)>=0;});})||all.find(function(r){return r.attrs.length;})||all[0];var full=main.attrs.find(function(a){return FULL.indexOf(a.key)>=0;}),short=main.attrs.find(function(a){return SHORT.indexOf(a.key)>=0;});return {id:id,name:full?full.value:'',short:short?short.value:'',hasShort:!!short,record:main};});
}
function apply(source,changes){
 source=String(source||'');var voices=scan(source),edits=[];
 (changes||[]).forEach(function(change){var voice=voices.find(function(v){return v.id===change.id;});if(!voice)throw new Error('Stemmen findes ikke længere. Kontrollér ABC-kilden.');
  ['name','short'].forEach(function(key){if(change[key]===undefined)return;var value=String(change[key]);if(/["\r\n]/.test(value))throw new Error('Skriv et stemmenavn uden citationstegn eller linjeskift.');var group=key==='name'?FULL:SHORT,found=voice.record.attrs.filter(function(a){return group.indexOf(a.key)>=0;}),text=(key==='name'?'name':'snm')+'="'+value+'"';
   if(found.length){edits.push({start:found[0].start,end:found[0].end,text:text});found.slice(1).forEach(function(a){edits.push({start:a.start,end:a.end,text:''});});}
   else edits.push({start:voice.record.end,end:voice.record.end,text:' '+text});
  });
 });
 var next=source;edits.slice().sort(function(a,b){return b.start-a.start;}).forEach(function(e){next=next.slice(0,e.start)+e.text+next.slice(e.end);});
 return {source:next,offset:function(pos){return pos+edits.reduce(function(n,e){return n+(e.end<=pos?e.text.length-(e.end-e.start):0);},0);}};
}
function suggest(name){var known={'melodi':'Mel.','melody':'Mel.','basstemme':'Bas','bass voice':'Bass','bas':'Bas','bass':'Bass','klaver':'Klv.','piano':'Pno.','guitar':'Gtr.','violin':'Vln.','violin 1':'Vln. 1','violin 2':'Vln. 2','fløjte':'Fl.','flute':'Fl.','klarinet':'Kl.','clarinet':'Cl.','trompet':'Trp.','trumpet':'Tpt.','harmonika':'Harm.','accordion':'Acc.','sang':'Sang','vokal':'Vok.','voice':'V.','soprano':'S.','sopran':'S.','alto':'A.','alt':'A.','tenor':'T.'};return known[String(name||'').trim().toLowerCase()]||'';}
function mount(parent,getSource,onChange,wiki){
 function tr(s){return I18n.translate(s,I18n.language(wiki));}
 var doc=parent.ownerDocument,box=doc.createElement('details');box.className='huwabc-voice-names huwabc-advanced-settings';var summary=doc.createElement('summary');summary.textContent='Stemmenavne · fulde og korte';box.appendChild(summary);
 var hint=doc.createElement('p');hint.className='huwabc-muted';hint.textContent='Fuldt navn vises på første nodesystem. Kort navn bruges på de følgende. Forslag indsættes kun, når du vælger dem; du kan altid rette dem.';box.appendChild(hint);
 var grid=doc.createElement('div');grid.className='huwabc-voice-name-grid';box.appendChild(grid);var rows={},signature='';
 var suggestButton=doc.createElement('button');suggestButton.type='button';suggestButton.className='huwabc-btn';suggestButton.textContent='Brug forslag til korte navne';box.appendChild(suggestButton);
 var status=doc.createElement('div');status.className='huwabc-preview-status';status.setAttribute('role','status');box.appendChild(status);
 function change(list){try{var result=apply(getSource(),list);status.textContent='';onChange(result);update();}catch(e){status.textContent=e.message;}}
 function update(){var voices=scan(getSource()),sig=voices.map(function(v){return v.id;}).join('\u0000');if(sig!==signature||!grid.children.length){signature=sig;grid.textContent='';rows={};voices.forEach(function(v){var row=doc.createElement('div');row.className='huwabc-voice-name-row';row.setAttribute('data-voice-id',v.id);var id=doc.createElement('strong');id.textContent='V:'+v.id;row.appendChild(id);var controls={};[['name','Fuldt navn'],['short','Kort navn']].forEach(function(pair){var label=doc.createElement('label');label.className='huwabc-field';var caption=doc.createElement('span');caption.textContent=pair[1];label.appendChild(caption);var input=doc.createElement('input');input.type='text';input.className='huwabc-input';input.setAttribute('aria-label',tr(pair[1])+' · V:'+v.id);input.addEventListener('change',function(){var next={id:v.id};next[pair[0]]=input.value;change([next]);});label.appendChild(input);row.appendChild(label);controls[pair[0]]=input;});grid.appendChild(row);rows[v.id]=controls;});}
  voices.forEach(function(v){['name','short'].forEach(function(key){if(doc.activeElement!==rows[v.id][key])rows[v.id][key].value=v[key];});});
  var candidates=voices.filter(function(v){return (!v.hasShort||v.short===v.name)&&suggest(v.name)&&suggest(v.name)!==v.short;});suggestButton.disabled=!candidates.length;
  if(!voices.length)status.textContent='Denne melodi har ingen V:-stemmer. Stemmenavne kan tilføjes i ABC-kilden.';
 }
 suggestButton.addEventListener('click',function(){var next=scan(getSource()).filter(function(v){return (!v.hasShort||v.short===v.name)&&suggest(v.name)&&suggest(v.name)!==v.short;}).map(function(v){return {id:v.id,short:suggest(v.name)};});if(next.length)change(next);});
 parent.appendChild(box);update();return {element:box,update:update};
}
exports.scan=scan;exports.apply=apply;exports.suggest=suggest;exports.mount=mount;
})();
"},"$:/plugins/huwiki/abc/selection-popover.js":{"title":"$:/plugins/huwiki/abc/selection-popover.js","text":"/*\
title: $:/plugins/huwiki/abc/selection-popover.js
type: application/javascript
module-type: library
\*/
(function(){
'use strict';
var I18n=require('$:/plugins/huwiki/abc/i18n.js');
exports.mount=function(host,controls,opts){
 opts=opts||{};var doc=host.ownerDocument,win=doc.defaultView,parent=controls.parentNode,next=controls.nextSibling;
 var placeholder=doc.createElement('div'),box=doc.createElement('section'),head=doc.createElement('header');
 var saved=opts.state&&opts.state.get('inspectorPlacement',''),mode=['follow','fixed','inline'].indexOf(saved)>=0?saved:opts.state&&opts.state.get('inspectorPinned',false)?'fixed':'follow';
 var fixed=opts.state&&opts.state.get('inspectorPosition',null),opened=false,closed=false,target=null,frame=0,lastPosition=null,needsReveal=false,drag=null;
 function tr(da,en){return I18n.language(opts.wiki)==='da'?da:en;}
 function bounds(){var v=win.visualViewport;return {left:v?v.offsetLeft:0,top:v?v.offsetTop:0,width:v?v.width:win.innerWidth,height:v?v.height:win.innerHeight};}
 box.className='huwabc-inspector';box.hidden=true;box.setAttribute('role','region');head.className='huwabc-inspector-head';
 var heading=doc.createElement('strong');head.appendChild(heading);
 var placement=doc.createElement('select');placement.className='huwabc-inspector-placement huwabc-select';placement.setAttribute('aria-label',tr('Editorens placering','Editor placement'));
 [['follow','Følg markeringen','Follow selection'],['fixed','Fast placering','Fixed position'],['inline','Ved ABC-koden','By ABC source']].forEach(function(p){var o=doc.createElement('option');o.value=p[0];o.textContent=tr(p[1],p[2]);placement.appendChild(o);});
 head.appendChild(placement);
 var close=doc.createElement('button');close.type='button';close.className='huwabc-btn huwabc-inspector-close';close.textContent=tr('Luk','Close');head.appendChild(close);
 controls.insertBefore(head,controls.firstChild);host.appendChild(box);placeholder.className='huwabc-inspector-placeholder';placeholder.setAttribute('aria-hidden','true');
 function sync(){placement.value=mode;var text=mode==='follow'?tr('Redigering · følger markering','Editing · follows selection'):mode==='fixed'?tr('Redigering · fast placering','Editing · fixed position'):tr('Redigering · ved ABC-koden','Editing · by ABC source');heading.textContent=text;box.setAttribute('aria-label',text);head.title=mode==='inline'?'':tr('Træk i overskriften for at placere kortet frit.','Drag the heading to position the card.');controls.setAttribute('data-editor-placement',mode);close.hidden=!opened;}
 function setMode(value){mode=value;if(opts.state)opts.state.set('inspectorPlacement',mode);lastPosition=null;sync();if(mode==='inline')restore();else if(target&&target.isConnected)show(target);position(true);}
 function restore(){if(!opened)return;opened=false;box.hidden=true;if(next&&next.parentNode===parent)parent.insertBefore(controls,next);else parent.appendChild(controls);placeholder.remove();lastPosition=null;sync();}
 placement.addEventListener('change',function(){if(placement.value==='fixed'&&lastPosition)fixed={left:lastPosition.left,top:lastPosition.top};setMode(placement.value);});
 close.addEventListener('click',function(){if(opts.cancel)opts.cancel();hide();if(opts.focus)opts.focus();});
 function reveal(top,v){if(!needsReveal||mode!=='follow'||v.width>=700||!target)return;needsReveal=false;var r=target.getBoundingClientRect(),delta=r.bottom-(top-12),n=target.parentElement;if(delta<=0)return;while(n&&n!==doc.body&&delta>1){var st=win.getComputedStyle(n);if(/auto|scroll/.test(st.overflowY)&&n.scrollHeight>n.clientHeight+1){var before=n.scrollTop;n.scrollTop=Math.max(0,before+delta);delta-=n.scrollTop-before;}n=n.parentElement;}if(delta>1)win.scrollBy(0,delta);}
 function position(force){
  if(!opened||closed||drag)return;var v=bounds();box.style.maxHeight=Math.max(120,Math.floor(v.height*.62))+'px';box.style.width=Math.min(440,v.width-24)+'px';
  var r=target&&target.isConnected?target.getBoundingClientRect():null,w=box.getBoundingClientRect().width,h=box.getBoundingClientRect().height,left,top;
  var typing=box.contains(doc.activeElement)&&doc.activeElement.matches('input,textarea,select,[contenteditable]');
  if(mode==='fixed'){var f=fixed||lastPosition||{left:v.left+v.width-w-18,top:v.top+80};left=f.left;top=f.top;}
  else if(typing&&lastPosition&&!force){left=lastPosition.left;top=lastPosition.top;}
  else if(r&&(r.width||r.height)){var staff=target.closest('.abcjs-staff-wrapper,.huwabc-tabs-only'),sr=staff?staff.getBoundingClientRect():r;left=r.left+r.width/2-w/2;
   top=v.width<700?v.top+v.height-h-12:sr.bottom+h+8<=v.top+v.height-12?sr.bottom+8:sr.top-h-8>=v.top+12?sr.top-h-8:v.top+v.height-h-12;
  }else if(lastPosition){left=lastPosition.left;top=lastPosition.top;}else return;
  left=Math.max(v.left+8,Math.min(left,v.left+v.width-w-8));top=Math.max(v.top+8,Math.min(top,v.top+v.height-h-8));box.style.left=Math.round(left)+'px';box.style.top=Math.round(top)+'px';lastPosition={left:left,top:top};box.setAttribute('data-placement',mode==='fixed'?'pinned':v.width<700?'bottom':'selection');reveal(top,v);
 }
