 function show(node){if(closed||!node)return;needsReveal=!opened||node!==target;target=node;if(mode==='inline'){sync();return;}
  if(!opened){var r=controls.getBoundingClientRect(),style=win.getComputedStyle(controls);placeholder.style.height=r.height+'px';placeholder.style.marginTop=style.marginTop;placeholder.style.marginBottom=style.marginBottom;parent.insertBefore(placeholder,controls);box.appendChild(controls);opened=true;box.hidden=false;lastPosition=null;}sync();position(false);
 }
