 head.addEventListener('pointerdown',function(e){if(!opened||e.button!==0||e.target.closest('button,select,input'))return;var r=box.getBoundingClientRect();e.preventDefault();e.stopPropagation();mode='fixed';sync();drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top};head.setPointerCapture(e.pointerId);});
