};
})();
","type":"application/javascript","module-type":"library"},"$:/plugins/huwiki/abc/context-editor.css":{"title":"$:/plugins/huwiki/abc/context-editor.css","text":"/* Local notation editing; no global wiki selectors. */
.huwabc-inspector{position:fixed;z-index:10060;box-sizing:border-box;background:#fff;color:#23483e;border:1px solid #a9cfc0;border-radius:12px;box-shadow:0 10px 36px rgba(20,50,42,.23);overflow:auto;overscroll-behavior:contain;padding:9px 11px 10px;font:13px/1.45 system-ui,sans-serif;}
.huwabc-inspector[hidden]{display:none!important}
.huwabc-inspector-head{display:flex;align-items:center;gap:7px;padding-bottom:7px;border-bottom:1px solid #e0ebe6;}
.huwabc-inspector-head>strong{flex:1;font-size:12px}
.huwabc-inspector .huwabc-btn{font-size:12px;min-height:30px;padding:5px 8px}
.huwabc-inspector .huwabc-selection{margin:6px 0 0;padding:0;border:0;background:transparent}
.huwabc-inspector .huwabc-compose-hint{display:none}
.huwabc-inspector .huwabc-selection-toolbar{gap:5px;flex-wrap:wrap}
.huwabc-inspector .huwabc-selection-toolbar>.huwabc-select{font-size:12px;min-width:130px;min-height:30px;padding:3px 6px;}
.huwabc-inspector .huwabc-field{font-size:12px;min-width:100px}
.huwabc-inspector .huwabc-input,.huwabc-inspector .huwabc-select{font-size:13px;padding:5px 7px;min-height:32px}
.huwabc-inspector .huwabc-selection-label{font-size:12px;margin:7px 0}
.huwabc-context-common{display:flex;gap:6px;align-items:center;margin:7px 0 0}
.huwabc-context-meta .huwabc-field{margin:5px 0 8px}
.huwabc-context-meta-help{font-size:11px;line-height:1.4;color:#5f766d;margin:5px 0 8px}
.huwabc-context-error{font-size:12px;color:#a32727;margin-top:5px;}
.huwabc-context-error:empty{display:none}
.huwabc-selection [hidden]{display:none!important}
.huwabc-editable-text{cursor:text;touch-action:manipulation}
.huwabc-editable-text:hover{fill:#267765!important}
.huwabc-editable-text:focus-visible{outline:2px solid #267765;outline-offset:4px}
.huwabc-editable-text.huwabc-meta-selected{fill:#c33d25!important}
.huwabc-piano-follow-choice{max-width:100%;font-weight:650}
.huwabc-piano-voice{max-width:180px;min-width:110px}
.huwabc-piano .huwabc-piano-settings{align-items:center}
.huwabc-page[data-page-index].huwabc-page-active>.huwabc-page-folio{font-weight:700;color:#236e5e}
@media(max-width:700px){.huwabc-inspector{border-radius:12px;padding:7px 9px}.huwabc-inspector-head>strong{font-size:11px}.huwabc-inspector .huwabc-btn{min-height:34px}.huwabc-inspector .huwabc-context-common{gap:6px}}
@media print{.huwabc-inspector{display:none!important}}
/* 0.3.25: compact fields in the same green card, both inline and floating. */
.huwabc-selection{box-sizing:border-box;min-width:0;max-width:100%}
.huwabc-selection .huwabc-inspector-head{flex-wrap:wrap;row-gap:6px;cursor:grab;touch-action:none;margin-bottom:8px;}
.huwabc-selection[data-editor-placement=inline] .huwabc-inspector-head{cursor:default;touch-action:auto}
.huwabc-selection .huwabc-inspector-head>strong{flex:1 1 170px;font-size:12px}
.huwabc-selection .huwabc-inspector-placement{flex:0 1 160px;width:160px;max-width:100%;min-width:0;font-size:12px;padding:4px;touch-action:manipulation}
.huwabc-selection .huwabc-inspector-head select,.huwabc-selection .huwabc-inspector-head button{cursor:pointer;touch-action:manipulation}
.huwabc-selection .huwabc-selection-fields{display:flex;gap:8px;flex-wrap:wrap;align-items:end}
.huwabc-selection .huwabc-field.huwabc-pitch-field{flex:0 0 100px!important;width:100px;min-width:0!important;max-width:100px;}
.huwabc-selection .huwabc-field.huwabc-value-field{flex:1 1 170px;min-width:110px;max-width:100%}
.huwabc-selection .huwabc-field[hidden]{display:none!important}
.huwabc-inspector{background:#eff8f3;}
.huwabc-inspector .huwabc-selection{max-width:100%;}
.huwabc-entry-tools{display:flex;flex-wrap:wrap;gap:6px;align-items:end;margin:8px 0 4px;border-top:1px solid #c5ddd2;padding-top:8px}
.huwabc-entry-tools .huwabc-field{flex:0 1 115px;min-width:90px;max-width:150px}
.huwabc-entry-tools .huwabc-btn{font-size:11px;padding:5px 7px;min-height:30px}
.huwabc-entry-tools .huwabc-btn[aria-pressed=true]{background:#236e5e;color:#fff}
.huwabc-entry-status{width:100%;font-size:11px;line-height:1.4;color:#45665b;margin:3px 0 0}
.huwabc-selection .huwabc-selection-toolbar>.huwabc-select{min-width:115px;max-width:160px;flex:1 1 115px}
.huwabc-blank-options{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
.huwabc-blank-options select{width:auto;max-width:230px}
/* A ledger line is painted above the notehead; it must not steal its click. */
.huwabc-edit-preview .abcjs-ledger{pointer-events:none}
