(function(){
'use strict';
var I18n=require('$:/plugins/huwiki/abc/i18n.js');
var Voices=require('$:/plugins/huwiki/abc/voice-routing.js');
var Sequence=require('$:/plugins/huwiki/abc/audio-sequence.js');
// Use the SAME flattened sequence and conversion as the sounding buffers.
// Notated tracks come first; generated accompaniment is appended afterwards.
// Keep actual note-off times, ties, repeated occurrences, tempo and voice identity.
function compile(sequence,secondsPerWhole,voices){
 var notes=Sequence.notesFromSequence(sequence,secondsPerWhole).filter(function(n){return n.trackIndex<voices.length&&!n.percussion;});
 return {voices:voices,notes:notes,at:function(seconds,choice){
  var track=choice==='all'?-1:Number(String(choice).replace(/^voice:/,''));
  if(!Number.isFinite(seconds))return [];
  return Array.from(new Set(notes.filter(function(n){return (track<0||n.trackIndex===track)&&n.start<=seconds+0.00001&&n.end>seconds+0.00001;}).map(function(n){return n.pitch;}))).sort(function(a,b){return a-b;});
 },range:function(choice){var track=choice==='all'?-1:Number(String(choice).replace(/^voice:/,''));return notes.filter(function(n){return track<0||n.trackIndex===track;}).map(function(n){return n.pitch;});}};
}
function mount(keyboard,opts){
 opts=opts||{};var doc=keyboard.element.ownerDocument,select=doc.createElement('select'),label=doc.createElement('label'),caption=doc.createElement('span');
 label.className='huwabc-piano-follow-choice';select.className='huwabc-piano-select huwabc-piano-voice';label.appendChild(caption);label.appendChild(select);
 keyboard.element.querySelector('.huwabc-piano-settings').insertBefore(label,keyboard.element.querySelector('.huwabc-piano-settings').firstChild);
 var choice=opts.state?opts.state.get('pianoVoice','all'):'all',voices=[],compiled=null,source='',clock=0,annotation=false,disposed=false;
 function tr(da,en){return (typeof opts.getLanguage==='function'?opts.getLanguage():I18n.language(opts.wiki))==='da'?da:en;}
 function text(){caption.textContent=tr('Vis toner fra ','Show notes from ');select.setAttribute('aria-label',tr('Vis toner fra','Show notes from'));}
 function options(){text();select.textContent='';var all=doc.createElement('option');all.value='all';all.textContent=tr('Alle noterede stemmer','All notated voices');select.appendChild(all);voices.forEach(function(v){var o=doc.createElement('option');o.value='voice:'+v.index;o.textContent=v.name+(v.isPercussion?tr(' (slagtøj)',' (percussion)'):'');select.appendChild(o);});
  if(!Array.from(select.options).some(function(o){return o.value===choice;}))choice='all';select.value=choice;
 }
 function showCaption(value){if(opts.caption)opts.caption.textContent=value;}
 function paint(){if(disposed||!compiled||annotation)return;keyboard.setActive(compiled.at(clock,choice));var v=voices.find(function(v){return 'voice:'+v.index===choice;});showCaption(tr('Noterede toner: ','Notated notes: ')+(v?v.name:tr('alle stemmer','all voices')));}
 function setRange(){if(compiled){var notes=compiled.range(choice);if(notes.length)keyboard.setRange(Math.min.apply(null,notes),Math.max.apply(null,notes));}}
 function ready(controller){
  if(disposed||!controller||!controller.visualObj||!controller.midiBuffer||!controller.midiBuffer.flattened)return;
  var visual=controller.visualObj,spw=visual.millisecondsPerMeasure()*100/(controller.warp||100)/1000/visual.getBarLength();
  compiled=compile(controller.midiBuffer.flattened,spw,voices);annotation=false;clock=Math.max(0,Number(controller.percent)||0)*(controller.timer?controller.timer.lastMoment:0)/1000;
  setRange();paint();
 }
 function setSource(ABC,next){if(next===source&&voices.length)return;source=String(next||'');voices=Voices.describe(ABC,source);compiled=null;annotation=false;clock=0;options();keyboard.clear();}
 function at(ms){if(!compiled||disposed)return;clock=Math.max(0,Number(ms)||0)/1000;if(annotation)setRange();annotation=false;paint();}
 function explain(notes,title){annotation=true;if(notes.length)keyboard.setRange(Math.min.apply(null,notes),Math.max.apply(null,notes));keyboard.setActive(notes);showCaption(title||tr('Valgte toner','Selected notes'));}
 select.addEventListener('change',function(){choice=select.value;annotation=false;if(opts.state)opts.state.set('pianoVoice',choice);setRange();paint();});
 options();
 return {setSource:setSource,ready:ready,at:at,explain:explain,clear:function(){annotation=false;clock=0;keyboard.clear();},refresh:paint,
  destroy:function(){disposed=true;label.remove();},info:function(){return {voice:choice,seconds:clock,voices:voices,notes:compiled?compiled.at(clock,choice):[],intervals:compiled?compiled.notes.length:0};}};
}
exports.compile=compile;exports.mount=mount;
})();
