(function(){
'use strict';
var VoiceNames=require('$:/plugins/huwiki/abc/voice-names.js');
// Preserve source bytes outside the chosen header value. No title matching or
// blind text replacement: repeated voice labels always address a V: identifier.
function headers(source,code){
 var found=[],offset=0,body=false,block=null;
 (String(source).match(/[^\r\n]*(?:\r\n|\r|\n|$)/g)||[]).forEach(function(raw){
  var line=raw.replace(/[\r\n]+$/,''),begin=/^\s*%%begin([a-z]+)/i.exec(line);
  if(block){if(new RegExp('^\\s*%%end'+block+'\\b','i').test(line))block=null;offset+=raw.length;return;}
  if(begin){block=begin[1];offset+=raw.length;return;}
  if(/^\s*K:/.test(line))body=true;
  var m=!body&&new RegExp('^([ \\t]*'+code+':[ \\t]*)(.*)$').exec(line);
  if(m){var value=m[2],end=value.length;for(var i=0;i<value.length;i++){if(value[i]==='\\'){i++;continue;}if(value[i]==='%'){end=i;break;}}
   var clean=value.slice(0,end).replace(/\s+$/,'');found.push({start:offset+m[1].length,end:offset+m[1].length+clean.length,value:clean});}
  offset+=raw.length;
 });return found;
}
function bind(root,source,map){
 var out=[],title=headers(source,'T'),composer=headers(source,'C'),voices=VoiceNames.scan(source),items=map?map.items:[];
 function attach(node,entry){if(!node||!entry)return;entry.node=node;node.setAttribute('data-huwabc-meta',entry.key);node.setAttribute('role','button');node.setAttribute('tabindex','0');node.classList.add('huwabc-editable-text');out.push(entry);}
 if(title.length)root.querySelectorAll('.abcjs-title').forEach(function(node){attach(node,Object.assign({key:'header:T',kind:'title',code:'T'},title[0]));});
 // Multiple C: fields can be joined by the renderer. Refuse an ambiguous target.
 if(composer.length===1)root.querySelectorAll('.abcjs-composer').forEach(function(node){attach(node,Object.assign({key:'header:C',kind:'composer',code:'C'},composer[0]));});
 root.querySelectorAll('.abcjs-voice-name').forEach(function(node){
  var match=String(node.getAttribute('class')||'').match(/\babcjs-v(\d+)\b/);if(!match)return;
  var cls='abcjs-v'+match[1],svg=node.ownerSVGElement,ids=[];
  items.forEach(function(item){if(item.kind!=='note')return;(item.nodes||[]).forEach(function(n){var parent=n.closest('.abcjs-note');if(n.ownerSVGElement===svg&&parent&&parent.classList.contains(cls)&&item.event.rawVoice&&ids.indexOf(item.event.rawVoice)<0)ids.push(item.event.rawVoice);});});
  if(ids.length!==1)return;var voice=voices.find(function(v){return v.id===ids[0];});if(!voice)return;
  var attrs=voice.record.attrs.filter(function(a){return ['name','nm','subname','sname','snm'].indexOf(a.key)>=0;});
  // The floating editor changes both long and short names. Highlight their
  // actual source attributes, not the notes/clef or the whole V: declaration.
  var ranges=attrs.length?attrs.map(function(a){return {start:a.start,end:a.end};}):[{start:voice.record.end,end:voice.record.end}];
  attach(node,{key:'voice:'+voice.id,kind:'voice',id:voice.id,name:voice.name,short:voice.short,start:ranges[0].start,end:ranges[0].end,ranges:ranges,value:voice.name});
 });return out;
}
function apply(source,entry,values){
 if(!entry)throw new Error('Vælg først en tekst i noderne.');
 if(entry.kind==='voice')return VoiceNames.apply(source,[{id:entry.id,name:values.name,short:values.short}]);
 var all=headers(source,entry.code),h=all[0];if(!h||(entry.code==='C'&&all.length!==1))throw new Error('Teksten kan ikke kobles sikkert til kilden. Brug ABC-feltet.');
 var value=String(values.value||'');if(/[\r\n]/.test(value))throw new Error('Brug én tekstlinje.');
 if(entry.code==='T'&&!value.trim())throw new Error('Titlen må ikke være tom.');
 // % starts an ABC comment. Keep it literal in a header edit.
 var escaped='',slashes=0;for(var i=0;i<value.length;i++){var ch=value[i];if(ch==='%'&&slashes%2===0)escaped+='\\';escaped+=ch;slashes=ch==='\\'?slashes+1:0;}value=escaped;
 return {source:source.slice(0,h.start)+value+source.slice(h.end),offset:function(pos){return pos>=h.end?pos+value.length-(h.end-h.start):pos;}};
}
exports.headers=headers;exports.bind=bind;exports.apply=apply;
})();
