(function(){
'use strict';
var Model=require('$:/plugins/huwiki/abc/editor-model.js');
var EPS=1e-8;
function fail(s){throw new Error(s);}
function parsed(A,s){var t=A.parseOnly(s)[0];if(!t||t.warnings&&t.warnings.length)fail('Ret ABC-fejlen i tekstfeltet før denne ændring.');return t;}
function splice(s,a,b,value){return s.slice(0,a)+value+s.slice(b);}
function result(s,edits,anchor){var list=edits.slice().sort(function(a,b){return a.start-b.start;});for(var i=1;i<list.length;i++)if(list[i].start<list[i-1].end)fail('Overlappende ændringer er ikke tilladt.');var next=s;list.slice().reverse().forEach(function(e){next=splice(next,e.start,e.end,e.value);});return {source:next,anchor:anchor,offset:function(n){return n+list.reduce(function(d,e){return d+(e.end<=n?e.value.length-(e.end-e.start):0);},0);}};}
function map(A,s){return Model.build(s,parsed(A,s));}
function eventAt(m,n){return m.events.find(function(e){return n>=e.start&&n<e.end;})||m.events.find(function(e){return e.start>=n;});}
function prefixStart(s,e){var part=s.slice(e.start,e.end);return e.start+(part.match(/^\s*/)||[''])[0].length;}
function withChord(A,s,e,value){
 value=String(value||'').trim();if(/["\r\n\\]/.test(value))fail('Skriv en becifring uden citationstegn, skråstreger bagud eller linjeskift.');
 var old=(e.chords||[])[0],edit=old?{start:old.outerStart,end:old.outerEnd,value:value?'"'+value+'"':''}:{start:prefixStart(s,e),end:prefixStart(s,e),value:value?'"'+value+'"':''};
 var r=result(s,[edit]);parsed(A,r.source);r.anchor={kind:value?'chord':e.rest?'rest':'note',start:value?edit.start+1:r.offset((e.notes[0]||e.rest||e).start)};return r;
}
function lineAt(s,n){var a=s.lastIndexOf('\n',Math.max(0,n-1))+1,b=s.indexOf('\n',n);return {start:a,end:b<0?s.length:b,text:s.slice(a,b<0?s.length:b)};}
function lyricSlots(text,offset){
 var slots=[],i=0;while(i<text.length){var c=text[i];if(c==='%')break;if(/\s|[-]/.test(c)){i++;continue;}if(c==='|')fail('Indsætning i sangtekst med taktstreger foretages foreløbig i ABC-kilden.');
 var a=i;if(c==='*'||c==='_'){i++;slots.push({start:offset+a,end:offset+i,value:c});continue;}
 while(i<text.length&&!/[\s\-_*|%]/.test(text[i])){if(text[i]==='\\'&&i+1<text.length)i+=2;else i++;}if(i===a)fail('Denne sangtekst skal redigeres i ABC-kilden.');slots.push({start:offset+a,end:offset+i,value:text.slice(a,i)});
 }return slots;
}
function withLyric(A,s,e,value,verse){
 verse=Number(verse)||0;if(verse<0||verse>7)fail('Vælg et vers fra 1 til 8.');
 if(!e.notes.length)fail('Sangstavelser knyttes til toner, ikke pauser. Vælg først en node.');
 var v=String(value||'').trim();if(/[\r\n%]/.test(v))fail('Skriv én sangstavelse uden linjeskift eller procenttegn.');
 var known=(e.lyrics||[]).find(function(x){return x.verse===verse;});
 if(known){var rr=result(s,[{start:known.start,end:known.end,value:v?Model.lyricEncode(v):'*'}]),beforeKnown=map(A,s),afterKnown=map(A,rr.source),eventIndex=beforeKnown.events.findIndex(function(x){return x.start===e.start;});
  beforeKnown.events.forEach(function(ev,i){(ev.el.lyric||[]).forEach(function(ly,j){if(i===eventIndex&&j===verse)return;var now=afterKnown.events[i]&&afterKnown.events[i].el.lyric&&afterKnown.events[i].el.lyric[j];if(ly.syllable&&(!now||now.syllable!==ly.syllable||now.divider!==ly.divider))fail('Ændringen ville flytte en anden sangstavelse. Brug ABC-kilden her.');});});
  var target=afterKnown.events[eventIndex],lyric=target.lyrics.find(function(x){return x.verse===verse;});rr.anchor=lyric?{kind:'lyric',start:lyric.start}:{kind:'note',start:target.notes[0].start};return rr;
 }
 var m=map(A,s),line=lineAt(s,e.notes[0].start),evs=m.events.filter(function(x){return x.start>=line.start&&x.start<=line.end;});
 if(evs.some(function(x){return x.rawVoice!==e.rawVoice;}))fail('Indsæt sangtekst i ABC-kilden, når flere stemmer deler samme kodelinje.');
 var notes=evs.filter(function(x){return x.notes.length;}),index=notes.findIndex(function(x){return x.start===e.start;});if(index<0)fail('Sangtekstens node blev ikke fundet.');
 var lyrics=[],pos=line.end<s.length?line.end+1:line.end;
 while(pos<s.length){var l=lineAt(s,pos);if(/^w:/.test(l.text)){lyrics.push(l);pos=l.end<s.length?l.end+1:l.end;}else if(/^\s*(%|$)/.test(l.text)){if(l.end>=s.length)break;pos=l.end+1;}else break;}
 var token=v?Model.lyricEncode(v):'*',edits=[];
 if(lyrics[verse]){var l=lyrics[verse],prefix=l.text.match(/^w:\s*/)[0].length,slots=lyricSlots(l.text.slice(prefix),l.start+prefix);
  if(slots.length>notes.length)fail('Sangtekstens rytme er tvetydig. Ret denne linje i ABC-kilden.');
  if(slots[index]){if(slots[index].value==='_')fail('Dette sted forlænger en sangstavelse. Ret forlængelsen i ABC-kilden først.');edits.push({start:slots[index].start,end:slots[index].end,value:token});}
  else{var end=l.start+prefix+(l.text.slice(prefix).indexOf('%')>=0?l.text.slice(prefix).indexOf('%'):l.text.length-prefix),pad=' '+Array(Math.max(0,index-slots.length)).fill('*').concat([token]).join(' ');edits.push({start:end,end:end,value:pad+' '});}
 }else{
  var extra='';for(var n=lyrics.length;n<=verse;n++)extra+='\nw: '+(n===verse?Array(index).fill('*').concat([token]).join(' '):'*');
  var end=lyrics.length?lyrics[lyrics.length-1].end:line.end;edits.push({start:end,end:end,value:extra});
 }
 var r=result(s,edits),after=map(A,r.source),newEv=after.events[m.events.findIndex(function(x){return x.start===e.start;})];
 if(v&&(!newEv||!newEv.lyrics.some(function(x){return x.verse===verse&&Model.lyricDisplay(x.value)===v;})))fail('Sangstavelsen kunne ikke placeres sikkert. Brug ABC-kilden her.');
 // No unrelated lyric may move to a different note, even in unusual imported ABC.
 m.events.forEach(function(old,i){if(old===e||old.start===e.start)return;(old.el.lyric||[]).forEach(function(ly,j){var now=after.events[i]&&after.events[i].el.lyric&&after.events[i].el.lyric[j];if(ly.syllable&&(!now||now.syllable!==ly.syllable||now.divider!==ly.divider))fail('Ændringen ville flytte en anden sangstavelse. Brug ABC-kilden her.');});});
 var li=newEv&&newEv.lyrics.find(function(x){return x.verse===verse;});r.anchor=li?{kind:'lyric',start:li.start}:{kind:'note',start:newEv.notes[0].start};return r;
}
function unitAt(s,e,A){
 var prefix=s.slice(0,e.start),re=/(?:^|\n)L:\s*(\d+)\s*\/\s*(\d+)|\[L:\s*(\d+)\s*\/\s*(\d+)\s*\]/g,m,value=null;
 while((m=re.exec(prefix)))value=Number(m[1]||m[3])/Number(m[2]||m[4]);
 if(value!==null&&value>0)return value;
 return parsed(A,s).getBarLength()<.75?1/16:1/8;
}
function suffix(r){if(!Number.isFinite(r)||r<=0)fail('Ugyldig nodelængde.');var den=1;while(Math.abs(r*den-Math.round(r*den))>EPS&&den<4096)den*=2;if(Math.abs(r*den-Math.round(r*den))>EPS)fail('Denne rytme kræver redigering i ABC-kilden.');var num=Math.round(r*den);while(den>1&&num%2===0){num/=2;den/=2;}return den===1?(num===1?'':String(num)):(num===1?'':num)+'/'+den;}
function simple(s,e){
 var raw=s.slice(e.start,e.end),start=prefixStart(s,e),part=s.slice(start,e.end),ch=/^(?:"(?:\\.|[^"\\])*"\s*)*/.exec(part)[0];start+=ch.length;part=s.slice(start,e.end);
 var m=/^((?:\^{1,2}|_{1,2}|=)?[A-Ga-g][,']*|[zx])(\d*(?:\/+\d*)?)(\s*)$/.exec(part);
 if(!m||e.notes.length>1||e.el.startTriplet||e.el.tripletMultiplier||e.el.decoration||e.el.startSlur||e.el.endSlur||(e.el.pitches||[]).some(function(p){return p.startTie||p.endTie||p.startSlur||p.endSlur;}))fail('Denne figur har akkordtoner, buer eller særlig rytme. Ret længden i ABC-kilden.');
 return {start:start,end:e.end-m[3].length,token:m[1],suffix:m[2]};
}
function preservePitches(A,before,changed,resultData){
 var current=resultData.source,after=map(A,current),edits=[];
 before.items.filter(function(i){return i.kind==='note'&&i.event!==changed;}).forEach(function(n){var at=resultData.offset(n.start),other=after.items.find(function(x){return x.kind==='note'&&x.start===at;});if(!other)fail('En anden node ville blive ændret.');if(other.midi!==n.midi){var a=n.midi-(n.transpose||0)-Model.midi(n.pitch.d,0),p=a===0?'=':a>0?'^'.repeat(a):'_'.repeat(-a);edits.push({start:at,end:other.end,value:p+Model.name(n.pitch.d)});}});
 var extra=result(current,edits),offset=resultData.offset;resultData.source=extra.source;resultData.offset=function(n){return extra.offset(offset(n));};return resultData;
}
function write(A,s,e,pitch,duration){
 var m=map(A,s),old=m.events.find(function(x){return x.start===e.start;});if(!old)fail('Vælg positionen igen.');var sp=simple(s,old),unit=unitAt(s,old,A),dur=Number(duration),original=old.el.duration;
 if(!Number.isFinite(dur)||dur<=0||dur>4)fail('Vælg en gyldig nodelængde.');
 if(pitch!=='z'&&!Model.pitch(pitch))fail('Ugyldig tone.');
 if(Math.abs((sp.suffix?lengthOf(sp.suffix):1)*unit-original)>EPS)fail('Trioler og brudt rytme redigeres foreløbig i ABC-kilden.');
 var available=original,end=sp.end,consumed=[];
 if(dur>available+EPS){var following=m.events.filter(function(x){return x.voice===old.voice&&x.start>old.start;});for(var i=0;i<following.length&&available+EPS<dur;i++){var ev=following[i],gap=s.slice(end,ev.start);if(/[|:\n]/.test(gap)||!ev.rest||ev.chords.length)break;var ss;try{ss=simple(s,ev);}catch(ignore){break;}available+=ev.el.duration;end=ss.end;consumed.push(ev);}}
 if(dur>available+EPS)fail('Der er ikke plads til længden her uden at ændre næste node eller takt.');
 if(pitch==='z'&&old.lyrics.length)fail('Fjern sangstavelsen før noden ændres til en pause.');
 var rest=available-dur,next=pitch+suffix(dur/unit)+(rest>EPS?' z'+suffix(rest/unit):''),r=result(s,[{start:sp.start,end:end,value:next}]);
 r=preservePitches(A,m,old,r);var a=map(A,r.source),idx=m.events.indexOf(old),newEv=a.events[idx];
 // Time occupied by the replacement must be identical; all following music retains timing.
 var sum=a.events.filter(function(x){return x.voice===old.voice;}).reduce(function(n,x){return n+x.el.duration;},0),prev=m.events.filter(function(x){return x.voice===old.voice;}).reduce(function(n,x){return n+x.el.duration;},0);
 if(Math.abs(sum-prev)>EPS)fail('Ændringen ville forskyde musikkens tid.');
 // Adding rests beside a lyrical note must not shift any following syllables.
 m.events.filter(function(x){return x.notes.length&&x!==old;}).forEach(function(ev){var n=a.events.find(function(x){return x.notes.some(function(y){return y.start===r.offset(ev.notes[0].start);});});if(n&&JSON.stringify(ev.el.lyric||[])!==JSON.stringify(n.el.lyric||[]))fail('Længdeændringen ville forskyde sangteksten.');});
 r.anchor={kind:pitch==='z'?'rest':'note',start:(newEv.notes[0]||newEv.rest).start};r.nextEventIndex=idx+1;return r;
}
function lengthOf(s){var m=/^(\d*)(\/*)(\d*)$/.exec(s);if(!m)fail('Ugyldig længde.');return (m[1]?Number(m[1]):1)/(m[3]?Number(m[3]):Math.pow(2,m[2].length));}
function appendMeasure(A,s){
 var tune=parsed(A,s),m=map(A,s),voices={};
 if(/(?:^|\n)M:.*\n[\s\S]*(?:^|\n)M:|\[M:/.test(s))fail('Tilføj takten i ABC-kilden ved taktartsskift.');
 (tune.lines||[]).forEach(function(l){(l.staff||[]).forEach(function(st,si){(st.voices||[]).forEach(function(v,vi){var k=si+':'+vi;(voices[k]||(voices[k]=[])).push.apply(voices[k],v);});});});
 var totals=Object.keys(voices).map(function(k){return voices[k].filter(function(x){return x.el_type==='note';}).reduce(function(n,x){return n+x.duration;},0);});
 if(totals.some(function(n){return Math.abs(n-totals[0])>EPS;}))fail('Stemmerne har forskellig længde. Afslut dem i ABC-kilden før en fælles takt tilføjes.');
 var edits=[],bar=tune.getBarLength();
 Object.keys(voices).forEach(function(k){var v=voices[k],lastNote=v.filter(function(x){return x.el_type==='note';}).pop(),last=v.filter(function(x){return x.el_type==='bar';}).pop(),ev=m.events.find(function(x){return x.start===lastNote.startChar;});
  if(!ev||!last||last.startChar<lastNote.startChar)fail('Afslut sidste takt med en taktstreg i ABC-kilden først.');
  if(Math.abs(totals[0]/bar-Math.round(totals[0]/bar))>EPS)fail('Afslut den ufuldstændige takt først.');
  var token='z'+suffix(bar/unitAt(s,ev,A)),value=last.type==='bar_thin_thick'?'| '+token+' |]':s.slice(last.startChar,last.endChar)+' '+token+' |';
  edits.push({start:last.startChar,end:last.endChar,value:value});
 });var r=result(s,edits);parsed(A,r.source);return r;
}
function starter(title,meter,kind){
 meter=/^(?:2\/4|3\/4|4\/4|5\/4|6\/8|7\/8|9\/8|11\/8)$/.test(meter)?meter:'4/4';var f=meter.split('/'),n=Number(f[0])*8/Number(f[1]),rest='z'+suffix(n),bars=Array(4).fill(rest).join(' | ')+' |]';
 var h='X:1\nT:'+String(title||'').replace(/[\r\n]/g,' ')+'\nM:'+meter+'\nL:1/8\nQ:1/4=100\n';
 if(kind==='voices')return h+'%%score (1 2)\nV:1 name="1" stem=up\nV:2 name="2" stem=down\nK:C\nV:1\n'+bars+'\nV:2\n'+bars;
 if(kind==='staves')return h+'%%score {1 2}\nV:1 name="1" clef=treble\nV:2 name="2" clef=bass\nK:C\nV:1\n'+bars+'\nV:2\n'+bars;
 return h+'K:C\n'+bars;
}
exports.map=map;exports.eventAt=eventAt;exports.chord=withChord;exports.lyric=withLyric;exports.write=write;exports.appendMeasure=appendMeasure;exports.starter=starter;exports.suffix=suffix;
})();
"},"HUWiki ABC – Nodeindtastning":{"title":"HUWiki ABC – Nodeindtastning","type":"text/vnd.tiddlywiki","tags":"[[HUWiki ABC]] Hjælp","text":"{{||$:/plugins/huwiki/abc/LocalizedBody}}","huwiki-title-da":"ABC – Nodeindtastning","huwiki-title-en":"ABC – Note entry","huwiki-text-da":"! Skriv musik fra et tomt nodeark

Åbn [[ABC-nodeværksted|HUWiki ABC – Nodeværksted]]. Vælg ''En stemme'', ''To stemmer på samme system'' eller ''To nodesystemer'', vælg taktart, og tryk ''Ny tom melodi''. Den nye redigeringskladde indeholder fire takter med pauser. Eksisterende musik ændres ikke.

!! Indtast noder og pauser

Klik på en pause og vælg ''Skriv noder'' i det grønne kort. Standardlængden er en fjerdedel. Klik på klaviaturet eller brug A–G. Bogstaverne følger ABC: B er internationalt B, altså dansk H. Klaviaturet bruger wikiens valgte tonenavne.

* 1 = helnode; 2 = halvnode; 3 = fjerdedel; 4 = ottendedel; 5 = sekstendedel.
* 0 eller ''Pause'' skriver en pause med den valgte længde.
* ← og → vælger en anden position i den aktive stemme.
* Når en pause udfyldes, bliver resterende tid stående som en pause. Markøren går videre. En ny takt tilføjes efter behov ved slutningen.
* ''+ Takt'' tilføjer en fælles takt efter det eksisterende stykke. Alle noterede stemmer får den nye takt.
* ''Stop nodeindtastning'' går tilbage til almindelig markering og rettelse.

Der indsættes ikke ekstra tid foran eksisterende toner. En længere tone må kun bruge den valgte position og umiddelbart følgende enkle pauser i samme takt. Andre toner og taktgrænser overskrives ikke.

!! Vælg og ret

Uden nodeindtastning ændrer tonefeltet den valgte tone. Ved en pause kan tonefeltet erstatte pausen med en tone af samme længde. Ændring af længden bevarer takternes varighed; en forkortelse efterlader pauseplads.

↑ og ↓ flytter diatonisk med hensyn til tonearten. Shift+↑ og Shift+↓ flytter en halv tone. Fortegn, der ellers ville ændre senere toner, suppleres med nødvendige opløsningstegn. Genvejene gælder ikke, når et tekstfelt eller en rullemenu har fokus.

Klik på en tone i en anden stemme, eller vælg ''Stemme'' i kortet. Stemmevalget går til omtrent samme tidspunkt i den valgte stemme. Nye ark kan allerede begynde med to stemmer på samme nodesystem (op/ned) eller to separate systemer; tilføjelse af flere stemmer til et eksisterende ark er ikke et nyt værktøj i denne testversion.

!! Becifringer og sangstavelser

Vælg en node eller pause og skift til ''Becifringer''. Markeringen bliver ved samme position. Skriv en becifring og vælg ''Anvend'' eller Enter. Et tomt felt fjerner becifringen.

Vælg en node og skift til ''Sangstavelser''. Skriv én stavelse ad gangen; ← og → går til positioner i samme stemme. Manglende tidligere stavelser udfyldes med ABC's *-pladsholdere. ''Vers'' vælger mellem op til otte vers. Sangstavelser på pauser tilbydes ikke. Forbindelser mellem stavelser, melismer og automatisk fordeling af en hel sangtekst er endnu ikke grafiske værktøjer.

!! Ved koden eller ved noderne

Klik på en node, pause eller becifring i ABC-feltet: Det samme kort arbejder med den tilsvarende musikalske position. Du kan også skrive kilden direkte. Tastaturgenveje indsætter ikke noder, mens du skriver i tekstfeltet.

Placeringen vælges øverst i selve det grønne kort: ''Følg markeringen'', ''Fast placering'' eller ''Ved ABC-koden''. Træk i kortets overskrift for at placere det frit; det skifter da til fast placering. Tonefeltet har en kompakt bredde i begge visninger. Placeringen er midlertidig visningstilstand, ikke en ændring af musikken.

!! Fortryd, gem og afgrænsning

Anvendte ændringer deler den eksisterende Fortryd/Gentag-historik. Esc annullerer en uanvendt indtastning i kortet; det skal ikke lukke hele kladden. Gem med tiddlerens sædvanlige flueben.

Denne første indtastningsversion er forsigtig med importeret musik. Varighedsændringer i akkordklange, trioler, bindebuer, brudt rytme og andre sammensatte figurer henvises til ABC-feltet. Ved taktartsskift eller uens stemmelængder skal nye takter foreløbig tilføjes i koden. Der er endnu ikke nye grafiske værktøjer til tempo, nøgle, toneart, formdele, bjælker, gentagelsestegn og volter.
","huwiki-text-en":"! Write music from a blank score

Open [[ABC score workshop|HUWiki ABC – Nodeværksted]]. Choose ''One voice'', ''Two voices on one staff'' or ''Two staves'', select a meter, and press ''New blank tune''. A new draft opens with four measures filled with rests. Existing music is unchanged.

!! Enter notes and rests

Select a rest and enable ''Enter notes'' in the green card. The initial duration is a quarter note. Click a piano key or use A–G. Letter keys use ABC's international note names; B is Danish H. The piano labels follow the wiki language.

* 1 = whole; 2 = half; 3 = quarter; 4 = eighth; 5 = sixteenth.
* 0 or ''Rest'' enters a rest with the chosen duration.
* ← and → move between positions in the active voice.
* Notes replace rest space, leaving unused time as a rest. The cursor advances. At the end, another measure is appended as needed.
* ''+ Measure'' appends a shared measure to all notated voices.
* ''Stop note entry'' returns to selection and editing.

Entry does not insert extra time before existing notes. A longer note can consume only the selected position and immediately following simple rests within the same measure. Other notes and barlines are not overwritten.

!! Select and edit

Outside note-entry mode, the pitch field changes the selected pitch. For a rest, choosing a pitch replaces the rest with a note of the same duration. Shortening a note leaves rest space and preserves measure duration.

↑ and ↓ move diatonically, respecting the key signature. Shift+↑ and Shift+↓ move by a semitone. Accidentals are adjusted where necessary to preserve other pitches. Musical shortcuts do not intercept text fields or select menus.

Select a note in another voice, or use ''Voice'' in the card to move to approximately the same musical time in that voice. New scores can start with two voices on one staff (stems up/down) or two separate staves. Adding voices to existing scores is not a new feature in this test version.

!! Chord symbols and syllables

Select a note or rest and choose ''Chord symbols''. The position stays selected. Enter a symbol and press Apply or Enter. An empty value removes the symbol.

Select a note and choose ''Lyric syllables''. Enter one syllable at a time; ← and → move between positions in the same voice. Earlier empty positions receive ABC * placeholders. ''Verse'' chooses up to eight verses. Rests cannot receive syllables. Hyphenation, melismas and automatic distribution of whole lyric lines are not new graphical tools in this version.

!! Work in the score or beside the source

Click a note, rest or chord in the ABC source: the same card edits the corresponding musical position. Direct ABC typing remains available. Note-entry shortcuts do not run while typing in a text field.

Choose ''Follow selection'', ''Fixed position'' or ''By ABC source'' at the top of the green card. Drag its heading to position it freely; dragging switches to fixed placement. The pitch field is compact in both locations. Placement is session UI state, not part of the music.

!! Undo, save and scope

Applied edits share the existing Undo/Redo history. Escape cancels an uncommitted card edit without discarding the whole draft. Save with the tiddler's normal checkmark.

This first entry version is conservative with imported notation. Edit duration in ABC for chord clusters, tuplets, ties, broken rhythms and other compound figures. Add measures in ABC when meters change or voices have unequal lengths. New graphical tools for tempo, clefs, keys, part markers, beams, repeats and endings are not included yet.
